(window.GIM_TS=window.GIM_TS||{})["Eruvin.1"]={"from":24,"a":[["על מה שאמרו חכמים במשנה שרוחב הקורה די שיהא \u0003טפח,\u0004 תוהים: הלא \u0003טפח ומחצה בעי\u0004 \u0005[צריך]!\u0006 שהרי האריח, שהוא חצי לבנה בת שלשה טפחים רחב טפח ומחצה!","ועונים: \u0003כיון\u0004 ש\u0003רחב לקבל טפח, אידך חצי טפח מלבין ליה בטינא, משהו מהאי גיסא ומשהו מהאי גיסא, וקיימא\u0004 \u0005[את חצי הטפח האחר מדביק אותו בטיט, משהו מצד זה ומשהו מצד זה, ועומד\u0006 האריח במקומו\u0005]\u0006.","\u0003אמר רבה בר רב הונא: קורה שאמרו — צריכה שתהא בריאה כדי לקבל אריח\u0004, אולם \u0003מעמידי קורה\u0004 שהקורה נשענת עליהם, הם עצמם \u0003אינן צריכין שיהיו בריאין כדי לקבל קורה ואריח\u0004 שעל גביה, שלא נתנו כל שיעור במעמידי הקורה אלא בה עצמה, שרק היא עצמה עשויה להכשיר מבוי. \u0003ורב חסדא אמר אחד זה ואחד זה צריכין שיהיו בריאין כדי לקבל קורה ואריח.\u0004","\u0003אמר רב ששת: הניח קורה על גבי מבוי, ופרס עליה מחצלת\u0004 המשתלשלת למטה \u0003והגביה\u0004 שולי המחצלת \u0003מן הקרקע\u0004 במבוי \u0003שלשה\u0004 טפחים, הרי \u0003קורה אין כאן מחיצה אין כאן. קורה אין כאן\u0004 שאינה ראויה להכשיר \u0003 דהא מיכסיא\u0004 כיון שהיא מכוסה ואינה ניכרת, ואף \u0003מחיצה אין כאן: דהויא לה\u0004 \u0005[שהרי היא]\u0006 \u0003מחיצה שהגדיים בוקעין\u0004 (יכולים לעבור) \u0003בה\u0004, שהרי היא גבוהה מהקרקע שלשה טפחים ולכן אין בה דין מחיצה.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים\u0006 בתוספתא\u0005]:\u0006 \u0003קורה היוצאה מכותל זה ואינה נוגעת בכותל זה\u0004 שכנגדו, \u0003וכן שתי קורות אחת יוצאה מכותל זה ואחת יוצאה מכותל זה ואינן נוגעות זו בזו,\u0004 אם היו \u0003פחות משלשה\u0004 טפחים זו לזו או לכותל — \u0003אין צריך להביא קורה אחרת\u0004 להתיר את המבוי, שמשום דין \"לבוד\" הרי הן כצמודות. אבל אם היו \u0003שלשה\u0004 טפחים — \u0003צריך להביא קורה אחרת.\u0004","\u0003רבן שמעון בן גמליאל אומר: פחות מארבעה\u0004 טפחים \u0003אין צריך להביא קורה אחרת, ארבעה — צריך להביא קורה אחרת\u0004 שלדעתו דין לבוד עד ארבעה טפחים.","\u0003וכן שתי קורות המתאימות\u0004 שהיו מקבילות זו לזו אולם היו דקות ביותר, \u0003לא בזו כדי לקבל אריח ולא בזו כדי לקבל אריח, אם מקבלת\u0004 יחידה זו המאוחדת משתי קורות יחד \u0003אריח לרחבו\u0004 שהוא \u0003טפח — אין צריך להביא קורה אחרת\u0004 להתיר, \u0003ואם לאו — צריך להביא קורה אחרת.\u0004","\u0003רבן שמעון בן גמליאל אומר: אם מקבלות\u0004 שתיהן \u0003אריח לארכו\u0004 שהוא \u0003שלשה\u0004 טפחים — \u0003אין צריך להביא קורה אחרת, ואם לאו — צריך להביא קורה אחרת.\u0004","\u0003היו\u0004 שתי קורות דקות אלה \u0003אחת למעלה ואחת למטה, ר' יוסי בר' יהודה אומר: רואין את העליונה כאילו היא למטה, ואת התחתונה כאילו היא למעלה\u0004 והן קרובות זו לזו, ואם היו שתיהן יחד ראויות לקבל אריח הרי הן מתירות, אף שבפועל אינן סמוכות, \u0003ובלבד שלא תהא עליונה\u0004 שבהן \u0003למעלה מעשרים אמה ותחתונה למטה מעשרה\u0004 טפחים, שמתחילה אינן מצויות בתוך תחום היתר מבוי.","\u0003אמר אביי: ר' יוסי בר' יהודה סבר לה כאבוה בחדא, ופליג עליה בחדא\u0004 \u0005[סבר כאביו ב\u0006דבר \u0005אחד וחלק עליו באחד]\u0006 ומבאר: \u0003סבר לה כאבוה בחדא\u0004 \u0005[סבר כאביו ב\u0006דבר \u0005אחד] —\u0006 \u0003דאית ליה\u0004 \u0005[שיש לו]\u0006 \u0003רואין,\u0004 שמחזיק בעקרון כשם שר' יהודה אביו סבר במשנה שרואים את הקורה כאילו היא בריאה, אף על פי שאינה כזו, כך גם אמר הבן, ר' יוסי, שרואים את שתי הקורות כאילו היו צמודות זו לזו.","ואולם ר' יוסי גם \u0003פליג עליה בחדא\u0004 \u0005[חלק עליו ב\u0006דבר \u0005אחד]\u0006 ש\u0003אילו ר' יהודה סבר\u0004 שהקורה שבדיוננו מתירה את המבוי אף כשהיא \u0003למעלה מעשרים\u0004 אמה, \u0003ור' יוסי בר' יהודה סבר: בתוך עשרים — אין\u0004 \u0005[כן]\u0006, מתירה. \u0003למעלה מעשרים — לא\u0004.","\u0003ג\u0004 במשנה נאמר: \u0003\"ר' יהודה אומר: רחבה אף על פי שאינה בריאה\". מתני ליה\u0004 \u0005[היה מלמדו\u0006 משנה\u0005]\u0006 \u0003רב יהודה לחייא בר רב קמיה\u0004 \u0005[לפני]\u0006 \u0003רב\u0004 בנוסח זה: קורה שאמרו — \u0003רחבה אף על פי שאינה בריאה. אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אתנייה\u0004 \u0005[השנה לו,\u0006 למדהו\u0005]\u0006 \u0003רחבה ובריאה\u0004.","ומקשים: \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003ר' אילעאי\u0004 בשם \u0003רב:\u0004 קורה \u0003רחבה ארבעה\u0004 טפחים, \u0003אף על פי שאינה בריאה\u0004 מכשירה את המבוי! ועונים: \u0003רחבה ארבעה שאני\u0004 \u0005[שונה]\u0006 שכן ברוחב ארבעה נחשבת הקורה כמקום חשוב ומחיצותיה נחשבות כסותמות, כמחיצה ממש, ולא משום היכר בלבד.","נאמר עוד במשנה: \u0003\"היתה של קש\u0004 ושל קנים — מותרת\". ושואלים: \u0003מאי קא משמע לן\u0004 \u0005[מה משמיע לנו\u0006 בזה\u0005]\u0006 \u0003דאמרינן\u0004 \u0005[שאומרים אנו]\u0006 \u0003רואין\u0004 את הקורה כאילו היא ראויה לשאת עליה אריח — הלא \u0003היינו הך\u0004 \u0005[זהו זה]!\u0006 כלומר, הרי אותם הדברים כבר נאמרו קודם לכן במשנה (\"רחבה אף על פי שאינה בריאה\")!","ומשיבים שיש בכך מקצת חידוש — \u0003מהו דתימא\u0004 \u0005[שתאמר]\u0006 \u0003במינה\u0004 באותו מין שקורה העשויה ממנו ראויה בדרך כלל לקבל אריח \u0003אמרינן\u0004 \u0005[אומרים אנו]\u0006 אפילו בקורה דקה ביותר, אולם \u0003שלא במינה\u0004 כגון בקש, שאינו ראוי כלל להחזקת אריח — \u0003לא אמרינן\u0004 \u0005[אין אנו אומרים]\u0006 רואים כאילו זה קורה ראויה לשאת אריח, לכן השמיע לנו שאין הבדל.","נאמר במשנתנו שקורה \u0003\"עקומה רואין אותה כאילו היא פשוטה\"\u0004 ומקשים: \u0003פשיטא\u0004 \u0005[פשוט,\u0006 ברור\u0005]!\u0006 ומשיבים \u0003קא משמע לן\u0004 \u0005[שהשמיע לנו בכך]\u0006 \u0003כד\u0004בריו של \u0003ר' זירא\u0004 ש\u0003אמר ר' זירא\u0004: היתה \u0003היא\u0004 הקורה \u0003בתוך המבוי ועקמומיתה חוץ למבוי, היא\u0004 הקורה \u0003בתוך עשרים\u0004 אמה \u0003ועקמומיתה למעלה מעשרים\u0004 אמה, או \u0003היא למעלה מעשרה ועקמומיתה למטה מעשרה\u0004, שהחלק העקום מצוי במקום שאין קורה מתירה בו כלל, \u0003רואין, כל שאילו ינטל\u0004 חלק \u0003עקמומיתה\u0004 המצוי מחוץ לתחום היתר הקורה ועדיין \u0003אין בין זה לזה,\u0004 בין חלקיה הראויים של הקורה, \u0003שלשה\u0004 טפחים — \u0003אין צריך להביא קורה אחרת, ואם לאו\u0004, שיש מרחק גדול מזה — \u0003צריך להביא קורה אחרת\u0004.","ושואלים: \u0003הא נמי פשיטא\u0004 \u0005[זו גם כן פשוטה]\u0006 שהרי חלק הקורה העקום עלינו לראותו כאילו הוא ישר! ומשיבים: \u0003היא בתוך מבוי, ועקמומיתה חוץ למבוי איצטריכא ליה\u0004 \u0005[נצרכה לו\u0006 לומר\u0005]\u0006 \u0003מהו דתימא: ליחוש דילמא אתי לאמשוכי בתרה\u0004 \u0005[שתאמר לחשוש שמא יבוא להימשך אחריה]\u0006 שאם בולטת הקורה מחוץ למבוי, שמא יבואו בני אדם להשתמש מחוץ למבוי תחת בליטת הקורה, על כן השמיע לנו שאין לחשוש לדבר זה.","אמרנו במשנה שקורה \u0003\"עגולה רואין אותה כאילו היא מרובעת\"\u0004. ושואלים: \u0003הא תו\u0004 \u0005[זו עוד]\u0006 \u0003למה לי,\u0004 הרי לכאורה כבר שנינו כיוצא בזה ומה צורך להוסיף כאן? ומשיבים: \u0003סיפא איצטריכא ליה\u0004 \u0005[סופו\u0006 של הדבר \u0005אני צריך לו]\u0006: אותו כלל ש\u0003כל שיש בהיקפו שלשה טפחים יש בו רוחב טפח\u0004.","ושואלים: \u0003מנא הני מילי\u0004 \u0005[מנין דברים אלה]\u0006 שכך הוא השיעור? \u0003אמר ר' יוחנן, אמר קרא\u0004 \u0005[אמר המקרא]\u0006 שנאמר בשלמה \u0003\"ויעש את הים מוצק עשר באמה משפתו עד שפתו עגל סביב וחמש באמה קומתו וקו שלשים באמה יסב אתו סביב\"\u0004 (מלכים א, ז, כג)","ומקשים: \u0003והא איכא שפתו\u0004 \u0005[והרי יש שפתו]?!\u0006 כלומר הלא נמדד הים מבפנים, ואם מודדים את היקפו מבחוץ שוב אין יחס זה מדויק.","\u0003אמר רב פפא: שפתו שפת פרח שושן כתיב ביה\u0004 \u0005[נאמר בו],\u0006 כלומר שהיתה שפתו דקה מאד, שכן נאמר: \u0003\"ועביו טפח ושפתו כמעשה שפת כוס פרח שושן אלפים בת יכיל\"\u0004 (מלכים א, ז, כו).","ושואלים: \u0003והאיכא משהו\u0004 \u0005[והרי\u0006 בכל זאת \u0005יש משהו]\u0006 של עובי השפה! ועונים: \u0003כי קא חשיב\u0004 \u0005[כאשר הוא חושב] —\u0006 גם את ההיקף \u0003מגואי, קא חשיב\u0004 \u0005[מבפנים, הוא חושב].\u0006","\u0003תניא\u0004 \u0005[שנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' חייא\u0004 אומר: \u0003ים שעשה שלמה היה מחזיק\u0004 בנפחו \u0003מאה וחמשים מקוה טהרה\u0004. ומקשים: \u0003מכדי, מקוה כמה הוי\u0004 \u0005[הינו\u0006 מה שיעורו\u0005]\u0006 — \u0003ארבעים סאה\u0004 כמו ששנינו \u0003\"ורחץ את בשרו\u0004"],["\u0003במים\"\u0004 משמעו במים המחוברים יחדיו, ואלו הם \u0003במי מקוה\u0004 בלבד. \u0003\"כל בשרו\"\u0004 משמע \u0003מים שכל גופו עולה בהן. וכמה הן — אמה על אמה ברום שלש אמות. ושיערו חכמים,\u0004 שהנפח של \u0003מי מקוה ארבעים סאה\u0004.","ואם כן \u0003כמה הוו להו\u0004 \u0005[הריהם]\u0006 שיעורי מקוה? נפח הים \u0003חמש מאה גרמידי\u0004 \u0005[אמות]\u0006 מעוקבות, שחושבים אורכו עשר אמות, רוחבו עשר אמות וגובהו חמש אמות; ואם נערוך חשבון, הרי \u0003לתלת מאה\u0004 \u0005[לשלוש מאות]\u0006 אמות מעוקבות — \u0003מאה\u0004 שיעורי מקוה, \u0003למאה וחמשין\u0004 \u0005[וחמישים]\u0006 אמות \u0005—\u0006 \u0003חמשין\u0004 \u0005[חמישים]\u0006 שיעורי מקוה\u0005,\u0006 ואם כן לחשבון זה, הרי למאה וחמישים שעורי מקוה טהרה \u0003בארבע מאה וחמשין סגיא\u0004 \u0005[וחמישים\u0006 אמות מעוקבות \u0005מספיק],\u0006 והיה הים גדול יותר בנפחו!","ועונים, כי היתה טעות בחישוב: \u0003הני מילי\u0004 \u0005[דברים אלה]\u0006 בחישוב נפחו של הים אמורים \u0003בריבועא\u0004 \u0005[בריבוע]\u0006 — אילו היו כל השיעורים בקוביה, ואולם \u0003ים שעשה שלמה עגול היה\u0004 ונפחו קטן יותר.","ועדיין שואלים: \u0003מכדי\u0004 \u0005[הרי]\u0006 \u0003כמה מרובע יתר על העגול — רביע,\u0004 ואם כן אין בנפח הים אלא ארבע מאות אמה. ואם כן, לחשבון זה הרי \u0003לארבע מאה\u0004 אמות הרי הן \u0003מאה\u0004 מקוואות לשלש מאות אמות מתוכם, ו\u0003למאה\u0004 הנותרים הרי הם — \u0003עשרים וחמשה.\u0004 ונמצא כי \u0003הני\u0004 \u0005[\u0006הרי \u0005אלו]\u0006 \u0003מאה ועשרים וחמשה\u0004 שיעורי מקוה בלבד \u0003הוו להו\u0004 \u0005[הריהם],\u0006 ולא מאה וחמישים כפי שאמרנו.","\u0003תני\u0004 \u0005[שנה\u0006 לתרץ\u0005]\u0006 \u0003רמי בר יחזקאל: ים שעשה שלמה שלש אמות תחתונות מרובעות ושתים עליונות עגולות\u0004, ולפיכך אין לחשב את שיעורו בדיוק כעיגול אלא חלקו כקוביה.","ומעירים: \u0003נהי דאיפכא לא מצית אמרת\u0004 \u0005[אמנם ההיפך אינך יכול לומר]\u0006 שחלקו העגול היה למטה שכן \u0003שפתו עגול כתיב אלא אימא חדא\u0004 \u0005[אמור\u0006 רק אמה \u0005אחת]\u0006 היתה עגולה!","ודוחים: \u0003לא סלקא דעתך\u0004 \u0005[לא יעלה על דעתך]\u0006 \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]\u0006 בים זה \"ועביו טפח ושפתו כמעשה שפת כוס פרח שושן \u0003אלפים בת יכיל\"\u0004 (מלכים א' ז, כו) \u0003בת כמה הויא\u0004 \u0005[\u0006מדת \u0005\"בת\" כמה היא]\u0006 \u0003שלש סאין\u0004 שכן נאמר \"וחק השמן הבת השמן \u0003מעשר הבת מן הכר\u0004 עשרת הבתים חמר כי עשרת הבתים חמר\" (יחזקאל מה, יד), הרי שהבת היא עשירית הכור המכיל שלושים סאים, נמצא \u0003דהוה להו שיתא אלפי גריוי\u0004 \u0005[שהיו\u0006 בים \u0005ששת אלפי סאה]\u0006 שהם בדיוק מאה וחמשים שיעורי מקוה (שהוא ארבעים סאה).","ומקשים: \u0003והא כתיב\u0004 \u0005[והרי נאמר]\u0006 על הים: \u0003\"מחזיק בתים שלשת אלפים\u0004 יכיל\u0003\"\u0004 (דברי הימים ב, ד, ה) ומשיבים: \u0003ההוא לגודשא\u0004 \u0005[זה הוא לגודש]\u0006 שאם היו שמים לתוכו דברים יבשים יכולים אנו לגדוש ולהוסיף עד שלשת אלפים בתים.","\u0003אמר אביי, שמע מינה: האי גודשא, תלתא הוי\u0004 \u0005[שמע ממנה,\u0006 למד מכאן כי \u0005גודש זה —\u0006 \u0005שליש הוא]\u0006 מן השיעור שמחזיק כלי. \u0003ותנן נמי\u0004 \u0005[ו\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003שידה\u0004 (מרכבה) \u0003תיבה ומגדל\u0004 (ארון), \u0003כוורת\u0004 הדבורים העשויה \u0003קש, וכוורת\u0004 העשויה \u0003קנים\u0004 וכלי המשמש ל\u0003בור\u0004 מי שתיה בתוך \u0003ספינה אלכסנדרית\u0004 המפליגה למרחוק, \u0003אף על פי שיש להן שולים\u0004 (בסיס) \u0003והן מחזיקות ארבעים סאה בלח, שהן כוריים ביבש — טהורין\u0004 שכלי הגדול כשיעור זה אינו נחשב כלי, וכיון שאינו מיטלטל אינו מקבל טומאה. ולפי דרכנו למדנו שהכלי המחזיק ארבעים סאה בלח מחזיק כוריים (ששים סאה) ביבש, כלומר שאפשר לגדוש על הכלי עוד שליש.","\u0003לחיין שאמרו\u0004 בתיקון המבוי — \u0003גובהן עשרה טפחים\u0004 לפחות, \u0003ורחבן ועוביין כל שהוא. ר' יוסי אומר: רחבן שלשה טפחים.\u0004","במשנה נאמר \u0003\"לחיין שאמרו כו'\"\u0004 שואלים: \u0003לימא תנן סתמא\u0004 \u0005[האם\u0006 לומר \u0005ששנינו סתם\u0006 משנה\u0005]\u0006 \u0003כ\u0004שיטת \u0003ר' אליעזר\u0004 ש\u0003אמר\u0004 שלהתיר מבוי שני \u0003לחיין בעינן\u0004 \u0005[צריכים אנו]?\u0006","ודוחים: \u0003לא\u0004, \u0003מאי\u0004 \u0005[מה]\u0006 הוא הריבוי \u0003לחיין — לחיין דעלמא\u0004 \u0005[בכלל]\u0006 לאו דוקא במבוי אחד. ומקשים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 במקום \u0003קורה נמי\u0004 \u0005[גם כן],\u0006 \u0003ניתני\u0004 \u0005[שישנה]\u0006 \u0003קורות, ו\u0004נאמר: \u0003מאי\u0004 \u0005[מהן]\u0006 \u0003קורות — קורות דעלמא\u0004 \u0005[בכלל]!\u0006","\u0003הכי קאמר\u0004 \u0005[כך אמר,\u0006 התכוון\u0005]:\u0006 \u0003אותן לחיין שנחלקו בהן ר' אליעזר וחכמים — גובהן עשרה טפחים, ורוחבן ועוביין כל שהוא. וכמה כל שהוא\u0004, \u0003תני\u0004 \u0005[שנה]\u0006 \u0003ר' חייא: אפילו כחוט\u0004 שקושרים בו \u0003הסרבל\u0004 (מעיל).","\u0003תנא\u0004 \u0005[\u0006\u0003בתוספתא\u0004 \u0005שנינו]:\u0006 \u0003עשה לחי\u0004 והעמידו בעומק כדי \u0003חצי מבוי — אין לו\u0004 היתר לטלטל \u0003אלא\u0004 לאורך \u0003חצי מבוי\u0004 בלבד. ומקשים: \u0003פשיטא\u0004 \u0005[פשוט,\u0006 ברור\u0005]!\u0006 \u0003אלא אימא\u0004 \u0005[אמור]:\u0006 \u0003יש לו חצי מבוי,\u0004 אף על פי שאין לחי קבועה בפתחו, ובכך החידוש. ומקשים: \u0003הא נמי פשיטא\u0004 \u0005[זה גם כן פשוט]!\u0006 ומסבירים: כי בכל זאת יש בכך חידוש \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003ליחוש דילמא אתי לאשתמושי בכוליה, קא משמע לן\u0004 \u0005[שיחשוש שמא יבוא להשתמש ב\u0006כל המבוי \u0005כולו,\u0006 על כן \u0005משמיע לנו]\u0006 שבחציו מותר להשתמש.","\u0003אמר רבא: עשה לחי למבוי והגביהו מן הקרקע שלשה\u0004 טפחים, \u0003או שהפליגו\u0004 \u0005[הרחיקו]\u0006 \u0003מן הכותל שלשה — לא עשה ולא כלום\u0004 שאין זה לחי ראוי. ו\u0003אפילו\u0004 לדעת \u0003רבן שמעון בן גמליאל\u0004 ש\u0003אמר: אמרינן\u0004 \u0005[אומרים אנו]\u0006 \u0003לבוד\u0004 עד ארבעה טפחים — \u0003הני מילי\u0004 \u0005[דברים אלה\u0006 אמורים\u0005]\u0006 \u0003למעלה,\u0004 וכגון בקורה הרחוקה מכותל המבוי; \u0003אבל למטה, כיון דהויא\u0004 \u0005[שהיא]\u0006 \u0003מחיצה שהגדיין בוקעין בה\u0004 שיכול הגדי לעבור בפתח שגובהו שלשה טפחים אף הוא \u0003לא קאמר\u0004 \u0005[אמר]\u0006 שיחול כאן דין לבוד.","שנינו במשנה ש\u0003ר' יוסי אומר\u0004 שרוחב הלחיין צריך להיות \u0003שלשה טפחים. אמר רב יוסף אמר רב יהודה אמר שמואל: אין הלכה כר' יוסי לא בהילמי\u0004 (בעשיית ציר מלח בשבת) \u0003ולא בלחיין.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב הונא בר חיננא: בהילמי אמרת לן\u0004 \u0005[לנו],\u0006 \u0003בלחיין לא אמרת לן\u0004 \u0005[לנו],\u0006 ושמא נשתכח מלבך? ומעירים: \u0003מאי שנא\u0004 \u0005[במה שונה]\u0006 \u0003ב\u0004ענין \u0003הילמי\u0004 — \u0003דפליגי רבנן עליה\u0004 \u0005[שחלוקים חכמים עליו]\u0006 ב\u0003לחיין נמי פליגי רבנן עליה\u0004 \u0005[גם כן חלוקים חכמים עליו],\u0006 ואם כן מסתבר לומר שאין הלכה כמותו בשני המקרים. \u0003אמר ליה\u0004 \u0005[לו],\u0006 יש מקום לחלק: \u0003שאני\u0004 \u0005[שונים]\u0006 \u0003לחיין, משום דקאי\u0004 \u0005[שעומד]\u0006 \u0003רבי כוותיה\u0004 \u0005[בשיטתו],\u0006 ושמא נפסוק הלכה כשיטתם המשותפת.","דיון זה כולו היה לפי גרסה אחת ואילו \u0003רב רחומי מתני הכי\u0004 \u0005[היה שונה כך,\u0006 בגרסה שונה\u0005]:\u0006 \u0003אמר רב יהודה בריה\u0004 \u0005[בנו]\u0006 של \u0003רב שמואל בר שילת משמיה\u0004 [משמו] של \u0003רב: אין הלכה כר' יוסי לא בהילמי ולא בלחיין. אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003אמרת?\u0004 כלומר לאחר זמן שאלו אותו אם אמנם מסר הלכה זו, \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003לא\u0004 אמרתי. \u0003אמר רבא\u0004 וחיזק דבריו בשבועה: \u0003האלהים! אמרה, וגמירנא לה מיניה\u0004 \u0005[אמר אותה,\u0006 את ההלכה הזאת, \u0005ואני למדתיה ממנו],\u0006 ואולם חזר בו אחר כך מפסק זה. \u0003ומאי טעמא קא הדר ביה\u0004 \u0005[ומה טעם חזר בו]?\u0006 \u0003משום\u0004 הכלל הידוע ש\u0003ר' יוסי נימוקו עמו\u0004, ויש לפסוק הלכה כמותו אפילו כנגד רבים.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 שאל \u0003רבא בר רב חנן\u0004 את \u0003אביי: הילכתא מאי\u0004 \u0005[מה ההלכה]\u0006 בענין רוחב הלחיים? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003פוק חזי מאי עמא דבר\u0004 \u0005[צא\u0006 ו\u0005ראה מה נוהג העם]\u0006 וכבר נהג העם בלחי משהו.","\u0003איכא דמתני לה אהא\u0004 \u0005[יש ששונה\u0006 תשובה \u0005זו על\u0006 נושא \u0005זה]:\u0006 \u0003השותה מים לצמאו, אומר\u0004 לפני השתיה ברכה: \u0003\"שהכל נהיה בדברו\". ר' טרפון אומר\u0004 לפני השתיה מברך: \u0003\"בורא נפשות רבות וחסרונן על כל מה שבראת\". אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב חנן לאביי: הלכתא מאי\u0004 \u0005[מה ההלכה]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003פוק חזי מאי עמא דבר\u0004 \u0005[צא\u0006 ו\u0005ראה מה נוהג העם].\u0006 ונהגו לברך \"שהכל נהיה בדברו\"."],["\u0003איתמר\u0004 \u0005[נאמר]\u0006 שנחלקו אמוראים בדבר \u0003לחי העומד מאליו\u0004, כלומר לחי המצוי במבוי ולא העמידוהו במיוחד לצורך הכשר מבוי אלא לדבר אחר במקום שיוכל לשמש כלחי. \u0003אביי אמר: הוי\u0004 \u0005[הרי זה]\u0006 \u0003לחי, רבא אמר: לא הוי\u0004 \u0005[אינו]\u0006 \u0003לחי\u0004.","ומתחילה מצמצמים את תחום המחלוקת: \u0003היכא דלא סמכינן עליה\u0004 \u0005[במקום שאין אנו סומכים עליו]\u0006 \u0003מאתמול,\u0004 מערב שבת, \u0003כולי עלמא לא פליגי\u0004 \u0005[הכל אינם חולקים]\u0006 \u0003דלא הוי\u0004 \u0005[שאינו]\u0006 \u0003לחי. כי פליגי היכא דסמכינן עליה\u0004 \u0005[כאשר נחלקו הרי זה במקום שסמכנו עליו]\u0006 \u0003מאתמול. אביי אמר: הוי\u0004 \u0005[הריהו]\u0006 \u0003לחי, דהא סמכינן עליה\u0004 \u0005[שהרי סמכנו עליו]\u0006 \u0003מאתמול. רבא אמר\u0004: \u0003לא הוי\u0004 \u0005[אינו]\u0006 \u0003לחי, כיון דמעיקרא לאו אדעתיה דהכי עבידי, לא הוי\u0004 \u0005[שמתחילה לא על דעת כן נעשה, אינו נחשב]\u0006 \u0003לחי.\u0004","ומעירים: \u0003קא סלקא דעתך כי היכי דפליגי\u0004 \u0005[עלה על דעתנו כי כשם שהם נחלקים]\u0006 \u0003בלחי פליגי נמי\u0004 \u0005[נחלקו גם כן]\u0006 \u0003במחיצה\u0004 אם יש לסמוך על מחיצה שלא הועמדה בידי אדם לצורך זה.","\u0003תא שמע\u0004 \u0005[בוא ושמע]\u0006 הוכחה לדבר ממה ששנינו במשנה: \u0003העושה סוכתו בין האילנות ואילנות דפנות לה כשירה\u0004. כלומר, כיון שהאילנות משמשים כמחיצה (דפנות): משמע שמחיצה אף שלא נעשתה לצורך זה — שמה מחיצה. ודוחים: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 \u0003שנטען מתחילה לכך\u0004 כדי שישמשו דפנות לסוכה. ומקשים: \u0003אי הכי פשיטא\u0004 \u0005[אם כך פשוט\u0006 הוא\u0005]\u0006 וברור שאם נטעם בכוונה לכך כשרים הם לדפנות! ועונים: \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003ליגזור דילמא אתי לאשתמושי\u0004 \u0005[שיגזרו\u0006 לאסור \u0005שמא יבוא להשתמש]\u0006 \u0003באילן\u0004 בחג, ובתוך כך יתלוש עליו, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שמותרת סוכה זו ואין אנו גוזרים בה לאסור.","ועוד מנסים להוכיח: \u0003תא שמע\u0004 \u0005[בוא ושמע]\u0006 הוכחה לדבר ממה ששנינו: \u0003היה שם אילן או גדר או חיצת הקנים\u0004 (קנים הנטועים באופן שמחוברים זה לזה) \u0003נידון משום דיומד\u0004 כלומר נחשבים אלה כאחת המחיצות הראויות להקיף את באר הרבים כפי שיבואר. ואם כן משמע שמחיצה שלא נעשתה לכך נחשבת בכל זאת למחיצה!","ודוחים: \u0003הכא נמי במאי עסקינן\u0004 \u0005[כאן גם כן במה אנו עוסקים]\u0006 \u0003שעשאן מתחילה לכך\u0004. ושואלים: \u0003אי הכי מאי קא משמע לן\u0004 \u0005[אם כך מה השמיע לנו]?\u0006 ומשיבים: \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 חידוש בפרט אחד, בענין \u0003חיצת הקנים\u0004 העשויה \u0003קנה קנה פחות משלשה טפחים, כדבעא מיניה\u0004 \u0005[כמו ששאל ממנו]\u0006 \u0003אביי מרבה\u0004 — מה דינה, והלכה זו למדנו מכאן, והיא היא החידוש בדבר.","ועוד רוצים להביא ראיה, \u0003תא שמע\u0004 \u0005[בוא ושמע]\u0006 ממה ששנינו: \u0003אילן המיסיך על הארץ\u0004 וענפיו פרושים ומשתפלים בגובה עשרה טפחים ויורדים מסביב עד סמוך לקרקע. \u0003אם אין נופו גבוה מן הארץ שלשה טפחים — מטלטלין תחתיו\u0004 משום שהנוף יוצר כעין מחיצה סביב, ומותר לטלטל בתוך מחיצה זו. ודוחים: \u0003הכא נמי במאי עסקינן\u0004 \u0005[כאן גם כן במה אנו עוסקים]\u0006 \u0003שנטעו מתחילה לכך\u0004.","ומקשים: \u0003אי הכי ליטלטל בכולו\u0004 \u0005[אם כך נטלטל בכולו]\u0006 \u0003אלמה\u0004 \u0005[משום מה]\u0006 \u0003אמר רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע: אין מטלטלין בו אלא\u0004 אם כן היה כשיעור \u0003בית סאתים\u0004 או פחות אבל ביותר מכשיעור זה — אין מטלטלים משום שאין דינו כחצר, ואם כן משמע שאין מחיצות אלה נדונות כמחיצות לכל דבר.","ודוחים: \u0003משום דהוי\u0004 \u0005[שהריהו]\u0006 \u0003דירה שתשמישה לאויר\u0004 ולצל, שהשימוש בה אינו בא מכוח מחיצותיה אלא ממקומה וחללה בלבד, \u0003וכל דירה שתשמישה לאויר\u0004 ולא נעשתה לגור בה תמיד, \u0003אין מטלטלין בה אלא בית סאתים\u0004.","ועוד רוצים להביא ראיה, \u0003תא שמע\u0004 \u0005[בוא ושמע]\u0006 ממה ששנינו: \u0003שבת\u0004 אדם \u0003בתל שהוא גבוה עשרה\u0004 טפחים מסביבתו \u0003ו\u0004שטחו \u0003הוא\u0004 רחב \u0003מארבע אמות ועד בית סאתים, וכן\u0004 מי ששבת \u0003בנקע\u0004 (עמק) \u0003שהוא עמוק עשרה\u0004 טפחים מסביבתו, \u0003והוא\u0004 רחב \u0003מארבע אמות ועד בית סאתים\u0004, וכן אם היה בתוך מקום שהיתה בו \u0003קמה קצורה ו\u0004שורת \u0003שיבולות\u0004 שאינן קצורות \u0003מקיפות אותה\u0004 ואותן שיבולים גבוהות עשרה טפחים והרי הן משמשות כעין מחיצה למקום הקצור, הרי בכל אלה דינו כמו ששבת בביתו, ו\u0003מהלך את כולה וחוצה לה אלפים אמה\u0004.","\u0003וכי תימא הכא נמי\u0004 \u0005[ואם תאמר כאן גם כן]\u0006 מדובר \u0003שעשה מתחילה לכך, בשלמא\u0004 \u0005[נניח]\u0006 \u0003קמה — לחיי\u0004 \u0005[בסדר],\u0006 \u0003אלא תל ונקע מאי איכא למימר\u0004 \u0005[מה יש לומר]\u0006 ודאי מימות עולם הם כך. ואם כן מוכח מכאן שמחיצות אינן צריכות להיות עשויות לשמן.","\u0003אלא\u0004 עלינו לדחות כל שנאמר עד כה, ולהסביר: \u0003במחיצות כולי עלמא לא פליגי דהויא\u0004 \u0005[הכל אינם חולקים שהריהי]\u0006 \u0003מחיצה, כי פליגי\u0004 \u0005[כאשר נחלקו] —\u0006 \u0003בלחי. אביי לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005]\u0006 ש\u0003אמר\u0004 כי \u0003לחי משום מחיצה, ומחיצה העשויה מאליה הויא\u0004 \u0005[הריהי]\u0006 \u0003מחיצה,\u0004 כמו שאמרנו. \u0003ורבא\u0004 לשיטתו ש\u0003אמר: לחי משום היכר,\u0004 ולכן \u0003אי עבידא\u0004 \u0005[אם עשויה]\u0006 \u0003בידים — הויא\u0004 \u0005[הריהו]\u0006 \u0003היכר, ואי\u0004 \u0005[ואם]\u0006 \u0003לא — לא הוי\u0004 \u0005[אינו]\u0006 \u0003היכר.\u0004","ומעתה מנסים להביא הוכחות להכריע במחלוקת בניסוחה זה, \u0003תא שמע\u0004 \u0005[בוא ושמע]\u0006 ממה ששנינו בתוספתא: \u0003אבני גדר היוצאות מן הגדר\u0004 ו\u0003מובדלות זו מזו פחות משלשה\u0004 טפחים, \u0003אין צריך לחי אחר\u0004 להתיר את המבוי, מפני שהאבנים הללו מצטרפות ונעשות כעין לחי. היו מובדלות \u0003שלשה\u0004 טפחים — \u0003צריך לחי אחר\u0004. ואם כן נמצא שלחי העומד מאליו דינו כלחי.","ודוחים: \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 \u0003שבנאן מתחילה לכך\u0004 — לשם לחי. ושואלים: \u0003אי הכי פשיטא\u0004 \u0005[אם כך, פשוט\u0006 הוא\u0005]\u0006 ומשיבים: \u0003מהו דתימא למיסר בניינא הוא דעבידא\u0004 \u0005[\u0006היית \u0005אומר\u0006 שדבר זה עשוי \u0005לקשר את הבנין\u0006 עם בנין אחר כמלאכת הבנאים ורק לצורך זה \u0005נעשו\u0006 האבנים\u0005]\u0006 על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שאין אנו חוששים שיאמרו הבריות כן, כיון שנעשו מתחילה לשם לחי.","ועוד מנסים להוכיח, \u0003תא שמע\u0004 \u0005[בוא ושמע]\u0006 ממה ששנינו בתוספתא: ששנה \u0003ר' חייא כותל שצידו אחד כנוס מחברו בין שנראה מבחוץ\u0004 שהוא כנוס, אבל \u0003שוה מבפנים, ובין שנראה מבפנים ושוה מבחוץ, נדון\u0004 חלק בולט זה \u0003משום לחי\u0004. ואם כן נראה שלחי אינו צריך להיעשות לצורך זה.","ומשיבים: \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 \u0003שעשאו\u0004 גם \u0003מתחילה\u0004 לכך. ושואלים: \u0003אי הכי מאי קא משמע לן\u0004 \u0005[אם כך מה השמיע לנו]?\u0006 ומשיבים: \u0003הא קא משמע לן\u0004 \u0005[\u0006דבר \u0005זה השמיע לנו]:\u0006 \u0003נראה מבחוץ ושוה מבפנים — נדון משום לחי\u0004, אף על פי שאין הלכה זו מקובלת על הכל.","ועוד מנסים להוכיח: \u0003תא שמע\u0004 \u0005[בוא ושמע\u0006 פתרון:\u0005]\u0006 \u0003דרב הוה יתיב בההוא מבואה, הוה יתיב\u0004 \u0005[היה יושב במבוי אחד, והיה יושב]\u0006 \u0003רב הונא קמיה\u0004 \u0005[לפניו]\u0006 \u0003אמר ליה לשמעיה\u0004 \u0005[לו לשמש]:\u0006 \u0003זיל אייתי\u0004 \u0005[לך, הבא]\u0006 \u0003לי כוזא דמיא\u0004 \u0005[מעט מים].\u0006 \u0003עד דאתא\u0004 \u0005[שבא],\u0006 \u0003נפל לחי\u0004 באותו מבוי. \u0003אחוי ליה בידיה קם אדוכתיה\u0004 \u0005[הראה לו בידו\u0006 שיעמוד\u0005,\u0006 ו\u0005עמד במקומו].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב הונא: לא סבר לה מר\u0004 \u0005[האם אין אדוני סבור]\u0006 שאפשר \u0003לסמוך אדיקלא\u0004 \u0005[על הדקל]\u0006 העומד בפתח מבוי זה ויתיר משום לחי? \u0003אמר\u0004 רב: \u0003דמי האי מרבנן כמאן דלא פרשי אינשי שמעתא\u0004 \u0005[דומה תלמיד חכם זה,\u0006 רב הונא, \u0003כמי שאינו יודע שמועתם\u0004 של חכמים\u0005]\u0006 כי \u0003מי סמכינן עליה\u0004 \u0005[האם סמכנו עליו]\u0006 \u0003מאתמול?\u0004 ולכן אי אפשר להתיר על ידו.","ומדייקים: \u0003טעמא\u0004 \u0005[הטעם]\u0006 דוקא \u0005—\u0006 \u0003דלא סמכינן\u0004 \u0005[שלא סמכנו]\u0006 מאתמול, \u0003הא סמכינן\u0004 \u0005[אבל\u0006 אם \u0005היינו סומכים] —\u0006 \u0003הוי\u0004 \u0005[היה זה]\u0006 \u0003לחי.\u0004 משמע שלחי העומד מאליו לחי הוא!","ומנסים להציע: \u0003לימא\u0004 \u0005[שמא נאמר]\u0006 ש\u0003אביי ורבא בדלא סמכינן עליה פליגי, הא סמכינן עליה\u0004 \u0005[בשלא סמכו עליו נחלקו,\u0006 אולם במקרה \u0005שסמכו עליו] —\u0006 \u0003הוה\u0004 \u0005[הריהו]\u0006 \u0003לחי\u0004 לכל הדעות. ועונים: \u0003לא סלקא דעתך\u0004 \u0005[יעלה על דעתך]\u0006 כי \u0003ההוא ברקא דהוה בי\u0004 \u0005[אותו יציע שהיה בבית]\u0006 \u0003בר חבו דהוו פליגי בה\u0004 \u0005[שנחלקו בו]\u0006 \u0003אביי ורבא כולי שנייהו\u0004 \u0005[כל שנותיהם]\u0006 אם העמוד שעליו נסמך היציע יכול לשמש כלחי למבוי שבצידו שהרי ודאי סמכו בעלי המבוי עליו כלחי למבוי זה, אלא מן ההכרח לומר שנחלקו גם בלחי שכבר סמכו עליו מבעוד יום.","\u0003בכל\u0004 החומרים \u0003עושין לחיין אפילו בדבר שיש בו רוח חיים\u0004 אם היה מוצמד לפתח המבוי. \u0003ור' מאיר אוסר\u0004. ומוסיפים הלכה אחרת, שאף כל דבר שיש בו רוח חיים \u0003מטמא משום גולל\u0004 (כיסוי הקבר) אם השתמשו בו לצורך זה."],["\u0003ור' מאיר מטהר\u0004. וכן \u0003כותבין עליו\u0004 — על כל דבר, אף שיש בו רוח חיים, \u0003גיטי נשים. ור' יוסי הגלילי פוסל.\u0004","\u0003תניא\u0004 \u0005[שנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' מאיר אומר: כל דבר שיש בו רוח חיים אין עושין אותו לא דופן לסוכה ולא לחי למבוי, לא פסין ל\u0004הקיף בהם את ה\u0003ביראות\u0004 \u0005[בארות]\u0006 \u0003ולא גולל לקבר,\u0004 ואם עשו, אינו מטמא. \u0003משום\u0004 (בשם) \u0003ר' יוסי הגלילי אמרו: אף אין כותבין עליו גיטי נשים\u0004.","ושואלים: \u0003מאי טעמא\u0004 \u0005[מה טעמו]\u0006 \u0003דר' יוסי הגלילי\u0004, \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]\u0006 על הפסוק \"כי יקח איש אשה ובעלה והיה אם לא תמצא חן בעיניו כי מצא בה ערות דבר וכתב לה ספר כריתות ונתן בידה ושילחה מביתו\" (דברים כד, א): \u0003\"ספר\", אין לי אלא ספר\u0004, כלומר: כתוב על גבי קלף כספר תורה. \u0003מנין לרבות כל דבר\u0004 שכשר לכתוב עליו גט? \u0003תלמוד לומר \"וכתב לה\" — מכל מקום\u0004, כלומר: בכל דבר שניתן להיכתב עליו. \u0003אם כן מה תלמוד לומר \"ספר\"? לומר לך: מה ספר — דבר שאין בו רוח חיים ואינו אוכל\u0004 (מאכל), \u0003אף כל דבר שאין בו רוח חיים ואינו אוכל\u0004. ומטעם זה סבר ר' יוסי שאין לכתוב גט על דבר שיש בו רוח חיים.","ושואלים: \u0003ורבנן\u0004 \u0005[וחכמים]\u0006 החולקים וסוברים שאפשר לכתוב גט אף על בעלי חיים, כיצד מבינים הם את הכתוב? והם מסבירים: \u0003מי כתיב\u0004 \u0005[האם נאמר]\u0006 \u0003\"\u0004וכתב \u0003בספר\"?\u0004 והרי \u0003\"ספר\" כתיב\u0004 \u0005[נאמר],\u0006 והכוונה \u0003לספירות\u0004 (סיפור) \u0003דברים בעלמא\u0004 \u0005[בלבד]\u0006 \u0003הוא דאתא\u0004 \u0005[שבא].\u0006 כלומר, \"ספר\" אין משמעו סוג ידוע של החומר שהגט נכתב עליו, אלא משמעו תוכן הגט שיהא זה דבר כתוב המוסר תוכן מסוים.","ועוד שואלים: \u0003ורבנן\u0004 \u0005[וחכמים]\u0006, \u0003האי\u0004 \u0005[אלו]\u0006 המלים \u0003\"וכתב לה\" מאי דרשי ביה\u0004 \u0005[מה דורשים הם בו]?\u0006 ועונים: \u0003ההוא מבעי ליה\u0004 \u0005[\u0006דבר \u0005זה נצרך לו]\u0006 כדי ללמד כי \u0003בכתיבה מתגרשת\u0004 האשה, \u0003ואינה מתגרשת בכסף. סלקא דעתך אמינא הואיל ואיתקש\u0004 \u0005[יעלה על דעתך לומר: הואיל והוקשה,\u0006 הושוותה\u0005]\u0006 \u0003יציאה\u0004 (גירושין) \u0003להויה\u0004 (קידושין), נאמר: \u0003מה הויה בכסף, אף יציאה בכסף. קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 והדגיש לומר \"וכתב\" ללמדנו שאין הדבר כן.","ושואלים: \u0003ור' יוסי הגלילי, האי סברא מנא ליה\u0004 \u0005[סברה זו\u0006 שאינה מתגרשת בכסף \u0005מנין לו]?\u0006 ומשיבים: \u0003נפקא ליה\u0004 \u0005[יוצא לו,\u0006 נלמד הדבר\u0005]\u0006 מן הכתוב \u0003\"ספר כריתת\"\u0004 שמשמעו: \u0003ספר כורתה, ואין דבר אחר כורתה\u0004.","ואומרים: \u0003ורבנן\u0004 \u0005[וחכמים]\u0006, \u0003האי\u0004 \u0005[אלו]\u0006 המלים \u0003\"ספר כריתת\" מיבעי ליה\u0004 \u0005[נחוץ לו]\u0006 ללמד שחייב הגט להיות בתוכנו \u0003דבר הכורת\u0004 כל קשר \u0003בינו לבינה. לכדתניא\u0004 \u0005[לכמו ששנינו\u0006 בברייתא\u0005],\u0006 האומר לאשה: \u0003הרי זה גיטך על מנת שלא תשתי יין\u0004 לעולם, \u0003על מנת שלא תלכי לבית אביך לעולם — אין זה כריתות,\u0004 ואינו גט. שכל גט המעמיד לאשה תנאי הקושר אותה לצמיתות, משמעו שלא נכרת לגמרי הקשר עם הבעל, ואינו \"כריתות\". אבל אם אומר: שיהא תנאי ידוע קיים \u0003כל שלשים יום\u0004 או תאריך מסוים אחר — \u0003הרי זה כריתות\u0004, שהרי גט זה יש בו כריתות גמורה בתום הזמן, אף שיש בו תנאי והגבלה לזמן מסוים.","\u0003ור' יוסי הגלילי\u0004 הלומד מ\"כריתות\" הלכה אחרת, \u0003נפקא ליה\u0004 \u0005[יוצא לו]\u0006 לימוד זה מן הריבוי \u0003'כרת' 'כריתת'\u0004 — שהרי די היה לכתוב \"ספר כרת\", ונאמר \"כריתות\" ללמד שני דברים: הן שגירושין נעשים על ידי ספר, והן שבגט צריכה להיות כריתות גמורה.","וחכמים; \u0003'כרת' 'כריתת' לא דרשי\u0004 \u0005[דורשים]\u0006 — אינם סבורים שיש הבדל בעל משמעות בין הדברים, ואין ללמוד כלל משינוי לשון זה.","\u0003שיירא שחנתה בבקעה\u0004 (במישור) \u0003והקיפוה\u0004 בני השיירה \u0003כלי בהמה\u0004 ויצרו מחיצה — \u0003מטלטלין בתוכה\u0004 בתוך ההיקף. \u0003ובלבד שיהא גדר\u0004 שנעשה מן הכלים \u0003גבוה עשרה טפחים ולא יהו פירצות\u0004 שבין הכלים \u0003יתרות על הבנין\u0004 (החלק הבנוי, הגדור).","ו\u0003כל פירצה שהיא כעשר אמות מותרת\u0004 ואינה פוסלת את המחיצה \u0003מפני שהיא כפתח\u0004. היתה הפירצה \u0003יתר מכאן — אסור\u0004 לטלטל בכל ההיקף.","\u0003איתמר\u0004 \u0005[נאמר]\u0006 שנחלקו אמוראים בבעיה של \u0003פרוץ כעומד\u0004, לאמור, דבר שחלקו הפרוץ שוה בדיוק לחלקו העומד, הקיים, האם מותר לטלטל בו או אסור? \u0003רב פפא אמר: מותר. רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע אמר: אסור.\u0004","ומסבירים, \u0003רב פפא אמר: מותר.\u0004 וכך נבין: \u0003הכי אגמריה רחמנא\u0004 \u0005[כך לימדו הקדוש ברוך הוא]\u0006 \u0003למשה, לא תפרוץ רובה.\u0004 וכל עוד שהרוב אינו פרוץ — הרי זו מחיצה. ואילו \u0003רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע אמר: אסור, הכי אגמריה רחמנא\u0004 \u0005[כך לימדו הקדוש ברוך הוא]\u0006 \u0003למשה: גדור רובה.\u0004","\u0003תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005]:\u0006 \u0003ולא יהו פירצות יתרות על הבנין\u0004. ונדייק: \u0003הא\u0004 \u0005[הרי]\u0006 היו \u0003כבנין\u0004 — \u0003מותר?!\u0004 וקשה לרב הונא בנו של רב יהושע!","ודוחים: \u0003לא תימא\u0004 \u0005[תאמר]\u0006 ותדייק \u0003הא\u0004 \u0005[הרי]\u0006 \u0003כבנין מותר, אלא אימא\u0004 \u0005[\u0006כך \u0005תאמר\u0006 ותדייק\u0005]:\u0006 \u0003אם בנין יתר על הפירצה — מותר\u0004.","וממשיכים להקשות: ולפי הסבר זה — \u0003אבל\u0004 אם היו הפירצות \u0003כבנין, מאי\u0004 \u0005[מה]\u0006 יהיה הדין — \u0003אסור? אי הכי ליתני\u0004 \u0005[אם כך, שישנה]\u0006 \u0003לא יהו פירצות כבנין\u0004. וממילא יובן שאם פרוץ יותר מכבנין הרי ודאי אסור. ומעירים: אכן, \u0003קשיא\u0004 \u0005[קשה]\u0006 לשיטה זו.","ועוד מנסים להוכיח, \u0003תא שמע\u0004 \u0005[בוא ושמע]\u0006 ממה ששנינו בדיני סוכה: \u0003המקרה\u0004 (עושה תקרה) \u0003סוכתו בשפודין\u0004 של מתכת, הפסולים לסכך כיון שמקבלים טומאה, \u0003או בארוכות המטה\u0004 (במוטות הארוכים של המטה) שאף הם אינם כשרים לסכך מאותו הטעם, \u0003אם יש ריוח ביניהן כמותן — כשירה\u0004, אם יהא באותו רווח סכך כשר. ומכאן ניתן להסיק שאם הכשר (העומד) שוה בשיעורו לפסול — הרי זה כאילו היה רובו כשר, וקשה לרב הונא בנו של רב יהושע!","ודוחים: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 \u0003כשנכנס ויוצא,\u0004 כלומר שיש עוד רווח נוסף בצד השפודים המאפשר להכניסם ולהוציאם, ומשום כך לבסוף נמצא שמקום הסכך יתר על השפודים.","ושואלים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אפשר לצמצם\u0004 ולדייק, ויהא הרווח שוה בדיוק למקום השפודים, ובכל זאת אפשר יהיה להוציאם ולהכניסם, ולכן אין תירוץ זה שאמרנו מועיל.","\u0003אמר ר' אמי\u0004 שיש לבאר הלכה זו דוקא \u0003במעדיף\u0004 (במוסיף) שיהא שיעור החלק המסוכך כהילכתו יתר על שיעור השפודים.","\u0003רבא אמר\u0004 לבאר תירוץ זה שאינו אלא \u0003אם היו נתונין\u0004 שפודים \u0003ערב\u0004 לסוכה \u0003נותנו\u0004 את הסכך הכשר \u0003שתי\u0004 ובכך הוא מוסיף עליו הרבה, היו נתונים \u0003שתי נותנו ערב\u0004.","ועוד מנסים להוכיח, \u0003תא שמע\u0004 \u0005[בוא ושמע]\u0006 ממה ששנינו בברייתא: \u0003שיירא שחנתה בבקעה והקיפוה בגמלין\u0004 שהרביצום, או \u0003באוכפות\u0004 של הגמלים"],["\u0003בעביטין\u0004 (כרי הגמל) \u0003בשליפין\u0004 (עומרי חיטה), \u0003בקנים, בקולחות\u0004 (קלחי ירקות) \u0003— מטלטלין בתוכה, ובלבד שלא יהא בין גמל לגמל\u0004 רווח \u0003כמלא גמל, ובין אוכף לאוכף כמלא אוכף, ובין עביט לעביט כמלא עביט\u0004. נמצא שפרוץ כעומד אינו מחיצה!","ודוחים: \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 \u0003כשנכנס ויוצא\u0004, שהרווח מרובה קצת מן העומד.","ומנסים להביא ראיה אחרת. \u0003תא שמע\u0004 \u0005[בא ושמע]\u0006 מה ששנינו בתוספתא במסכת כלאים: \u0003נמצאת אתה אומר, שלש מדות במחיצות\u0004 החוצצות בכלאים: \u0003כל שהוא פחות משלשה\u0004 שהמחיצה עצמה עשויה קנים שרוחב כל אחד מהם פחות משלושה טפחים, כדי להתיר \u0003צריך שלא יהא בין זה לזה\u0004 — בין קנה לקנה, \u0003שלשה\u0004 טפחים \u0003כדי שלא יזדקר\u0004 \u0005[יקפוץ]\u0006 \u0003הגדי בבת ראש\u0004 (בבת אחת) שביותר משלושה טפחים יכול הגדי לעבור, ושוב אין זה לבוד, ואינה נחשבת מחיצה.","\u0003כל שהוא שלשה,\u0004 שהמחיצה מורכבת מקנים שרוחב כל אחד מהם שלשה טפחים. \u0003ו\u0004אם היה רוחב הקנים \u0003משלשה עד ארבעה\u0004 טפחים, אף על פי שהרווח בין הקנים הוא למעלה משלשה טפחים, בכל אופן כדי להתיר \u0003צריך שלא יהא בין זה לזה כמלואו\u0004 כגודל רוחבו של החלק העומד, \u0003כדי שלא יהא הפרוץ כעומד\u0004 וכשר. \u0003ואם היה פרוץ מרובה על העומד — אף כנגד העומד אסור\u0004 לזרוע ממין אחר, שפירצות אלה מבטלות את המחיצה כולה.","\u0003כל ש\u0004רוחב הקנים \u0003הוא ארבעה\u0004 טפחים, \u0003ומארבעה\u0004 טפחים \u0003עד עשר אמות — צריך שלא יהא בין זה לזה\u0004 בין חלק אחד של המחיצה לחברו \u0003כמלואו, שלא יהא פרוץ כעומד. ואם היה פרוץ כעומד\u0004 הרי \u0003כנגד העומד — מותר\u0004 לזרוע, שבמקום זה יש מחיצה, \u0003כנגד הפרוץ — אסור. ואם היה\u0004 בכל המקרים הללו \u0003עומד מרובה על הפרוץ, אף כנגד הפרוץ — מותר\u0004.","ואם \u0003נפרצה\u0004 הגדר \u0003ביותר מעשר\u0004 אמות — \u0003אסור\u0004, ששוב בטלה כל אותה מחיצה, \u0003היו שם קנים הדוקרנים\u0004 (יתידות הנעוצות בקרקע) \u0003ועושה להן פיאה\u0004 (מקלעת קש) \u0003מלמעלה\u0004 כצורת הפתח, \u0003אפילו ביותר מעשר — מותר\u0004 שצורת הפתח מתירה אף ביותר מעשר אמות.","\u0003קתני מיהת רישא\u0004 \u0005[למדנו מכל מקום בתחילה]\u0006 \u0003משלשה עד ארבעה, ובלבד שלא יהא בין זה לזה כמלואו,\u0004 והרי זו \u0003תיובתא [קושיה חמורה]\u0004 ל\u0003רב פפא\u0004 המתיר בפרוץ כעומד!","\u0003אמר לך רב פפא: מאי\u0004 \u0005[מה\u0006 משמע\u0005]\u0006 \u0003מלואו\u0004 — לא מלואו ממש, אלא ב\u0003נכנס ויוצא\u0004 שהוא מעט יותר מכן.","ומעירים: \u0003הכי נמי מסתברא\u0004 \u0005[כך גם כן מסתבר]\u0006 \u0003מדקתני\u0004 \u0005[מ\u0006מה \u0005ששנינו]:\u0006 \u0003אם היה פרוץ מרובה על העומד אף כנגד העומד — אסור\u0004. ודייק מלשון זה: \u0003הא\u0004 \u0005[הרי]\u0006 אם היה בדיוק \u0003כעומד — מותר\u0004. ומסכמים: אכן, \u0003שמע מינה\u0004 \u0005[למד ממנה].\u0006","ושואלים: \u0003לימא תיהוי תיובתיה\u0004 \u0005[האם נאמר שתהא זו,\u0006 דיוק זה, \u0005קושיה חמורה]\u0006 על שיטת \u0003רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע?\u0004 ודוחים: \u0003אמר לך: וליטעמיך, אימא סיפא\u0004 \u0005[יאמר לך: לשיטתך, אמור את הסוף]:\u0006 \u0003אם היה עומד מרובה על הפרוץ, אף כנגד הפרוץ מותר\u0004, ונדייק: \u0003הא\u0004 \u0005[הרי]\u0006 \u0003כפרוץ — אסור\u0004,","ואם כן \u0003סיפא קשיא\u0004 \u0005[\u0006הדיוק מן \u0005הסוף קשה]\u0006 \u0003ל\u0004שיטת \u0003רב פפא, רישא קשיא\u0004 \u0005[\u0006הדיוק מן \u0005ההתחלה קשה]\u0006 \u0003ל\u0004שיטת \u0003רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע.\u0004","ומתרצים: \u0003סיפא\u0004 \u0005[הסוף]\u0006 \u0003לרב פפא לא קשיא, איידי דתנא רישא\u0004 \u0005[לא קשה, אגב ששנה בראש]\u0006 לשון זו של \u0003\"פרוץ מרובה על העומד\", תנא סיפא\u0004 \u0005[שנה בסוף]\u0006 \u0003\"עומד מרובה על הפרוץ\",\u0004 אבל אין זו לשון מדויקת.","וכן אפשר לתרץ כי \u0003רישא\u0004 \u0005[התחלה]\u0006 \u0003לרב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע לא קשיא, איידי דבעי למיתני סיפא\u0004 \u0005[אינו קשה, אגב\u0006 מתוך \u0005שרצה לשנות בסוף]\u0006 \u0003\"עומד מרובה על הפרוץ\" תנא רישא\u0004 \u0005[שנה בראש]\u0006 \u0003\"פרוץ מרובה על העומד\"\u0004 בלא לדייק בלשון.","ומוסיפים לשאול: \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003ל\u0004שיטת \u0003רב פפא\u0004 המתיר בפרוץ כעומד \u0003משום הכי\u0004 \u0005[כך]\u0006 \u0003לא עריב להו ותני להו\u0004 \u0005[עירב אותם ושנה אותם\u0006 כאחת\u0005]\u0006 בין פחות משלשה ובין שלשה טפחים שאסור שיהיה ביניהם חלל שלושה טפחים, כי לשיטתו שפרוץ כעומד דינו כעומד נמצא שבקנים של שלשה טפחים אין המחיצה נפסלת אלא בחלל יותר משלשה.","ואינו דומה לקנים של פחות משלושה שאיסורם הוא רק בחלל שלושה טפחים אבל בפחות מכך, אף אם הוא יותר מהעומד, כשר \u0003אלא ל\u0004שיטת \u0003רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע\u0004 האוסר בפרוץ כעומד \u0003ליערבינהו וליתננהו\u0004 \u0005[שיערבם וישנם\u0006 יחד\u0005],\u0006 וכך ישנה: \u0003כל שהוא פחות משלשה\u0004, \u0003ו\u0004כן גם \u0003שלשה — צריך שלא יהא בין זה לזה שלשה\u0004, שהרי לשיטתו אף בקנה שלשה אסור שיהא חלל שלשה טפחים אלא פחות מעט!","ומשיבים: \u0003משום דלא דמי פסולא דרישא לפסולא דסיפא\u0004 \u0005[שאינו דומה הפסול שבהתחלה לפסול שבסוף]\u0006 \u0003פסולא דרישא\u0004 \u0005[הפסול שבהתחלה\u0006 טעמו\u0005]\u0006 — \u0003כדי שלא יזדקר הגדי בבת אחת, פסולא דסיפא\u0004 \u0005[הפסול שבסוף]\u0006 — כדי \u0003שלא יהא פרוץ כעומד\u0004. ולכן אף שלמעשה גם בקנה של שלשה צריך החלל להיות פחות משלשה, בדומה לחלק הראשון של התוספתא, הרי מבחינת הנימוק והטעם יש לצרף מקרה זה רק לחלקה השני. ואם כן אין להוכיח מכאן אף לאחד מן החולקים.","וכיון שהובאה תוספתא זו דנים בה מעט לגופה כיון שנקבע שם השיעור של חלל ה\u0003פחות משלשה\u0004 אם כן תוספתא זו \u0003מני\u0004 \u0005[\u0006של \u0005מי היא] —\u0006 כשיטת \u0003רבנן\u0004 \u0005[חכמים],\u0006 \u0003דאמרי\u0004 \u0005[ש\u0006הם \u0005אומרים]:\u0006 \u0003פחות משלשה אמרינן\u0004 \u0005[אומרים אנו]:\u0006 הרי זה \u0003לבוד\u0004, אבל \u0003שלשה לא אמרינן\u0004 \u0005[אין אנו אומרים]\u0006 דין \u0003לבוד\u0004.","אולם \u0003אימא סיפא\u0004 \u0005[אמור את הסוף]:\u0006 \u0003כל שהוא שלשה ומשלשה ועד ארבעה\u0004"],["\u0003אתאן\u0004 \u0005[הגענו]\u0006 \u0003ל\u0004שיטת \u0003רבן שמעון בן גמליאל\u0004 ש\u0003אמר:\u0004 כל רווח שהוא \u0003פחות מארבעה\u0004 טפחים יש בו דין \u0003לבוד. דאי רבנן\u0004 \u0005[שאם\u0006 תאמר כשיטת \u0005חכמים]:\u0006 \u0003משלשה ועד ארבעה\u0004 — מה משמעו של חילוק זה? \u0003שלשה וארבעה חד\u0004 \u0005[אחד]\u0006 \u0003הוא,\u0004 שהרי החל משלושה אין בו דין לבוד.","\u0003אמר אביי: מדרישא רבנן, סיפא נמי רבנן, ומודו רבנן דכל למישרא כנגדו, אי איכא\u0004 \u0005[מכיון שהראשית\u0006 כשיטת \u0005חכמים, הסוף גם כן\u0006 כשיטת \u0005חכמים, ומודים חכמים שהכל\u0006 כדי \u0005להתיר כנגדו, אם יש]\u0006 \u0003מקום ארבעה — חשיב\u0004 \u0005[חשוב]\u0006 הוא, \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא — לא חשיב\u0004 \u0005[אינו חשוב].\u0006 ולכן יש הבדל בין גדר שלושה ובין גדר ארבעה, שאף חכמים מודים שגדר ארבעה טפחים חשובה יותר,","ואילו \u0003רבא אמר מדסיפא\u0004 \u0005[מכיון שהסוף]\u0006 כשיטת \u0003רבן שמעון בן גמליאל רישא נמי\u0004 \u0005[הראשית גם כן]\u0006 כשיטת \u0003רבן שמעון בן גמליאל\u0004. \u0003וכי\u0004 \u0005[ואולם כאשר]\u0006 \u0003אמר רבן שמעון בן גמליאל\u0004 שאומרים אנו \u0003לבוד\u0004 בכגון זה — \u0003הני מילי\u0004 \u0005[דברים אלו\u0006 אמורים\u0005]\u0006 \u0003למעלה\u0004 — בגובה, ולענין הכשר קורה הרחוקה מהמחיצה. \u0003אבל למטה\u0004 — בסמוך לקרקע — \u0003הוה ליה\u0004 \u0005[הרי היא]\u0006 \u0003כמחיצה שהגדיים בוקעין בה\u0004 ואף הוא מודה ש\u0003לא אמרינן\u0004 \u0005[אין אנו אומרים]:\u0006 \u0003לבוד\u0004 בתיקון זה.","ומעתה חוזרים לבעית פרוץ כעומד ומנסים להביא ראיה, \u0003תא שמע\u0004 \u0005[בוא ושמע]\u0006 ממה ששנינו: \u0003דפנות הללו שרובן פתחים וחלונות — מותר, ובלבד שיהא עומד מרובה על הפרוץ\u0004.","ומתחילה מבררים את לשון הברייתא: \u0003\"שרובן\", סלקא דעתך\u0004 \u0005[עולה על דעתך]?!\u0006 והרי אם רובן פתחים וחלונות, ודאי שאין העומד מרובה על הפרוץ. \u0003אלא\u0004 יש לתקן את הלשון: \u0003שריבה בהן פתחים וחלונות — מותר, ובלבד שיהא עומד מרובה על הפרוץ\u0004.","ונדייק: \u0003הא\u0004 \u0005[הרי\u0006 אם היה\u0005]\u0006 \u0003כפרוץ — אסור,\u0004 והרי זו \u0003תיובתא\u0004 \u0005[קושיה חמורה]\u0006 ל\u0003רב פפא.\u0004 ומסכמים: \u0003תיובתא\u0004 \u0005[\u0006אכן \u0005קושיה חמורה\u0006 היא\u0005],\u0006 ואולם בכל זאת מסכמים: \u0003והילכתא כוותיה\u0004 \u0005[והלכה כמותו\u0006 כשיטתו\u0005]\u0006 של \u0003רב פפא.\u0004","על כך תוהים: \u0003תיובתא והילכתא\u0004 \u0005[\u0006גם \u0005קושיה חמורה ו\u0006גם \u0005הלכה\u0006 כמותו\u0005]?!\u0006 ועונים: \u0003אין\u0004 \u0005[כן],\u0006 \u0003משום דדייקא מתניתין כוותיה\u0004 \u0005[שמדוייקת משנתנו כמותו]\u0006 \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003לא יהיו פרצות יתירות על הבנין\u0004 והמשמעות הברורה שאפשר להוציא מכאן היא: שאם היו \u0003כבנין — מותר\u0004, וכדברי רב פפא.","שיירה החונה בבקעה, ורוצים לבנות מחיצה לענין שבת, \u0003מקיפין\u0004 סביב למקום השיירה \u0003שלשה חבלים זה למעלה מזה, וזה למעלה מזה, ובלבד שלא יהו בין חבל לחבירו שלשה טפחים,\u0004","\u0003שיעור\u0004 ה\u0003חבלים ועוביין יתר על טפח, כדי שיהא הכל\u0004 — החלל הפנוי והחבלים \u0003עשרה טפחים\u0004, ועל ידי כך נעשית איפוא מחיצה שגובהה עשרה טפחים.","וכן \u0003מקיפין\u0004 את השיירה \u0003בקנים\u0004 הנעוצים בקרקע זקופים. \u0003ובלבד שלא יהא בין קנה לחבירו — שלשה טפחים.\u0004","\u0003בשיירא דברו דברי ר' יהודה\u0004 שלדעתו לא הותרה מחיצה כזו שכולה רק שתי או רק ערב אלא בשיירה, שיש בכך שעת הדחק אבל כרגיל אין די בהיתר זה. \u0003וחכמים אומרים: לא דברו בשיירא\u0004 דוקא, \u0003אלא בהווה\u0004, כלומר — כרגיל במקום קבע עושים מחיצות טובות יותר, ולא הוזכרה שיירה אלא משום שמן הסתם אינם יכולים בנקל לעשות מחיצות גמורות ושלמות אבל מעיקר הדין מועילות מחיצות כגון אלה בכל מקום.","ויתר על כן נחלקו: \u0003כל מחיצה שאינה של שתי ושל ערב\u0004 יחד — \u0003אינה מחיצה, דברי ר' יוסי בר' יהודה\u0004 שלשיטתו אף בשיירה לא התירו. \u0003וחכמים אומרים: אחד משני דברים —\u0004 או שתי או ערב.","\u0003אמר רב המנונא אמר רב, הרי אמרו\u0004 חכמים (כפי המסקנה מן המשנה הקודמת): \u0003עומד מרובה על הפרוץ בשתי — הוי\u0004 \u0005[הריהו]\u0006 כ\u0003עומד,\u0004 שכן כלי בהמה מונחים על הקרקע בעמידה כדרך השתי. ואולם \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רב המנונא: בערב מאי\u0004 \u0005[מהו]?\u0006 האם גם שם מועיל בעומד מרובה על הפרוץ, או לא?","\u0003אמר אביי: תא שמע\u0004 \u0005[בוא ושמע\u0006 פתרון ממשנתנו\u0005]:\u0006 \u0003שיעור חבלים ועוביין יתר על טפח, שיהו הכל עשרה טפחים. ואי איתא\u0004 \u0005[ואם יש]\u0006 — שאנו מקבלים שעומד מרובה על הפרוץ דינו כעומד, \u0003למה לי יתר על טפח?\u0004","הרי אפשר לעשות בדרך אחרת — \u0003ליעביד\u0004 \u0005[שיעשה]\u0006 \u0003פחות\u0004 מחלל \u0003שלשה, וחבל משהו,\u0004 ושוב \u0003פחות\u0004 מחלל \u0003שלשה וחבל משהו\u0004, וחלל \u0003פחות מארבעה, וחבל משהו\u0004, ומשום דין לבוד (שיש בין שני החבלים פחות משלושה טפחים) יהא עומד מרובה על הפרוץ (הפחות מארבעה) ויהא מותר אף בצורה זו.","ומקשים: \u0003ותיסברא\u0004 \u0005[ו\u0006כי יכול \u0005אתה להיות סבור\u0006 כן\u0005]?\u0006 \u0003האי\u0004 \u0005[אותו\u0006 חלל\u0005]\u0006 \u0003פחות מארבעה\u0004 טפחים \u0003היכא מוקים ליה\u0004 \u0005[היכן יעמיד אותו]?\u0006 \u0003אי מוקים ליה תתאי\u0004 \u0005[אם יעמיד אותו\u0006 בחלק \u0005התחתון]\u0006 \u0003הוה ליה\u0004 \u0005[הרי הוא]\u0006 \u0003כמחיצה שהגדיים בוקעין בה\u0004, ובטלה משום כך.","\u0003אי מוקים ליה עילאי, אתי אוירא דהאי גיסא ודהאי גיסא ומבטל לה\u0004 \u0005[אם ישים אותו למעלה, יבוא האויר,\u0006 החלל, \u0005מצד זה ומצד זה ויבטל אותו],\u0006 שהרי החבל אינו כלבוד לחבל מתחתיו, וחלל ארבעה מצד זה וחלל האויר מלמעלה מבטלים כוחו של החבל העליון, וכאילו אינו קיים.","ו\u0003אי מוקים ליה במיצעי\u0004 \u0005[אם יעמיד אותו באמצע]\u0006 \u0003הוה ליה\u0004 \u0005[הרי זה]\u0006 \u0003עומד מרובה על הפרוץ משתי רוחות\u0004 בצרופן יחד, אבל אם נתייחס לכל צד בפני עצמו הרי הפרוץ מרובה על העומד. ואם נאמר שדבר זה מועיל, \u0003שמעת מינה\u0004 \u0005[ממנה]\u0006 כי \u0003עומד מרובה על הפרוץ משתי רוחות הוי עומד\u0004, אולם דבר זה כבר נדון ונשאר בגדר ספק בלבד!","\u0003אלא רב המנונא הכי קא מיבעיא ליה\u0004 \u0005[כך נשאלה לו\u0006 השאלה\u0005]\u0006 \u0003כגון דאייתי\u0004 \u0005[שהביא]\u0006 \u0003מחצלת דהוי\u0004 \u0005[שהיא]\u0006 \u0003שבעה\u0004 טפחים \u0003ומשהו, וחקק בה\u0004 חור שרוחבו \u0003שלשה\u0004 טפחים, \u0003ושבק\u0004 \u0005[והניח]\u0006 \u0003בה ארבעה ומשהו, ואוקמיה\u0004 \u0005[והעמידה]\u0006 \u0003בפחות משלשה\u0004 טפחים מהקרקע.","\u0003רב אשי אמר: מחיצה תלויה\u0004 בת עשרה טפחים \u0003איבעיא ליה\u0004 \u0005[נשאלה לו]\u0006 מה הדין במחיצה תלויה, כלומר: מחיצה שיש בה כשיעור אך אינה מגיעה עד לקרקע, האם נאמר שכוח חציצתה נמשך עד למטה ומכשירה, או לא \u0003כדבעא מיניה\u0004 \u0005[כמו ששאל ממנו]\u0006 \u0003ר' טבלא מרב: מחיצה תלויה מהו שתתיר בחורבה\u0004 כמחיצה ממש? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אין מחיצה תלויה מתרת אלא\u0004 על גבי \u0003מים — קל הוא שהקלו חכמים במים.\u0004","שנינו במשנה: \u0003מקיפין\u0004 את השיירה \u0003בקנים\u0004 ור' יהודה אמר שהיתר זה במחיצה שכולה רק שתי או רק ערב נאמר בשיירה בלבד. ושואלים: \u0003בשיירא אין\u0004 \u0005[כן]\u0006\u0003, ביחיד לא? והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]\u0006, \u0003ר' יהודה אומר: כל מחיצות\u0004 הרעועות, וכגון שעשויות משתי או מערב לבד, שב\u0003שבת לא התירו ליחיד\u0004 לטלטל בחללן אם הוא \u0003יותר מבית סאתים\u0004 משמע בית סאתים מתיר ר' יהודה אפילו ליחיד.","ומשיבים שיש להבין את דברי ר' יהודה במשנה כפי ש\u0003אמר רב נחמן ואיתימא\u0004 \u0005[ויש אומרים]\u0006 \u0003רב ביבי בר אביי: לא נצרכא\u0004 הלכה זו \u0003אלא ליתן להן כל צרכן, הכא נמי\u0004 \u0005[כאן גם כן]\u0006 \u0003ליתן להן כל צרכן.\u0004 כלומר, לא חלק ר' יהודה על עצם ההתרה של מחיצה כזו אף ליחיד, ולא אמר אלא שרק לאנשי שיירה התירו לסמוך על מחיצות כגון אלה בכל שטח שיצטרכו לו, מה שאין כן ביחיד שהתירו לו רק כבית סאתים.","ומעירים: \u0003היכא איתמר\u0004 \u0005[\u0006ו\u0005היכן נאמר]\u0006 דבר זה של \u0003רב נחמן ואיתימא\u0004 \u0005[ויש אומרים]\u0006 של \u0003רב ביבי בר אביי — אהא\u0004 \u0005[על זה]\u0006 ששנינו בסוף המשנה: \u0003כל מחיצה שאינה של שתי וערב אינה מחיצה,\u0004 ל\u0003דברי ר' יוסי בר' יהודה\u0004.","ושאלו \u0003ומי\u0004 \u0005[והאם]\u0006 \u0003אמר ר' יוסי בר' יהודה הכי\u0004 \u0005[כך]?\u0006 \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003אחד יחיד ואחד שיירא\u0004 שוים לענין היתרם במחיצת \u0003חבלים. ומה בין יחיד לשיירא? יחיד נותנין לו\u0004 במחיצה כזו \u0003בית סאתים\u0004 בלבד לשימושו, \u0003שנים\u0004 אף הם אין \u0003נותנין להם\u0004 אלא \u0003בית סאתים\u0004 בלבד, \u0003שלשה נעשו שיירא; ונותנין להן\u0004 לכל אחד ואחד בית סאתים כלומר \u0003בית שש\u0004 סאים. אלו \u0003דברי ר' יוסי בר' יהודה.\u0004","\u0003וחכמים אומרים: אחד יחיד ואחד שיירא נותנין להן כל צרכן\u0004 וכללו של דבר \u0003ובלבד שלא יהא בית סאתים פנוי\u0004 שלא יעשו היקף הגדול מצרכם יותר משטח בית סאתים. הרי שר' יוסי בר' יהודה סומך על היתר החבלים ואפילו ליחיד!","\u0003אמר רב נחמן ואיתימא\u0004 \u0005[ויש אומרים]\u0006 \u0003רב ביבי בר אביי: לא נצרכא\u0004 מחלוקתו של ר' יוסי בר' יהודה, \u0003אלא\u0004 לומר שבמחיצה כתיקונה נותנים \u0003להן כל צרכם\u0004, ואילו מחיצה כגון זו מתירים בה לשיירה רק כבית שש סאים.","\u0003דרש רב נחמן משום רבינו שמואל: יחיד — נותנין לו בית סאתים, שנים — נותנין להם בית סאתים, שלשה — נעשו שיירא, ונותנין להן בית שש\u0004 סאים.","ותמהו עליו: \u0003שבקת רבנן ועבדת\u0004 \u0005[עזבת\u0006 שיטת \u0005חכמים ועשית]\u0006 \u0003כר' יוסי בר' יהודה,\u0004 כיחיד נגד רבים!?","\u0003הדר אוקים\u0004 \u0005[חזר\u0006 ו\u0005העמיד]\u0006 \u0003רב נחמן אמורא עליה\u0004 \u0005[עליו,\u0006 לפניו\u0005]\u0006 \u0003ודרש: דברים שאמרתי לפניכם טעות הן בידי. ברם\u0004 באמת \u0003כך אמרו: יחיד — נותנין לו בית סאתים, שנים — נותנין להן בית סאתים, שלשה — נעשו שיירא ונותנין להן כל צרכן\u0004."],["ושואלים: \u0003רישא\u0004 \u0005[תחילתה]\u0006 כשיטת \u0003ר' יוסי בר' יהודה וסיפא רבנן\u0004 \u0005[וסופה\u0006 כשיטת \u0005חכמים]?!\u0006","ומשיבים: \u0003אין, משום דקאי אבוה בשיטתיה\u0004 \u0005[כן, משום שמחזיק\u0006 גם \u0005אביו,\u0006 ר' יהודה\u0005, בשיטתו]\u0006 לענין הקף יחיד, ודעתם אם כן בענין זה היא דעת רבים.","\u0003אמר רב גידל אמר רב:\u0004 פעמים \u0003שלשה\u0004 אנשים אף \u0003ב\u0004בית \u0003חמש\u0004 סאים — \u0003אסורין,\u0004 ולפעמים אפילו \u0003ב\u0004בית \u0003שבע\u0004 סאים — \u0003מותרים\u0004. דברים אלה נראו בלתי מובנים. \u0003אמרו ליה\u0004 \u0005[לו]:\u0006 האם \u0003אמר רב הכי\u0004 \u0005[כך]?\u0006 \u0003אמר להו\u0004 \u0005[להם],\u0006 וחיזק דבריו בשבועה: \u0003אורייתא נביאי וכתובי, דאמר רב הכי\u0004 \u0005[תורה נביאים וכתובים, שאמר רב כך]!\u0006","\u0003אמר רב אשי: מאי קשיא\u0004 \u0005[מה הקושי\u0006 בדבר\u0005]?\u0006 \u0003דילמא הכי קאמר\u0004 \u0005[שמא כך,\u0006 במקרה כגון זה\u0005, אמר]:\u0006 \u0003הוצרכו\u0004 להשתמש ב\u0003שש\u0004 סאין \u0003והקיפו בשבע — אפילו בשבע מותרין\u0004 שבית סאה ריק — אינו אוסר, \u0003לא הוצרכו אלא לחמש והקיפו בשבע — אפילו בחמש אסורין\u0004 שיש בית סאתים בלא שימוש.","ושואלים: \u0003ואלא הא דקתני\u0004 \u0005[זו ששנינו]\u0006 \u0003\"ובלבד שלא יהא בית סאתים פנוי\", מאי לאו\u0004 \u0005[האם לא\u0006 הכוונה\u0005]\u0006 \u0003פנוי מאדם?\u0004 כלומר שיהא בחשבון הכולל בית סאתים עודפים על חשבון בית סאתים לכל אדם? ודוחים: \u0003לא,\u0004 הכוונה היא \u0003פנוי מכלים,\u0004 אף על פי שאין לכל אחד מהאנשים בית סאתים, כיון שאינם משתמשים בבית סאתים זה לטלטל שם, בטלו המחיצות.","\u0003איתמר\u0004 \u0005[דנו\u0006 חכמים\u0005]:\u0006 היו \u0003שלשה\u0004 אנשים בשיירא \u0003ומת אחד מהן\u0004 ביום השבת, או היו \u0003שנים ונתוספו עליהן\u0004 בשבת, נחלקו בכך \u0003רב הונא ור' יצחק, חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר: שבת גורמת,\u0004 והכל נדון לפי מצב הדברים בשעת כניסת השבת. \u0003וחד\u0004 \u0005[ואחד\u0006 מהם\u0005]\u0006 \u0003אמר: דיורין\u0004 \u0005[הדיירים]\u0006 \u0003גורמין,\u0004 ודנים לפי מספר האנשים המצויים בפועל בכל שעה.","ומעירים: \u0003תסתיים\u0004 \u0005[תוגדר]\u0006 ש\u0003רב הונא הוא\u0004 ש\u0003אמר שבת גורמת\u0004. שכן \u0003אמר רבה: בעאי\u0004 \u0005[שאלתי]\u0006 \u0003מרב הונא, ובעאי\u0004 \u0005[ושאלתי]\u0006 \u0003מרב יהודה:\u0004 אדם ש\u0003עירב\u0004 מחצר לחצר \u0003דרך הפתח, ונסתם הפתח\u0004 בשבת, או שעירב \u0003דרך החלון ונסתם החלון, מהו?\u0004 האפשר עדיין לסמוך על עירוב זה להתיר לטלטל דרך פתחים אחרים? \u0003ואמר לי: שבת הואיל והותרה\u0004 מתחילה — \u0003הותרה\u0004. ומסכמים: אכן \u0003תסתיים\u0004 \u0005[תוגדר]\u0006 שמסתבר כי רב הונא הוא הסובר ששבת גורמת ולא הדיירים.","ומציעים: \u0003לימא\u0004 \u0005[האם לומר]\u0006 כי \u0003רב הונא ור' יצחק בפלוגתא\u0004 \u0005[במחלוקת]\u0006 של התנאים \u0003ר' יוסי ור' יהודה קמיפלגי\u0004 \u0005[נחלקו]?\u0006 \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003חצר שנפרצה משתי רוחותיה, וכן בית שנפרץ משתי רוחותיו, וכן מבוי שניטלו קורותיו או לחייו\u0004 אם ארעו דברים אלה בשבת — \u0003מותרין\u0004 הדיירים בטלטול \u0003לאותה שבת ואסורין לעתיד לבא,\u0004 אלה \u0003דברי ר' יהודה.\u0004","\u0003ר' יוסי אומר: אם מותרין לאותה שבת\u0004 צריכים להיות \u0003מותרין\u0004 גם \u0003לעתיד לבא, ואם אסורין לעתיד לבא אסורין\u0004 גם \u0003לאותה שבת.\u0004 ומכיון שאכן אסורים לעתיד לבוא, אם כן אסורים גם כן לאותה שבת, ואין אומרים כיון שהותרה הותרה.","\u0003לימא\u0004 \u0005[האם נאמר]\u0006 כי \u0003רב הונא\u0004 ש\u0003אמר כר' יהודה\u0004 שקבע לפי כניסת השבת \u0003ור' יצחק\u0004 ש\u0003אמר כר' יוסי?\u0004","ודוחים: \u0003אמר לך\u0004 \u0005[יכול לומר לך]\u0006 \u0003רב הונא: אנא דאמרי\u0004 \u0005[אני שאמרתי]\u0006 דברי הרי הם מבוססים \u0003אפילו ל\u0004שיטת \u0003ר' יוסי\u0004. כי, \u0003עד כאן לא קאמר\u0004 \u0005[לא\u0006 שמענו \u0005שאמר]\u0006 \u0003ר' יוסי התם\u0004 \u0005[שם] —\u0006 \u0003אלא\u0004 במקרה \u0003דליתנהו\u0004 \u0005[שאין\u0006 קיימות \u0005להן]\u0006 \u0003למחיצות\u0004 המתירות. \u0003הכא איתנהו\u0004 \u0005[כאן יש\u0006 קיימות \u0005להן]\u0006 \u0003למחיצות.\u0004 והכל נדון לפי המחיצות, ואף לדעתו יהיה מותר בטלטול.","\u0003ור' יצחק אמר\u0004 (יכול לומר): \u0003אנא דאמרי\u0004 \u0005[אני שאמרתי]\u0006 דברי, יכולתי לבססם \u0003אפילו ל\u0004שיטת \u0003ר' יהודה\u0004 כי \u0003עד כאן לא קאמר\u0004 \u0005[לא\u0006 שמענו \u0005שאמר]\u0006 \u0003ר' יהודה התם\u0004 \u0005[שם]\u0006 \u0003אלא דאיתנהו לדיורין\u0004 \u0005[שישנם הדיורים] —\u0006 \u0003הכא ליתנהו לדיורין\u0004 \u0005[כאן אין הדיורים\u0006 מצויים עוד\u0005],\u0006 ואף לדעתו יהיה אסור בטלטול.","במשנה הובאו דברי \u0003חכמים\u0004 ה\u0003אומרים אחד משני דברים\u0004: או שתי או ערב מתיר. ושואלים: \u0003היינו תנא קמא\u0004 \u0005[הרי זה\u0006 בדיוק דברי \u0005התנא הראשון]\u0006 ומה חידשו החכמים האחרונים בכך?","ומשיבים: \u0003איכא בינייהו\u0004 \u0005[יש ביניהם]\u0006 הבדל מעשי ביחס ל\u0003יחיד\u0004 במקום \u0003ישוב\u0004; שהתנא הראשון לא התיר לכתחילה לסמוך על דרך זו של עשיית מחיצה וחכמים אחרונים התירו בכל מקרה.","\u0003ארבעה דברים פטרו במחנה\u0004 של אנשי צבא היוצאים למלחמה: \u0003מביאין עצים\u0004 להסקה \u0003מכל מקום\u0004 ואין חוששים משום גזל העצים מבעליהם. \u0003ופטורין מרחיצת ידים\u0004 לאוכל, ופטורין מלעשר תבואת \u0003דמאי,\u0004 תבואה שנלקחה מעם הארץ ואין ידוע אם היא מעושרת, שכרגיל חוזרים ומפרישים ממנה מעשר מספק, ופטורים \u0003מלערב\u0004 עירובי חצירות.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים\u0006 בתוספתא\u0005]:\u0006 \u0003מחנה היוצאת למלחמת הרשות מותרין בגזל עצים\u0004 לחים וכן \u0003יבשים. ר' יהודה בן תימא אומר: אף חונין בכל מקום\u0004 אפילו אם גורמים הם נזק לשדה שחונים בו. \u0003ובמקום שנהרגו שם נקברין\u0004 שאין כבודם בטלטול ממקום למקום ואין בעל המקום יכול לעכב.","ודנים בפרטי הדברים; לכאורה מהו החידוש ש\u0003\"מותרין בגזל עצים יבשים\"?\u0004 הרי \u0003האי תקנתא דיהושע הוה\u0004 \u0005[זו תקנה של יהושע היתה]\u0006 שכן \u0003אמר מר\u0004 \u0005[החכם]:\u0006 מסורת בידינו \u0003עשרה תנאים התנה יהושע\u0004 עם בני ישראל כשנכנסו לארץ וביניהם \u0003שיהו\u0004 בעלי בהמות \u0003מרעין\u0004 (שולחין למרעה) את צאנם \u0003בחורשין\u0004 (יערות) של אחרים ולא יקפידו עליהם. ושיהיו \u0003מלקטין עצים\u0004 לשימושם \u0003משדותיהן\u0004 של אחרים!","ומשיבים: \u0003התם\u0004 \u0005[שם]\u0006 בתנאי יהושע, מדובר רק \u0003בהיזמי והיגי\u0004 \u0005[מיני קוצים]\u0006 שאין מקפידים עליהם, \u0003הכא\u0004 \u0005[כאן]\u0006 במחנה מלחמה — התירו אפילו \u0003בשאר עצים.\u0004","\u0003אי נמי\u0004 \u0005[או גם כן],\u0006 \u0003התם\u0004 \u0005[שם]\u0006 מדובר \u0003ב\u0004זמן שהיו הקוצים \u0003מחוברין.\u0004 ונמצא שמועילים המלקטים לבעל השדה שהם מנכשים את הקוצים משדותיו. \u0003הכא\u0004 \u0005[כאן],\u0006 אפילו \u0003בתלושין.\u0004","\u0003אי נמי\u0004 \u0005[או גם כן]:\u0006 \u0003התם\u0004 \u0005[שם]\u0006 מדובר רק בקוצים \u0003לחין\u0004 שאינם ראויים מיד לשימוש להסקה ואין מקפידים עליהם, \u0003הכא\u0004 \u0005[כאן],\u0006 אפילו \u0003ביבשים\u0004.","הובאו קודם דברי \u0003ר' יהודה בן תימא\u0004 ה\u0003אומר\u0004 שאף \u0003חונין בכל מקום ו\u0004כן שחיילים \u0003במקום שנהרגים שם נקברים,\u0004 ומקשים: \u0003פשיטא\u0004 \u0005[פשוט,\u0006 ברור\u0005]\u0006 הלא חייל כזה \u0003מת מצוה הוא\u0004 וכלל בידינו: \u0003מת מצוה קונה מקומו\u0004 ואין בעל שדה יכול למנוע מלקבור מת מצוה במקום הימצאו!","ומשיבים: \u0003לא צריכא\u0004 \u0005[לא נצרכה\u0006 הלכה זו\u0005]\u0006 אלא \u0003אף על גב\u0004"],["\u0003דאית ליה\u0004 \u0005[שיש לו]\u0006 \u0003קוברין, דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003איזהו מת מצוה כל שאין לו קוברין,\u0004 אבל מי שיש לו קרובי משפחה שיטפלו בקבורתו אינו קרוי מת מצוה. וכן אם היה מצוי במקום ש\u0003קורא ואחרים עונין אותו — אין זה מת מצוה\u0004. ועל כן חידוש הוא באיש הצבא, שגם שאין בו תנאי מת מצוה קוברין אותו במקומו. ולעצם ההלכה שואלים: \u0003ו\u0004האם \u0003מת מצוה קנה מקומו? והא תניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003המוצא מת מוטל בסרטיא\u0004 (בדרך סלולה) — \u0003מפניהו וקוברו לימין אסרטיא או לשמאל אסרטיא\u0004 ואין קוברים אותו ברחוב.","","היה יכול לפנותו ל\u0003שדה בור\u0004 (בלתי מעובד) או ל\u0003שדה ניר\u0004 (חרוש) — \u0003מפניהו לשדה בור,\u0004 היו לפניו \u0003שדה ניר ושדה זרע — מפניהו לשדה ניר, היו שתיהן,\u0004 השדות, \u0003נירות\u0004 או \u0003שתיהן זרועות\u0004 או \u0003שתיהן בורות — מפניהו לכל רוח שירצה!\u0004 נמצא שאין קוברין מת מצווה בכל מקום, אלא מפנים אותו מהמקום שמת בו!","\u0003אמר רב ביבי: הכא\u0004 \u0005[כאן]\u0006 \u0003במת מוטל על המיצר\u0004 (גדר) וחוצה את דרך הרבים עד למיצר שכנגדו \u0003עסקינן\u0004 \u0005[עוסקים אנו],\u0006 ש\u0003מתוך שניתנה רשות לפנותו מן המיצר\u0004 שכן אסור יהיה לכהנים לעבור שם — \u0003מפניהו\u0004 כבר \u0003לכל רוח שירצה\u0004. אבל נמצא בשדה, אין רשות לפנותו משם. נאמר במשנה שאנשי המחנה \u0003פטורין מרחיצת ידים. אמר אביי: לא שנו אלא\u0004 שפטורין מ\u0003מים ראשונים\u0004 של נטילת ידים שלפני האוכל, \u0003אבל מים אחרונים — חובה.\u0004","","\u0003אמר רב חייא בר אשי: מפני מה אמרו מים אחרונים חובה — מפני שמלח סדומית\u0004 (הבא מסדום) \u0003יש, שמסמא את העינים\u0004 אף כשכמות קטנה ממנה נכנסת לעין, ולכן יש לרחוץ את הידים שמא דבק בהן מלח סדומי בשעת האכילה, וגם אנשי הצבא חייבים להיזהר בשמירת בריאותם.","\u0003אמר אביי: ומשתכחא כקורטא בכורא\u0004 \u0005[ונמצא\u0006 מלח זה \u0005כקורט\u0006 קטן \u0005ב\u0006תוך \u0005כור]\u0006 שלם של מלח. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רבא לרב אשי: כייל מילחא\u0004 \u0005[\u0006אם \u0005מדד מלח]\u0006 שלא בשעת אכילה, \u0003מאי\u0004 \u0005[מהו]?\u0006 האם גם הוא מחוייב בנטילת ידים לאחר מכן? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003הא לא מיבעיא\u0004 \u0005[זו לא נצרכה\u0006 לומר\u0005]\u0006 שבוודאי חייב.","במשנה נאמר שאנשי הצבא פטורים מלהפריש \u0003דמאי\u0004. \u0003דתנן\u0004 \u0005[ו\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003מאכילין את העניים דמאי ואת אכסניא\u0004 \u0005[צבא המלך]\u0006 \u0003דמאי. אמר רב הונא: תנא\u0004 \u0005[שנינו],\u0006 \u0003בית שמאי אומרים: אין מאכילין את העניים דמאי ואת אכסניא דמאי, ובית הלל אומרים: מאכילין את העניים דמאי ואת אכסניא דמאי.\u0004 במשנה נאמר שאנשי הצבא פטורים \u0003מלערב. אמרי דבי\u0004 \u0005[אמרו בני בית\u0006 מדרשו\u0005]\u0006 \u0003ר' ינאי: לא שנו אלא\u0004 שפטורין מלערב \u0003עירובי חצירות, אבל עירובי תחומין — חייבין\u0004.","","\u0003דתני\u0004 \u0005[ש\u0006כן \u0005שנה]\u0006 \u0003ר' חייא: לוקין על\u0004 יציאה מן התחום בלא \u0003עירובי תחומין — דבר תורה\u0004, וראיה לענין תחומין ממה שנאמר בתורה \"אל יצא איש ממקומו ביום השביעי\" (שמות טז, כט) וכיון שדבר תורה הוא אין להתירו בשעה שאינה של סכנת נפשות.","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003ר' יונתן: וכי לוקין על לאו\u0004 שבתורה שנאמר רק בלשון \u0003\"אל\"?\u0004 על שאלה זו \u0003מתקיף רב אחא בר יעקב: אלא מעתה\u0004 מה שנאמר \u0003\"אל תפנו אל האבת ואל הידענים\"\u0004 (ויקרא יט, לא) \u0003הכי נמי דלא לקי\u0004 \u0005[כך גם כן\u0006 תאמר \u0005שאינו לוקה]?!\u0006 אלא יש לתקן \u0003ר' יונתן הכי קשיא ליה\u0004 \u0005[כך היה קשה לו]:\u0006 הלא איסור זה על תחומין הוא \u0003לאו שניתן לאזהרת מיתת בית דין\u0004 שכן מאותו פסוק למדים איסור להוציא לרשות הרבים, והעובר על איסור זה נדון למיתת בית דין, וכלל בידינו: \u0003כל לאו שניתן\u0004 (שיש בו צד מסוים) \u0003לאזהרת מיתת בית דין — אין לוקין עליו\u0004 אפילו כאשר בפרט זה או במקרה זה אין צד של מיתת בית דין.","","\u0003אמר רב אשי: מי כתיב\u0004 \u0005[האם נאמר]\u0006 בכתוב \u0003\"אל יוציא\",\u0004 שעיקרו לאיסור הוצאה בשבת? הרי לשון \u0003\"אל יצא\" כתיב\u0004 \u0005[נאמר],\u0006 שפשוטו של מקרא זה שמדבר רק בדין יציאה מחוץ לתחום שבת ולא בהוצאה, ואין בכך — לכל הדעות — צד מיתת בית דין כלל.","","\u0003עושין פסין לביראות\u0004 \u0005[בארות]\u0006 שברשות הרבים, שכן הבאר עצמה כרגיל רחבה ארבעה טפחים ועמוקה עשרה ועל כן היא נחשבת כרשות היחיד ולכן אסור לשאוב ממנה בשבת, מפני שהוא מוציא מרשות היחיד לרשות הרבים. ולכן תיקנו חכמים שיעשו פסין כעין מחיצה סביב הבאר, ולהעלות מים בכלים ולהעבירם, ויעשה כל אותו שטח כרשות היחיד, ועל ידי כן מותר לשאוב מן הבאר ולהעביר את מימיו אל השטח המוקף מחיצה.","ועושין \u0003ארבעה דיומדין\u0004 (עמודים כפולים) \u0003נראין כשמונה\u0004 שמעמידים בכל פינה עמוד בעל שתי זרועות, ודיומדין אלה נחשבים כמחיצה גמורה, אלה \u0003דברי ר' יהודה. ר' מאיר אומר\u0004: יש להעמיד \u0003שמונה\u0004 עמודים ה\u0003נראין כשנים עשר,\u0004 כיצד? עושה \u0003ארבעה דיומדין\u0004 וביניהם \u0003ארבעה\u0004 עמודים \u0003פשוטין.\u0004","\u0003גובהן\u0004 של הדיומדין \u0003עשרה טפחים\u0004 לפחות, \u0003ורוחבן ששה ועוביים כל שהוא\u0004. \u0003וביניהן,\u0004 בין הדיומדין או העמודין יכול להיות רווח \u0003כמלא שתי רבקות\u0004 (צמדים) \u0003של שלש שלש בקר, דברי ר' מאיר.\u0004","\u0003ר' יהודה אומר:\u0004 רווח גדול קצת יותר \u0003של ארבע\u0004 פרות. ומשערים רווח זה של עשר אמות באמות מרווחות ולא מצומצמות, כאשר הפרות \u0003קשורות\u0004 זו לזו \u0003ולא מותרות\u0004 כאשר רבקה \u0003אחת נכנסת ואחת יוצאת\u0004 ויש רווח משהו ביניהן.","\u0003מותר להקריב\u0004 את הפסין \u0003לבאר, ובלבד\u0004 שיהא השטח הפנימי רחב מספיק כדי \u0003שתהא פרה\u0004 עומדת \u0003ראשה ורובה בפנים\u0004, בתחום מחיצת הדיומדין, \u0003ושותה.\u0004 \u0003מותר\u0004",""],["\u0003להרחיק\u0004 את הפסים ולהגדיל את ההיקף \u0003כל שהוא\u0004 כלומר כמה שירצה \u0003ובלבד שירבה בפסין\u0004 בין הדיומדים. \u0003ר' יהודה אומר\u0004: עושים היקף זה \u0003עד\u0004 שטח של \u0003בית סאתים\u0004 (חמשת אלפים אמות מרובעות).","\u0003אמרו לו: לא אמרו\u0004 שיעור \u0003בית סאתים אלא לגנה ולקרפף\u0004 (חצר גדולה לשים בה עצים וגרוטאות), \u0003אבל אם היה דיר או סהר\u0004 (מקום לבהמות) \u0003או מוקצה\u0004 (החצר שמאחורי הבית) \u0003או חצר\u0004 שלפני הבית — \u0003אפילו בית חמשת כורין אפילו בית עשרה כורין — מותר. ומותר להרחיק כל שהוא, ובלבד שירבה בפסין\u0004.","מציעים: \u0003לימא מתניתין דלא\u0004 \u0005[האם לומר\u0006 ש\u0005משנתינו אינה]\u0006 \u0003כ\u0004שיטת \u0003חנניא, דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003עושין פסין\u0004 מסביב \u0003לבור וחבלין\u0004 סביב \u0003לשיירא. וחנניא אומר: חבלין לבור, אבל לא פסין\u0004.","ודוחים: \u0003אפילו תימא\u0004 \u0005[תאמר]\u0006 כ\u0003חנניא — בור\u0004 של מים מכונסים יש לו דין \u0003לחוד\u0004 ו\u0003באר\u0004 מים נובעים \u0003לחוד.\u0004","\u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 קושיה זו בלשון אחרת: \u0003מדלא קתני\u0004 \u0005[מ\u0006מה \u0005שלא שנינו]\u0006 \u0003חנניא אומר: עושין חבלין לבור ופסין לבאר. מכלל\u0004 הדברים אתה שומע שלשיטת \u0003חנניא: לא שנא\u0004 \u0005[אינו שונה]\u0006 \u0003בור ולא שנא\u0004 \u0005[אינו שונה]\u0006 \u0003באר,\u0004 שבשניהם \u0003חבלים — אין\u0004 \u0005[כן],\u0006 מתירים, \u0003פסין — לא. לימא מתניתין\u0004 \u0005[האם לומר שמשנתנו]\u0006 היא ש\u0003לא כחנניא?\u0004","ודוחים: \u0003אפילו תימא\u0004 \u0005[תאמר]\u0006 שהיא כשיטת \u0003חנניא, למאי דקאמר תנא קמא קא מהדר ליה\u0004 \u0005[למה שאמר התנא הראשון הרי הוא משיב לו]\u0006 ולא בא לברר את שיטתו שלו ולהבדיל בין בור לבאר.","ומציעים עוד: \u0003לימא\u0004 \u0005[האם נאמר]\u0006 שמשנתינו ש\u0003לא כ\u0004שיטת \u0003ר' עקיבא? דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003אחד באר הרבים ובור הרבים ובאר היחיד עושין להן פסין, אבל בור היחיד עושין לו מחיצה\u0004 גמורה \u0003גבוה עשרה טפחים, דברי ר' עקיבא.\u0004","\u0003ואילו הכא קתני\u0004 \u0005[כאן שנה]:\u0006 עושים פסים \u0003לביראות,\u0004 ונדייק: \u0003לביראות\u0004 (בארות) — \u0003אין\u0004 \u0005[כן],\u0006 ואילו \u0003לבורות — לא,\u0004 והרי אמר ר' עקיבא שאף לבור הרבים עושים פסים.","ודוחים: \u0003אפילו תימא\u0004 \u0005[אפילו תאמר]\u0006 שמשנתנו כשיטת \u0003ר' עקיבא,\u0004 אלא \u0003באר מים חיים דפסיקא ליה\u0004 \u0005[שברור לו]\u0006 ואינו צריך לחלק בכך; \u0003לא שנא\u0004 \u0005[אינו שונה]\u0006 אם היא של \u0003רבים ולא שנא\u0004 \u0005[ואינו שונה]\u0006 של \u0003יחיד\u0004 שתמיד \u0005מותר,\u0006 \u0003קתני\u0004 \u0005[שנה]\u0006 אולם \u0003בור\u0004 שיש לו רק מים \u0003מכונסין דלא פסיקא ליה\u0004 \u0005[שלא ברור לו] —\u0006 \u0003לא קתני\u0004 \u0005[שנה].\u0006 אבל אין להוכיח מכאן שהוא חולק על ר' עקיבא.","ועוד מציעים: \u0003לימא מתניתין\u0004 \u0005[האם לומר שמשנתנו\u0006 אינה \u0003כ\u0004שיטת \u0003ר' יהודה בן בבא, דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003ר' יהודה בן בבא אומר: אין עושין פסין אלא לבאר הרבים בלבד, ואילו הכא קתני לביראות\u0004 \u0005[כאן שנה לבארות],\u0006 \u0003לא שנא\u0004 \u0005[אינו שונה]\u0006 אם היא של \u0003רבים ולא שנא\u0004 \u0005[ואינו שונה]\u0006 של \u0003יחיד!\u0004","ודוחים: \u0003אפילו תימא\u0004 \u0005[תאמר]\u0006 שמשנתנו כ\u0003ר' יהודה בן בבא, מאי ביראות\u0004 \u0005[מה הן בארות]\u0006 שהוזכרו — \u0003ביראות דעלמא\u0004 \u0005[בארות בכלל],\u0006 כלומר שהזכיר בארות בלשון רבים אבל כוונתו רק לסוג אחד של בארות, והוא בארות הרבים.","במשנה הוזכרו דיומדין, ושאלו: \u0003מאי\u0004 \u0005[מה הן]\u0006 \u0003דיומדין? אמר ר' ירמיה בן אלעזר: דיו\u0004 \u0005[שנים\u0006 ביוונית\u0005]\u0006 \u0003עמודין\u0004. שעושים עמוד אחד כפול.","ומכיון שהזכירו פירוש זה של הקידומת \"דיו\" מביאים עוד מלים בהן היא מופיעה. \u0003ד\"יו למ\"נודה שב\"ח זונ\"ית נתק\"לקל במיד\"ה שלש\"ה סימ\"ן.\u0004","\u0003תנן התם\u0004 \u0005[שנינו שם\u0006 במשנה\u0005],\u0006 \u0003ר' יהודה אומר: כל השיתין\u0004 (תאנים לא משובחות) \u0003פטורין\u0004 מלעשר, ואף על פי שהם דמאי, שכן וודאי עישר אותן כבר המוכר, אף שהוא עם הארץ, כיון שאינו מקפיד על הפסד זה, \u0003חוץ מן הדיופרא\u0004. ושאלו: מהו \u0003דיופרא? אמר עולא: אילן העושה דיו\u0004 \u0005[שני]\u0006 מחזורים של \u0003פירות בשנה\u0004.","ובדומה לזה \u0003אמר ר' ירמיה בן אלעזר: דיו\u0004 \u0005[שני]\u0006 \u0003פרצוף פנים היה לו לאדם הראשון\u0004: מלפנים ומאחור, שכן \u0003נאמר: \"אחור וקדם צרתני\u0004 ותשת עליו כפכה\" (תהילים קלט, ה), וכן \u0003כתיב\u0004 \u0005[נאמר]:\u0006 \u0003\"ויבן ה' אלהים את הצלע\u0004 אשר לקח מן האדם לאשה, ויבאה אל האדם\" (בראשית ב, כב) ונחלקו בדבר זה \u0003רב ושמואל: חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר\u0004 ש\u0003פרצוף\u0004 אחד היה כצורת נקבה וממנו יצר את חוה. \u0003וחד\u0004 \u0005[ואחד\u0006 מהם\u0005]\u0006 \u0003אמר:\u0004 שהיה לו \u0003זנב\u0004 ונטלו וממנו יצרה.","ושואלים: \u0003בשלמא למאן דאמר\u0004 \u0005[נניח\u0006 לשיטת \u0005מי שאומר]\u0006 \u0003פרצוף\u0004 \u0005—\u0006 \u0003היינו דכתיב\u0004 \u0005[זהו שנאמר]\u0006 \u0003\"אחור וקדם צרתני\"\u0004 שהיו לאדם שתי פרצופים. \u0003אלא למאן דאמר\u0004 \u0005[ל\u0006שיטת \u0005מי שאומר]\u0006 \u0003זנב\u0004 — \u0003מאי\u0004 \u0005[מה\u0006 \u0003משמעו\u0004\u0005]\u0006 \u0003של \"אחור וקדם צרתני\"?\u0004","ומשיבים שיש לפרש זאת במובן מוסרי, וכדברי \u0003ר' אמי,\u0004 ש\u0003אמר ר' אמי\u0004: האדם נברא \u0003אחור\u0004 (אחרון) \u0003למעשה בראשית, וקדם לפורענות\u0004.","ושואלים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003אחור למעשה בראשית דלא איברי עד מעלי שבתא\u0004 \u0005[שלא נברא עד ערב שבת],\u0006 \u0003אלא וקדם\u0004 (ראשון) \u0003לפורענות מאי היא\u0004 \u0005[מה הוא]?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003משום קללה\u0004 של חטא עץ הדעת — \u0003הא\u0004 \u0005[הרי]\u0006 \u0003בתחילה נתקלל נחש, ולבסוף נתקללה חוה, ולבסוף נתקלל אדם!\u0004","\u0003אלא\u0004 הכוונה היא \u0003ל\u0004פורענות ה\u0003מבול, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"וימח את כל היקום אשר על פני האדמה מאדם עד בהמה\u0004 עד רמש ועד עוף השמים\u0003\"\u0004 (בראשית ז, כג) שמתו בני האדם תחילה.","ועוד שואלים: \u0003בשלמא למאן דאמר\u0004 \u0005[נניח\u0006 לשיטת \u0005מי שאומר]\u0006 \u0003פרצוף, היינו דכתיב\u0004 \u0005[זהו שנאמר]\u0006 \u0003\"וייצר\u0004 את האדם\" \u0003תרין\u0004 \u0005[שני]\u0006 \u0003יודין;\u0004 אחד לאדם ואחד לחוה. \u0003אלא למאן דאמר\u0004 \u0005[ל\u0006שיטת \u0005מי שאומר]\u0006 \u0003זנב\u0004 — \u0003מאי\u0004 \u0005[מה\u0006 \u0003טעם\u0004\u0005]\u0006 \u0003נאמר בבריאת האדם \"וייצר\"?\u0004","ומשיבים שטעם הדבר \u0003כ\u0004דברי \u0003ר' שמעון בן פזי\u0004, ש\u0003אמר ר' שמעון בן פזי:\u0004 \"וייצר\" זה, כך יש לדורשו: \"וי יצר\", כלומר \u0003אוי\u0004 \u0005[ווי]\u0006 \u0003לי מיצרי\u0004 הרע אם אעשה רצון יוצרי ו\u0003אוי לי מיוצרי\u0004 (ה') אם אעשה רצון יצרי.","ועוד שואלים: \u0003בשלמא למאן דאמר\u0004 \u0005[נניח\u0006 לשיטת \u0005מי שאומר]\u0006 \u0003פרצוף\u0004 — \u0003היינו דכתיב\u0004 \u0005[זהו שנאמר]\u0006 \u0003\"זכר ונקבה בראם\u0004 ויברך אותם ויקרא את שמם אדם ביום הבראם\" (בראשית ה, ב) שמתחילת הבריאה יצר שני פרצופים אחד לזכר ואחד לנקבה \u0003אלא למאן דאמר\u0004 \u0005[ל\u0006שיטת \u0005מי שאומר]\u0006 \u0003זנב\u0004 — \u0003מאי\u0004 \u0005[מה\u0006 \u0003פירוש\u0004\u0005]\u0006 \u0003\"זכר ונקבה בראם\"?\u0004","ומשיבים שהוא \u0003כ\u0004דברי \u0003ר' אבהו\u0004, שכן \u0003ר' אבהו רמי\u0004 \u0005[השליך,\u0006 הראה סתירה\u0005],\u0006 \u0003כתיב\u0004 \u0005[נאמר]:\u0006 \u0003\"זכר ונקבה בראם\" וכתיב\u0004 \u0005[ו\u0006גם \u0005נאמר]\u0006 \u0003\"\u0004ויברא האלהים את האדם בצלמו \u0003בצלם אלהים ברא אתו\"\u0004 (בראשית א, כז) בלשון יחיד, אלא \u0003בתחלה עלתה במחשבה לבראות שנים, ולבסוף\u0004 למעשה \u0003לא נברא אלא אחד\u0004.","ועוד מקשים: \u0003בשלמא למאן דאמר\u0004 \u0005[נניח\u0006 לשיטת \u0005מי שאומר]\u0006 \u0003פרצוף, היינו דכתיב\u0004 \u0005[זהו שנאמר]:\u0006 \u0003\"\u0004ויקח אחת מצלעותיו \u0003ויסגור בשר תחתנה\"\u0004 (בראשית ב, כא) \u0003אלא למאן דאמר\u0004 \u0005[ל\u0006שיטת \u0005מי שאומר]\u0006 \u0003זנב\u0004 — \u0003מאי\u0004 \u0005[\u0006\u0003מהו] \"ויסגור בשר תחתנה\"?\u0004","\u0003אמר רב זביד ואיתימא\u0004 \u0005[ויש אומרים]\u0006 \u0003ר' ירמיה, ואיתימא\u0004 \u0005[ויש אומרים]\u0006 \u0003רב נחמן בר יצחק: לא נצרכה\u0004 סגירת הבשר \u0003אלא למקום חתך\u0004 בלבד שצריך היה לסגרו.","ומקשים שוב: \u0003בשלמא למאן דאמר זנב\u0004 \u0005[נניח\u0006 לשיטת \u0005האומר זנב]\u0006 — \u0003היינו דכתיב\u0004 \u0005[זהו שנאמר]:\u0006 \"\u0003ויבן\u0004 ה' אלוהים את הצלע \u0003\"\u0004, שהיה צורך לבנותה לדמות שלמה, \u0003אלא, למאן דאמר\u0004 \u0005[ל\u0006שיטת \u0005מי שאומר]\u0006 \u0003פרצוף\u0004 — \u0003מאי\u0004 \u0005[\u0006\u0003מהו] \"ויבן\"?\u0004","ומשיבים שהוא \u0003כ\u0004דברי \u0003ר' שמעון בן מנסיא, דדריש\u0004 \u0005[שדרש]\u0006 \u0003ר' שמעון בן מנסיא: \"ויבן ה' אלהים את הצלע\" — מלמד שקילעה הקדוש ברוך הוא לחוה\u0004 שקלע לה את שערות ראשה \u0003ו\u0004אחר כך \u0003הביאה לאדם הראשון, שכן בכרכי הים קורין לקלעיתא בנייתא\u0004 \u0005[קוראים לקליעת\u0006 שער \u0005בנייה]\u0006 —","\u0003דבר אחר: \"ויבן ה' אלהים\" אמר רב חסדא ואמרי לה במתניתא תנא\u0004 \u0005[ויש אומרים שבברייתא היא שנויה]\u0006 \u0003מלמד שבנאה הקדוש ברוך הוא לחוה כבנין\u0004"],["\u0003אוצר, מה אוצר זה רחב מלמטה וקצר\u0004 (צר) \u0003מלמעלה כדי לקבל את הפירות\u0004 בלי להתמוטט — \u0003אף האשה רחבה מלמטה וקצרה מלמעלה כדי לקבל את הולד\u0004. וכיון שהוזכר כתוב זה מביאים דרשה נוספת עליו.","\u0003\"ויביאה אל האדם\" — מלמד שעשה הקדוש ברוך הוא שושבינות לאדם הראשון\u0004 שטיפל ודאג לצורך נישואיו, והביא אליו את אשתו, \u0003מכאן ל\u0004אדם \u0003גדול שיעשה שושבינות לקטן ואל ירע לו,\u0004 אל יראה בכך פגיעה בכבודו.","ושואלים: \u0003למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 שהיתה \u0003פרצוף, הי מינייהו סגי ברישא\u0004 \u0005[איזה מהם הלך בראש]?\u0006 \u0003אמר רב נחמן בר יצחק: מסתברא דזכר סגי ברישא\u0004 \u0005[מסתבר שהזכר הלך בראש],\u0006 שכך היא דרך ארץ. \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003לא יהלך אדם אחורי אשה בדרך, ואפילו היא אשתו. נזדמנה על הגשר — יסלקנה לצדדין\u0004 שימהר בהליכתו עד שיהא מצידה ולא אחריה. \u0003וכל העובר אחורי אשה בנהר\u0004 שצריכה להרים בגדיה כדי לעבור — \u0003אין לו חלק לעולם הבא\u0004.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003המרצה\u0004 (סופר) \u0003מעות לאשה מידו לידה או מידה לידו בשביל שיסתכל בה, אפילו דומה\u0004 בשאר דברים \u0003למשה רבינו שקיבל תורה מהר סיני — לא ינקה מדינה של גיהנם. ועליו הכתוב אומר \"יד ליד לא ינקה רע\"\u0004 (משלי יא, כא) — \u0003לא ינקה מדינה של גיהנם.\u0004","\u0003אמר רב נחמן: מנוח עם הארץ היה, שנאמר: \"ויקם וילך מנוח אחרי אשתו\"\u0004 (שופטים יג, יא), שלא ידע דברי חכמים שאין ללכת אחרי אשה.","\u0003מתקיף לה\u0004 \u0005[הקשה על כך]\u0006 \u0003רב נחמן בר יצחק: אלא מעתה, גבי אלקנה\u0004 ד\u0003כתיב\u0004 \u0005[שנאמר]\u0006 בו: \u0003\"וילך אלקנה אחרי אשתו\" הכי נמי\u0004 \u0005[כך גם כן]\u0006 נאמר שאלקנה עם הארץ היה? \u0003וגבי אלישע\u0004 ד\u0003כתיב\u0004 \u0005[שנאמר]\u0006 בו: \u0003\"\u0004ותאמר אם הנער חי ה' וחי נפשך אם אעזבך \u0003ויקם וילך אחריה\"\u0004 (מלכים ב' ד, ל) \u0003הכי נמי\u0004 \u0005[כך גם כן]\u0006 תאמר שאלישע עם הארץ היה?","\u0003אלא\u0004: ודאי תפרש במקרים אלה שאין כוונת הפסוק שהלך אחריה ממש, אלא הלך \u0003אחרי דבריה ועצתה,\u0004 אם כן \u0003הכא נמי\u0004 \u0005[כאן\u0006 במנוח \u0005גם כן]\u0006 הלך \u0003אחרי דבריה ועצתה.\u0004","\u0003אמר רב אשי: ולמאי דאמר\u0004 \u0005[ולפי מה שאמר]\u0006 \u0003רב נחמן\u0004 ש\u0003מנוח עם הארץ היה, אפילו בי\u0004 \u0005[בבית]\u0006 \u0003רב נמי\u0004 \u0005[גם כן]\u0006 \u0003לא קרא\u0004 אף מקרא, ולא רק דברי חכמים. ד\u0003כתיב\u0004 \u0005[שנאמר]\u0006 במקרא \u0003\"ותקם רבקה ונערתיה ותרכבנה על הגמלים ותלכנה אחרי האיש\"\u0004 (בראשית כד, סא) ונדייק מלשון הכתוב: אחרי האיש \u0003ולא לפני האיש.\u0004","\u0003אמר ר' יוחנן\u0004: מוטב לו לאדם שיהלך \u0003אחרי ארי ולא אחרי אשה. אחרי אשה ולא אחרי עבודה זרה\u0004 כשתהלוכה שלה עוברת ברחוב, ונראה כמצטרף אליה. \u0003אחורי עבודה זרה ולא\u0004 לעבור \u0003אחורי בית הכנסת בשעה שמתפללין,\u0004 שנראה ככופר במי שהציבור מתפללים לו.","כיון שהובאו דברי אגדה של ר' ירמיה בן אלעזר מביאים עוד מדבריו. ש\u0003אמר ר' ירמיה בן אלעזר: כל אותן השנים שהיה אדם הראשון בנידוי\u0004 על חטא עץ הדעת \u0003הוליד רוחין ושידין ולילין שנאמר \"ויחי אדם שלשים ומאת שנה ויולד בדמותו כצלמו\u0004 ויקרא את שמו שת\" (בראשית ה, ג) \u0003מכלל דעד האידנא לאו כצלמו אוליד\u0004 \u0005[מכאן שעד עכשיו לא בצלמו הוליד]\u0006 אלא ברואים אחרים.","\u0003מיתיבי\u0004 \u0005[מקשים],\u0006 \u0003היה ר' מאיר אומר: אדם הראשון חסיד גדול היה, כיון שראה שנקנסה מיתה\u0004 לעולם \u0003על ידו, ישב בתענית מאה ושלשים שנה, ופירש מן האשה מאה ושלשים שנה, והעלה זרזי\u0004 (חגורות) \u0003תאנים על בשרו\u0004 כלבוש יחידי \u0003מאה ושלשים שנה.\u0004 ואם כן כיצד הוליד את השדים לעולם?","ומשיבים: \u0003כי קאמרינן\u0004 \u0005כאשר אומרים]\u0006 את הדבר \u0003ההוא,\u0004 הרי זה שנוצרו המזיקים \u0003בשכבת זרע דחזא לאונסיה\u0004 \u0005[שראה לאונסו],\u0006 וממנה עצמה נוצרו המזיקים.","\u0003ו\u0004עוד \u0003אמר ר' ירמיה בן אלעזר: מקצת שבחו של אדם אומרים בפניו, וכולו שלא בפניו. מקצת שבחו בפניו\u0004 ד\u0003כתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"\u0004ויאמר ה' לנח בא אתה וכל ביתך אל התיבה \u0003כי אתך ראיתי צדיק לפני בדור הזה\"\u0004 (בראשית ז, א)","ו\u0003כולו שלא בפניו\u0004 — ד\u0003כתיב\u0004 \u0005[שנאמר]:\u0006 \"אלה תולדות נח \u0003נח איש צדיק תמים היה בדרתיו\u0004 את האלהים התהלך נח\" (בראשית ו, ט) שלא בפניו קראו ה' — צדיק תמים.","\u0003ו\u0004עוד \u0003אמר ר' ירמיה בן אלעזר: מאי\u0004 ד\u0003כתיב\u0004 \u0005[מהו שנאמר]:\u0006 \"ותבוא אליו היונה לעת ערב \u0003והנה עלה זית טרף בפיה\u0004 וידע נח כי קלו המים מעל הארץ\" (בראשית ח, יא) — \u0003אמרה יונה לפני הקדוש ברוך הוא: רבונו של עולם, יהיו מזונותי מרורין כזית ומסורין בידך, ואל יהיו מתוקין כדבש ותלוין ביד בשר ודם\u0004. וכדי להסביר משמעות הדבר: \u0003כתיב הכא\u0004 \u0005[נאמר כאן]\u0006 \u0003\"טרף\" וכתיב התם\u0004 \u0005[ונאמר שם]\u0006 \u0003\"הטריפני לחם חקי\"\u0004 (משלי ל, ח).","\u0003ו\u0004עוד \u0003אמר ר' ירמיה בן אלעזר: כל בית שנשמעין בו דברי תורה בלילה, שוב אינו נחרב, שנאמר \"ולא אמר איה אלוה עשי נתן זמירות בלילה\"\u0004 (איוב לה, י) שהנותן בביתו זימרה של תורה לא יצטרך לקונן על חורבן ביתו.","\u0003ו\u0004עוד \u0003אמר ר' ירמיה בן אלעזר: מיום שחרב בית המקדש דיו לעולם שישתמש\u0004 לשבח את השם, או לברך איש את רעהו בשם, \u0003בשתי אותיות\u0004 בלבד מן השם המפורש, \u0003שנאמר \"כל הנשמה תהלל יה הללויה\"\u0004 (תהילים קנ, ו), ואין כל השם כולו (בארבע אותיות) נזכר.","\u0003ו\u0004עוד \u0003אמר ר' ירמיה בן אלעזר\u0004: כש\u0003נתקללה בבל — נתקללו שכיניה\u0004 עמה. כש\u0003נתקללה שומרון — נתברכו שכיניה\u0004. ומפרש: \u0003נתקללה בבל נתקללו שכיניה\u0004 — ד\u0003כתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ושמתיה למורש קפד ואגמי מים\"\u0004 (ישעיה יד, כג), שהחיות הרעות באות ומזיקות גם לשוכנים מסביב. \u0003נתקללה שומרון נתברכו שכיניה\u0004 — ד\u0003כתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ושמתי שמרון לעי השדה\u0004"],["\u0003למטעי כרם\"\u0004 (מיכה א, ו) שכל בני הסביבה נהנים מהם.","\u0003ו\u0004עוד \u0003אמר ר' ירמיה בן אלעזר: בא וראה שלא כמדת הקדוש ברוך הוא מדת בשר ודם; מדת בשר ודם מתחייב אדם הריגה למלכות, מטילין לו חכה\u0004 (מכשיר ברזל או עץ להחזיק את הפה) \u0003לתוך פיו, כדי שלא יקלל את המלך\u0004 כשמוציאים אותו להורג.","ואילו \u0003מדת הקדוש ברוך הוא, אדם מתחייב הריגה למקום —\u0004 הרי הוא \u0003שותק\u0004 מרצונו, \u0003שנאמר: \"לך דמיה תהלה\u0004 אלהים בציון ולך ישולם נדר\u0003\"\u0004 (תהילים סה, ב). \u0003ולא עוד אלא שמשבח\u0004 את ה' על יסוריו, \u0003שנאמר \"תהלה\". ולא עוד אלא שדומה לו כאילו מקריב קרבן\u0004 לכפר על חטאיו, \u0003שנאמר \"ולך ישלם נדר\".\u0004","\u0003היינו\u0004 \u0005[זה הוא]\u0006 ש\u0003אמר ר' יהושע בן לוי: מאי דכתיב\u0004 \u0005[מהו שנאמר]\u0006 \u0003\"עברי בעמק הבכא מעין ישיתוהו גם ברכות יעטה מורה\"\u0004 (תהילים פד, ז).","\u0003\"עברי\" — אלו בני אדם שעוברין על רצונו של הקדוש ברוך הוא. \"עמק\"\u0004 — עונשם הוא \u0003שמעמיקין להם גיהנם. \"הבכא\" — שבוכין ומורידין דמעות כמעיין של שיתין,\u0004 כלומר כמעיין שיורד ומגיע עד יסודות הארץ (\"מעין ישיתוהו\"). \u0003\"גם ברכות יעטה מורה\"\u0004 — \u0003שמצדיקין עליהם את הדין, ואומרים לפניו: רבונו של עולם, יפה דנת, יפה זכית, יפה חייבת, ויפה תקנת גיהנם לרשעים וגן עדן לצדיקים\u0004.","ומקשים: \u0003איני\u0004 \u0005[וכי כן הוא]?!\u0006 \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אמר ר' שמעון בן לקיש: רשעים אפילו על פתחו של גיהנם אינם חוזרין בתשובה, שנאמר: \"ויצאו וראו בפגרי האנשים הפשעים בי\u0004 כי תולעתם לא תמות ואשם לא תכבה והיו דראון לכל בשר\" (ישעיה סו, כד) \"\u0003שפשעו\" לא נאמר, אלא \"הפשעים\"\u0004 בלשון הווה — \u0003שפושעים והולכין לעולם!\u0004","ומתרצים: \u0003לא קשיא\u0004 \u0005[אינו קשה]\u0006 \u0003הא\u0004 \u0005[זה]\u0006 שאמרנו שמצדיקים את הדין — מדבר \u0003בפושעי ישראל, הא\u0004 \u0005[זה]\u0006 שאינם חוזרים בהם — \u0003בפושעי אומות העולם.\u0004","\u0003הכי נמי מסתברא\u0004 \u0005[כך גם כן מסתבר\u0006 לומר\u0005],\u0006 ש\u0003אם\u0004 לא תאמר \u0003כן, קשיא\u0004 \u0005[קשה]\u0006 מדברי \u0003ריש לקיש אדריש לקיש\u0004 \u0005[על\u0006 דברי \u0005ריש לקיש]\u0006 ש\u0003אמר ריש לקיש: פושעי ישראל אין אור\u0004 (אש) \u0003גיהנם שולטת בהן, קל וחומר ממזבח הזהב.\u0004","\u0003מה מזבח הזהב\u0004 במקדש, \u0003שאין עליו אלא כעובי דינר זהב, עמד כמה שנים ולא שלטה בו האור,\u0004 שלא נמס זהבו. \u0003פושעי ישראל, שמליאין מצו‍ת כרמון, שנאמר: \"כפלח הרמון רקתך\"\u0004 (שיר השירים ו, ז) \u0003ואמר ר' שמעון בן לקיש: אל תיקרי \"רקתך\" אלא ריקתיך, שאפילו ריקנין שבך מליאין מצו‍ת כרמון — על אחת כמה וכמה\u0004 שאין אור הגיהנום שולט בהם.","\u0003אלא הא דכתיב\u0004 \u0005[זה שנאמר]\u0006 \u0003\"עברי בעמק הבכא\",\u0004 שמובן מכאן שבכל זאת יורדים הם לגיהנום — יש להסביר: \u0003\"ההוא דמחייבי ההיא שעתא בגיהנם\u0004 \u0005[ההוא\u0006 מדובר שהם \u0005מתחייבים אותה שעה לגיהנום],\u0006 \u0003ו\u0004אולם \u0003אתי\u0004 \u0005[ובא]\u0006 \u0003אברהם אבינו ומסיק להו ומקבל להו\u0004 \u0005[ומעלה אותם ומקבל אותם].\u0006 שאינו מניח לפניו את הנימולים להיכנס לגיהנום. \u0003בר\u0004 \u0005[חוץ]\u0006 \u0003מישראל\u0004 יהודי \u0003שבא על בת גוי, דמשכה\u0004 \u0005[שנמשכת]\u0006 כעונש \u0003ערלתו ולא מבשקר ליה\u0004 \u0005[מכיר בו]\u0006 אברהם אבינו שהוא מזרעו.","על עיקר הדבר \u0003מתקיף לה\u0004 \u0005[מקשה עליו]\u0006 \u0003רב כהנא: השתא\u0004 \u0005[עכשיו]\u0006 ש\u0003אמרת \"הפשעים\"\u0004 משמעו: \u0003דפשעי ואזלי\u0004 \u0005[שפושעים והולכים],\u0006 \u0003אלא מעתה\u0004 אותם מקראות \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 בהם \u0003\"המוציא\" ו\"המעלה\"\u0004 את ישראל ממצרים, האם משמע לשונות אלה: \u0003דמסיק ודמפיק\u0004 \u0005[שמעלה ושמוציא]\u0006 \u0003הוא\u0004 עכשיו?! \u0003אלא\u0004 עליך להבין שהכוונה \u0003דאסיק ודאפיק\u0004 \u0005[שהעלה והוציא]\u0006 כבר, \u0003הכי נמי\u0004 \u0005[כך גם כן] —\u0006 \"הפושעים\" משמעו \u0003דפשעי הוא\u0004 \u0005[שפשעו כבר].\u0006","\u0003ו\u0004עוד \u0003אמר ר' ירמיה בר אלעזר: שלשה פתחים יש לגיהנם, אחד במדבר ואחד בים ואחד בירושלים\u0004. פתח \u0003במדבר,\u0004 ד\u0003כתיב\u0004 \u0005[שנאמר]\u0006 בקורח ועדתו: \u0003\"וירדו הם וכל אשר להם חיים שאלה\u0004 ותכס עליהם הארץ ויאבדו מתוך הקהל\u0003\"\u0004 (במדבר טז, לג);","\u0003בים\u0004 יש פתח לגיהנם, ד\u0003כתיב\u0004 \u0005[שנאמר]:\u0006 ביונה בהיותו במעי הדג: \u0003\"מבטן שאול שועתי שמעת קולי\"\u0004 (יונה ב, ג);","ו\u0003בירושלים\u0004 יש פתח לגיהנם, ד\u0003כתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"נאם ה' אשר אור לו בציון ותנור לו בירושלים\"\u0004 (ישעיה לא, ט). \u0003ותנא דבי\u0004 \u0005[ושנה\u0006 החכם \u0005בבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל: \"אשר אור לו בציון\" — זו גיהנם, \"ותנור לו בירושלים\" — זו פתחה של גיהנם\u0004.","ושואלים: \u0003ותו ליכא\u0004 \u0005[ויותר\u0006 פתחים \u0005אין]?\u0006 \u0003והאמר ר' מריון אמר ר' יהושע בן לוי, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 \u0003תנא\u0004 \u0005[שנה]\u0006 \u0003רבה בר מריון בדבי\u0004 \u0005[ב\u0006שם \u0005בני בית\u0006 מדרשו\u0005]\u0006 של \u0003ר' יוחנן בן זכאי: שתי תמרות יש בגי בן הנום ועולה עשן מביניהן,\u0004 ועל תמרות אלו שהן שונות משאר דקלים \u0003זו היא ששנינו: ציני\u0004 \u0005[דקלי]\u0006 \u0003הר הברזל כשירות\u0004 למצוות לולב, \u0003וזו היא פתחה של גיהנם\u0004. ומשיבים שאין זו קושיה — \u0003דילמא היינו דירושלים\u0004 \u0005[שמא זה הוא\u0006 הפתח \u0005שבירושלים]\u0006","\u0003אמר ר' יהושע בן לוי: שבעה שמות יש לגיהנם, ואלו הן: שאול, ואבדון, ובאר שחת, ובור שאון, וטיט הי ון, וצלמות, וארץ התחתית.\u0004","\u0003שאול,\u0004 ד\u0003כתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"מבטן שאול שועתי שמעת קולי\"\u0004 (יונה ב, ג). \u0003אבדון,\u0004 ד\u0003כתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"היספר בקבר חסדך אמונתך באבדון\"\u0004 (תהילים פח, יב). \u0003באר שחת,\u0004 ד\u0003כתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"כי לא תעזב נפשי לשאול לא תתן חסידך לראות שחת\"\u0004 (תהילים טז, י). וב\u0003ור שאון וטיט הי ון,\u0004 ד\u0003כתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ויעלני מבור שאון מטיט היון\"\u0004 (תהילים מ, ג). \u0003וצלמות,\u0004 ד\u0003כתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ישבי חשך וצלמות אסירי עני וברזל\" (תהילים קז, י). וארץ התחתית — גמרא\u0004 \u0005[מסורת לימוד]\u0006 היא שכך שמו.","ושואלים: \u0003ותו ליכא\u0004 \u0005[ויותר\u0006 שמות \u0005אין]?\u0006 \u0003והאיכא\u0004 \u0005[והרי יש]\u0006 \u0003גיהנם!\u0004 ועונים שזה אינו שם כי אם כינוי — \u0003גיא שעמוקה כגיהנם,\u0004 או \u0003שהכל יורד לה על עסקי הנם,\u0004 ומפרש \"הנם\" כמו: חנם, לשווא.","ומקשים: והרי יש שם \u0003תפתה,\u0004 ד\u0003כתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"כי ערוך מאתמול תפתה\"\u0004 (ישעיה ל, לג) ועונים \u0003ההוא\u0004 שגם זה כינוי הוא והכוונה \u0003שכל המתפתה ביצרו יפול שם\u0004.","כיון שדובר בגיהנם מזכירים גם עניינו של פתח \u0003גן עדן. אמר ריש לקיש: אם בארץ ישראל הוא — בית שאן פתחו, ואם בערביא — בית גרם פתחו, ואם בין הנהרות\u0004 בבבל \u0003הוא — דומסקנין פתחו.\u0004 שבמקומות אלה יש שפע גדול של צמחים וארץ פוריה. ומספרים כי \u0003אביי\u0004 היה \u0003משתבח בפירי דמעבר ימינא\u0004 \u0005[בפירות שמעברו הימני]\u0006 של נהר הפרת, ו\u0003רבא\u0004 היה \u0003משתבח בפירי\u0004 \u0005[בפירות]\u0006 \u0003הרפניא\u0004.","נאמר במשנה: \u0003וביניהן בין הפסים כמלוא שתי\u0004 צמדי פרות קשורות ולא מותרות. ושואלים: \u0003פשיטא\u0004 \u0005[ברור,\u0006 מובן\u0005]\u0006 \u0003כיון דתנא ליה\u0004 \u0005[ששנה לו]\u0006 ש\u0003קשורות הוו\u0004 \u0005[הן],\u0006 \u0003אנן ידעינן דלא הוו\u0004 \u0005[אנו יודעים שאין הן]\u0006 \u0003מותרות!\u0004","ומשיבים: \u0003מהו דתימא\u0004: \u0005[שתאמר]\u0006 \u0003קשורות\u0004 משמעו \u0003כעין קשורות\u0004 שקרובות הן זו לזו \u0003אבל ממש לא\u0004 — על כן \u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 שלא די שהן סמוכות אלא קשורות ממש.","נאמר במשנה \u0003\"אחת נכנסת ואחת יוצאת\" תנא\u0004 \u0005[שנינו\u0006 בתוספתא\u0005]\u0006 להבהיר: \u0003רבקה\u0004 \u0005[צמד]\u0006 \u0003נכנסת ורבקה יוצאת\u0004. \u0003תנו רבנן\u0004 \u0005[שנו חכמים\u0006 בברייתא\u0005]:\u0006 \u0003כמה ראשה ורובה של פרה — שתי אמות. וכמה עוביה של פרה — אמה ושני שלישי אמה\u0004."],["\u0003שהן כעשר\u0004 אמות, אלו \u0003דברי ר' מאיר. ר' יהודה אומר\u0004 לשיטתו: \u0003כשלש עשרה אמה וכארבע עשרה אמה.\u0004","ומתחילה תוהים: מדוע אמר \u0003\"כעשר\"\u0004, שמשמעו בערך עשר? \u0003הא\u0004 \u0005[הלא]\u0006 \u0003עשר\u0004 בדיוק \u0003הויין\u0004 \u0005[הן]!\u0006 ומשיבים: \u0003משום דבעי למיתנא סיפא\u0004 \u0005[שרצה לשנות בסוף]\u0006 \u0003\"כשלש עשרה\",\u0004 שנה אף בתחילה \"כעשר\".","ושואלים: כיצד אמר \u0003\"כשלש עשרה\"\u0004 הלא \u0003טפי הויין\u0004 \u0005[יותר הן]!?\u0006 ומשיבים: \u0003משום דבעי למתני\u0004 \u0005[שרצה לשנות]\u0006 \u0003\"כארבע עשרה\".\u0004 ושואלים: \u0003וכארבע עשרה הא לא הויין\u0004 \u0005[הלא אינו].\u0006 \u0003אמר רב פפא: יתירות על שלש עשרה\u0004 שליש אמה, \u0003ואינן מגיעות לארבע עשרה.\u0004","\u0003אמר רב פפא: בבור\u0004 שרוחבו כשלעצמו \u0003שמונה\u0004 אמות \u0003דכולי עלמא לא פליגי דלא בעינן\u0004 \u0005[הכל אינם חולקים שאין צורך]\u0006 להעמיד פסים \u0003פשוטין\u0004 בין הדיומדין. שכן רוחב הבור בתוספת הרווח הדרוש לעמידת הפרה מסביב לבור, שהוא כשתי אמות לכל צד, מגיע לשתים עשרה אמות. ונמצא שהרווח שבין הדיומדין, לאחר ניכוי מקומם שהוא שתי אמות לכל צד, עשר אמות. ובכך ר' מאיר מתיר ואומר שאין צורך להוסיף.","\u0003בבור\u0004 שרחבו \u0003שתים עשרה\u0004 אמה — \u0003דכולי עלמא לא פליגי דבעינן פשוטין\u0004 \u0005[הכל אינם חולקים שצריכים אנו פשוטים]\u0006 שאז גם אם מוסיף רק שתי אמות לכל צד בשביל הפרות נמצא השטח שש עשרה אמה והרווח המינימאלי בין הדיומדין ארבע עשרה אמה, שגם לשיטת ר' יהודה צריך סתימה.","\u0003כי פליגי\u0004 \u0005[כאשר נחלקו] —\u0006 היה זה \u0003משמונה עד שתים עשרה\u0004 אמות. שלשיטת \u0003ר' מאיר בעינן\u0004 \u0005[צריכים אנו]\u0006 להוסיף \u0003פשוטין\u0004. ולשיטת \u0003ר' יהודה לא בעינן\u0004 \u0005[אין אנו צריכים]\u0006 \u0003פשוטין\u0004.","ושואלים: \u0003ורב פפא מאי קא משמע לן\u0004 \u0005[מה השמיע לנו]?\u0006 הלא כבר \u0003תנינא\u0004 \u0005[שנינו]\u0006 שלדעת ר' מאיר הרווח הוא כעשר אמות בלבד, ולדעת ר' יהודה הוא קצת יותר משלש עשרה אמות?!","ומשיבים: אכן, עבורנו אין בכך חידוש אולם \u0003רב פפא\u0004 ה\u0003ברייתא לא שמיע ליה, וקא משמע לן\u0004 \u0005[לא היתה ידועה לו והשמיע לנו]\u0006 מעצמו \u0003כ\u0004דברי הב \u0003רייתא\u0004 הזאת.","\u0003ארי\"ך יות\"ר בת\"ל חיצ\"ת חצ\"ר שיבש\"ה\u0004 הרי זה \u0003סימן\u0004 לעניינים שיובאו במהלך הדברים הבאים. \u0003בעא מיניה\u0004 \u0005[שאל ממנו]\u0006 \u0003אביי מרבה: האריך בדיומדין\u0004 שהוסיף על כל זרוע שלהם \u0003כשיעור פשוטין\u0004 עוד אמה אחת, ואין הרווח עומד עכשיו על יותר מעשר אמות, לשיטת \u0003ר' מאיר מהו,\u0004 האם נאמר שדי בכך ושוב אינו צריך להעמיד פסים פשוטים, או שמא יש צורך דווקא בהעמדת פסים בחלל?","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 כבר \u0003תניתוה\u0004 \u0005[שניתם אותה]\u0006 שכן למדנו: \u0003\"ובלבד שירבה בפסין\" מאי לאו\u0004 \u0005[האם לא]\u0006 הכוונה ש\u0003מאריך בדיומדין?\u0004 ודוחים: \u0003לא,\u0004 הכוונה היא \u0003דמפיש ועביד\u0004 \u0005[שמרבה ועושה]\u0006 פסים \u0003פשוטין.\u0004","אמר לו: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 \u0003האי\u0004 \u0005[\u0006לשון \u0005זו]\u0006 \u0003\"ובלבד שירבה בפסין\"\u0004 אינה מדוייקת, שמשמעה שמוסיף בפסים עצמם, ובמקום זה \u0003\"עד שירבה פסין\" מיבעי ליה\u0004 \u0005[צריך\u0006 היה \u0005לו\u0006 לומר\u0005]!\u0006 ענה לו: אין להקפיד בכך, \u0003תני\u0004 \u0005[שנה,\u0006 למד\u0005]\u0006 \u0003\"עד שירבה פסין\"\u0004.","אותו ענין נאמר גם בגירסה אחרת: \u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003תניתוה\u0004 \u0005[\u0006כבר \u0005שניתם אותה]\u0006 \u0003\"ובלבד שירבה בפסין\". מאי לאו\u0004 \u0005[האם לא]\u0006 הכוונה \u0003דמפיש ועביד\u0004 \u0005[שמרבה ועושה]\u0006 \u0003פשוטין?\u0004 ודחה: \u0003לא,\u0004 אולי הכוונה ש\u0003מאריך בדיומדין.\u0004","ומעירים: \u0003הכי נמי מסתברא\u0004 \u0005[כך גם כן מסתבר],\u0006 \u0003מדקתני\u0004 \u0005[מ\u0006מה \u0005ששנינו]\u0006 \u0003\"ובלבד שירבה בפסין\"\u0004 משמע יאריך את הפסים עצמם. ומסכמים: אכן \u0003שמע מינה\u0004 \u0005[למד ממנה].\u0006","\u0003בעא מיניה\u0004 \u0005[שאל ממנו]\u0006 \u0003אביי מרבה: יותר משלש עשרה אמה ושליש ל\u0004שיטת \u0003ר' יהודה מהו? פשוטין עביד\u0004 \u0005[עושה]\u0006 \u0003או בדיומדין מאריך?\u0004","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003תניתוה\u0004 \u0005[\u0006כבר \u0005שניתם אותה]\u0006 כעין זה: \u0003כמה הן\u0004 הדיומדים צריכים להיות \u0003מקורבין ל\u0004בור — \u0003כדי ראשה ורובה של פרה. וכמה מרוחקין\u0004 — אם ירצה \u0003אפילו\u0004 שטח בית \u0003כור ואפילו כוריים,\u0004 ובלבד שירבה בפסים כדי למעט הפרצות.","\u0003ר' יהודה אומר: בית סאתים — מותר\u0004 להקיף כך, \u0003יותר מבית סאתים — אסור. אמרו לו לר' יהודה\u0004: וכי \u0003אי\u0004 (אין) \u0003אתה מודה בדיר וסהר ומוקצה וחצר, אפילו בת חמשת כורים ואפילו בת עשרה כורים שמותר\u0004 להשתמש בה?","\u0003אמר להן\u0004: יש הבדל גדול, כי \u0003זו\u0004 מסביב לדיר וסהר \u0003מחיצה\u0004 גמורה היא, \u0003ואלו פסין\u0004 בלבד.","ומעתה בשאלתנו: \u0003ואם איתא\u0004 \u0005[יש,\u0006 נכון\u0005]\u0006 שמאריכים בדיומדין, הרי משמעו של דבר שעשה סביב לבאר מחיצה גמורה של דיומדין המתארכים והולכים, וכמוה כמחיצת דיר וסהר, ולכן \u0003זו מחיצה וזו היא מחיצה מיבעי ליה\u0004 \u0005[היה צריך לו\u0006 לומר\u0005]!\u0006","ומשיבים: אין להביא מכאן ראיה, כי \u0003הכי קאמר\u0004 \u0005[כך אמר]:\u0006 \u0003זו\u0004 הדיומדים שסביב לחצר \u0003תורת מחיצה עליה, ופרצותיה בעשר, ואלו\u0004 המקיפים את הבאר ומצמצמים את רוחב הפרצות, \u0003תורת פסין עליהן — ופרצותיהן\u0004 הפרצות שביניהם אינן עולות על \u0003שלש עשרה אמה ושליש,\u0004 שאם תאמר שהוא מאריך את הדיומדים, אינו אלא כמחיצה ממש, ולכן אין להוכיח מכאן.","ועוד \u0003בעא מיניה\u0004 \u0005[שאל ממנו]\u0006 \u0003אביי מרבה: תל\u0004 המתרומם ו\u0003מתלקט\u0004 לגובה זקוף של \u0003עשרה\u0004 טפחים \u0003מתוך\u0004 שיפוע של \u0003ארבע\u0004 אמות, האם \u0003נידון משום דיומד או אינו נידון משום דיומד?\u0004","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003תניתוה\u0004 \u0005[\u0006כבר \u0005שניתם אותה\u0006 בברייתא\u0005].\u0006 שכן שנינו, \u0003ר' שמעון בן אלעזר אומר: היתה שם אבן מרובעת רואין, כל\u0004 שהיתה האבן גדולה \u0003שאילו תחלק ויש בה אמה לכאן ואמה לכאן — נידון משום דיומד, ואם לאו — אינו נידון משום דיומד.\u0004","\u0003ר' ישמעאל בנו של ר' יוחנן בן ברוקה אומר: היתה שם אבן עגולה\u0004 בפינת הבאר, \u0003רואין כל\u0004 שהיתה האבן גדולה \u0003שאילו תחקק ותחלק\u0004 שיעשה ממנה אבן מרובעת \u0003ויש בה\u0004 שיעור \u0003אמה לכאן ואמה לכאן — נידון משום דיומד ואם לאו אינו נידון משום דיומד.\u0004 מכל מקום, מדברי שניהם למדנו שאפשר להשתמש בכל דבר בתורת דיומד אם יש בו כשיעור.","לגוף הברייתא שואלים: \u0003במאי קא מפלגי\u0004 \u0005[במה נחלקו\u0006 שני תנאים אלה\u0005]?\u0006 ומשיבים: \u0003מר\u0004 \u0005[חכם זה,\u0006 ר' שמעון בן אלעזר\u0005]\u0006 \u0003סבר: חד\u0004 \u0005[\u0006פעם \u0005אחת]\u0006 \u0003רואין אמרינן\u0004 \u0005[אומרים אנו],\u0006 \u0003תרי\u0004 \u0005[שתי]\u0006 פעמים \u0003רואין — לא אמרינן\u0004 \u0005[איננו אומרים]\u0006 כלומר; דיינו שאנו אומרים שרואים את האבן כאילו נחלקה, אבל אין אומרים פעם נוספת \"רואין שנחקקה\", ו\u0003מר\u0004 \u0005[וחכם זה,\u0006 ר' ישמעאל בנו של ר' יוחנן בן ברוקה\u0005]\u0006 \u0003סבר: אפילו תרי\u0004 \u0005[שתי]\u0006 פעמים \u0003רואין נמי אמרינן\u0004 \u0005[גם כן אומרים אנו].\u0006 ואם כן הוא הדין לתל הדומה לאבן עגולה, שנידון אף הוא משום דיומד.","ועוד \u0003בעא מיניה\u0004 \u0005[שאל ממנו]\u0006 \u0003אביי מרבה: חיצת הקנים\u0004 (מחיצת קנים העומדת כעין דיומד) והיו בה \u0003קנה קנה פחות משלשה\u0004 טפחים זה מזה, שדינם כלבוד, האם \u0003נידון משום דיומד או לא?\u0004","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003תניתוה\u0004 \u0005[\u0006כבר \u0005שניתם אותה\u0006 בברייתא\u0005].\u0006 שכן שנינו: \u0003היה שם אילן או גדר או חיצת הקנים — נידון משום דיומד. מאי לאו\u0004 \u0005[האם לא]\u0006 הכוונה שהיו בחיצת הקנים \u0003קנה קנה פחות משלשה?\u0004","ודוחים: \u0003לא,\u0004 מדובר כאן \u0003בגודריתא דקני\u0004 \u0005[בסבך של קנים]\u0006 הצמודים זה לזה ויוצרים כעין עמוד. ומקשים: \u0003אי הכי — היינו\u0004 \u0005[אם כך הרי זה]\u0006 \u0003אילן,\u0004 ובודאי לא חזר התנא על אותו דבר פעמיים.","טענה זו נדחית: \u0003אלא מאי\u0004 \u0005[מה\u0006 תאמר\u0005]\u0006 שחיצת הקנים היא \u0003קנה קנה פחות משלשה,\u0004 אם כן לדעתך \u0003היינו\u0004 \u0005[הרי זה]\u0006 \u0003גדר! אלא מאי אית לך למימר\u0004 \u0005[מה יש לך לומר]\u0006 ולהסביר ששנה \u0003תרי גווני\u0004 \u0005[שני מיני]\u0006 \u0003גדר! הכא נמי\u0004 \u0005[כאן גם כן]\u0006 שנה \u0003תרי גווני\u0004 \u0005[שני מיני]\u0006 \u0003אילן,\u0004 ואין איפוא להוכיח מכאן לענייננו.","\u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 שלא כך היתה השאלה, אלא \u0003גודריתא דקני קא מיבעיא ליה\u0004 \u0005[סבך של קנים\u0006 צפוף \u0005הוא שנשאלה לו],\u0006 \u0003גודריתא דקני מאי\u0004 האם נחשבת היא כדיומד. \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003תניתוה\u0004 \u0005[\u0006כבר \u0005שניתם אותה\u0006 בברייתא\u0005].\u0006 שכן שנינו: \u0003היה שם גדר או אילן או חיצת הקנים — נידון משום דיומד. מאי לאו, גודריתא דקני\u0004 \u0005[האם לא\u0006 מדובר שם ב\u0005סבך של קנים]\u0006","ודוחים: \u0003לא,\u0004 מדובר ב\u0003קנה קנה פחות משלשה\u0004 שאז הוא כשר לכתחילה. ומקשים: \u0003אי הכי, היינו\u0004 \u0005[אם כך, הרי זה]\u0006 בדיוק \u0003גדר!\u0004","ודוחים קושיה זו: \u0003אלא מאי\u0004 \u0005[מה]\u0006 היא חיצת הקנים, הלא לדעתך היא \u0003גודריתא דקני\u0004 \u0005[סבך של קנים] —\u0006 \u0003היינו\u0004 \u0005[הרי זה]\u0006 \u0003אילן! אלא מאי אית לך למימר\u0004 \u0005[מה יש לך לומר]\u0006"],["\u0003תרי גווני\u0004 \u0005[שיני מיני]\u0006 \u0003אילן. הכא נמי, תרי גווני\u0004 \u0005[כאן גם כן, שני מיני]\u0006 \u0003גדר\u0004.","ועוד \u0003בעא מיניה\u0004 \u0005[שאל ממנו]\u0006 \u0003אביי מרבה: חצר שראשה נכנס לבין הפסין\u0004 המקיפים את הבאר \u0003מהו לטלטל מתוכה לבין הפסין, ומבין הפסין לתוכה? אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מותר.\u0004","ואם היו החצירות \u0003שתים, מאי\u0004 \u0005[מה\u0006 \u0003הדין\u0004\u0005]\u0006? האם מותר לטלטל מתוכן לבין הפסים ולהיפך \u0003אמר ליה\u0004 \u0005[לו]\u0006 רבה בתשובה: \u0003אסור.\u0004 שכן אסרו חכמים לטלטל מרשות יחיד אחת לחברתה.","\u0003אמר רב הונא:\u0004 אם היו \u0003שתים אסורין, ואפילו עירבו\u0004 אותן חצירות בפתח שביניהן ואינן אוסרות האחת את חברתה. וטעם הדבר, משום \u0003גזירה שמא יאמרו\u0004 אלו שאינם יודעים שיש פתח ושיתוף בין החצרות \u0003\"עירוב מועיל לבין הפסין\".\u0004 ואילו \u0003רבא אמר:\u0004 אם \u0003עירבו — מותר,\u0004 כיון שעל ידי העירוב נדונות הן כחצר אחת.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי לרבא: תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]\u0006 ש\u0003מסייע לך,\u0004 שכן שנינו: \u0003חצר שראשה אחד נכנס לבין הפסין — מותר לטלטל מתוכה לבין הפסין ומבין הפסין לתוכה, אבל שתים — אסור. במה דברים אמורים — שלא עירבו, אבל עירבו — מותרין\u0004.","ומעירים: \u0003לימא תיהוי תיובתא\u0004 \u0005[האם נאמר\u0006 ש\u0005תהא זו קושיה חמורה]\u0006 על \u0003רב הונא,\u0004 שהרי הברייתא סותרת דבריו?! ודוחים: \u0003אמר לך\u0004 \u0005[\u0006יכול היה \u0005לומר לך]\u0006 \u0003רב הונא: התם דהדרן וערבן\u0004 \u0005[שם\u0006 בברייתא מדובר כ\u0005שחזרו ונתערבו]\u0006 אותן שתי החצרות על ידי פירצה, והדבר גלוי לכל שחצר אחת היא ואין חשש שמא יאמרו שהעירוב מועיל לבין הפסים.","ועוד \u0003בעא מיניה\u0004 \u0005[שאל ממנו]\u0006 \u0003אביי מרבה: יבשו מים\u0004 מן הבאר \u0003בשבת מהו? אמר ליה\u0004 \u0005[לו]:\u0006 \u0003כלום נעשית מחיצה\u0004 זו \u0003אלא בשביל מים,\u0004 וכיון ש\u0003מים אין כאן —\u0004 אף \u0003מחיצה אין כאן,\u0004 ואין לה עוד חשיבות.","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רבין: יבשו מים בשבת\u0004 וחזרו \u0003ובאו\u0004 גשמים \u0003בשבת\u0004 זו \u0003מהו\u0004 האם חזרו הפסים להיתרם הראשון? \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: יבשו בשבת לא תיבעי [תישאל,\u0004 אינה צריכה להישאל] \u0003לך, דבעי מיניה דמר ופשיט לי דאסיר\u0004 \u0005[ששאלתי ממנו מאדוני,\u0006 רבה, \u0005ופתר לי שאסור].\u0006","כש\u0003באו\u0004 המים שוב, \u0003נמי\u0004 \u0005[גם כן]\u0006 \u0003לא תיבעי\u0004 \u0005[\u0006צריכה \u0005להישאל]\u0006 \u0003לך\u0004 — \u0003דהוה ליה\u0004 \u0005[שהרי היא]\u0006 \u0003מחיצה העשויה בשבת. ותניא\u0004 \u0005[ו\u0006כבר \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003כל מחיצה העשויה בשבת, בין בשוגג בין במזיד בין באונס בין ברצון — שמה מחיצה.\u0004 ואין אומרים שכיון שהיה איסור בעשייתה לא תועיל.","והקשה רבין: \u0003ולאו איתמר עלה\u0004 \u0005[וכי לא נאמר עליה,\u0006 על הלכה זו\u0005]\u0006 \u0003אמר רב נחמן: לא שנו\u0004 שמחיצה כזו שמה מחיצה \u0003אלא\u0004 לחומרה שיש איסור מן התורה \u0003לזרוק\u0004 ממנה לרשות הרבים ולהיפך\u0003, אבל לטלטל\u0004 בתוכה — \u0003לא\u0004 התירו חכמים.","ודוחים: \u0003כי איתמר\u0004 \u0005[כאשר נאמרו]\u0006 דבריו של \u0003רב נחמן\u0004 בעושה מחיצה — \u0003אמזיד איתמר\u0004 \u0005[על מזיד נאמרו],\u0006 שקנסו חכמים ואסרוה. אבל מחיצה שנעשתה מעצמה או בשוגג, לא קנסו בה ומותרת לכל דבר.","\u0003אמר ר' אלעזר: הזורק\u0004 חפץ מרשות הרבים \u0003לבין פסי הביראות — חייב.\u0004 ותוהים, \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]\u0006 \u0003אי לאו\u0004 \u0005[אם לא]\u0006 \u0003מחיצה היא — היכי משתרי ליה\u0004 \u0005[איך מותר לו]\u0006 \u0003למלאות?!\u0004 משמע שרשות היחיד היא לכל דבר.","ומשיבים: \u0003לא צריכא, דעבד\u0004 \u0005[לא נצרכה\u0006 אלא במקרה \u0005שעשה]\u0006 מבנה \u0003כעין פסי ביראות ברשות הרבים\u0004 במקום שאין באר, \u0003וזרק לתוכה — חייב.\u0004","ומקשים: \u0003הא נמי פשיטא\u0004 \u0005[זו גם כן פשוטה]!\u0006 \u0003אי לאו דבעלמא\u0004 \u0005[אם לא שבכלל]\u0006 \u0003מחיצה היא — גבי\u0004 \u0005[אצל]\u0006 \u0003בור היכי משתרי ליה לטלטלי\u0004 \u0005[היאך מותר לו לטלטל]?\u0006 ומסבירים: \u0003לא צריכא, אף על גב דקא בקעי\u0004 \u0005[לא נצרכה\u0006 אלא \u0005אף על פי שעוברים]\u0006 \u0003בה רבים,\u0004 שאף שאין מחיצה זו חוסמת בפניהם, בכל זאת נדונה היא כמחיצה לענין שבת.","ושואלים: \u0003ומאי קא משמע לן\u0004 \u0005[ומה השמיע לנו]\u0006 בכך — \u0003דלא אתו\u0004 \u0005[שלא באים]\u0006 \u0003רבים\u0004 העוברים במקום \u0003ומבטלי מחיצתא\u0004 \u0005[ומבטלים\u0006 דין \u0005המחיצה],\u0006 \u0003הא\u0004 \u0005[הרי]\u0006 \u0003אמר ר' אלעזר חדא זימנא\u0004 \u0005[פעם אחת]\u0006 סברה זאת!","\u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005],\u0006 \u0003ר' יהודה אומר\u0004 בדין פסי ביראות: \u0003אם היתה דרך רשות הרבים מפסקתן\u0004 את הפסים \u0003— יסלקנה לצדדין\u0004 ואינם מועילים כמחיצה\u0003, וחכמים אומרים: אינו צריך,\u0004 שאף אם עוברים שם הרבים עדיין יפה כוח המחיצות. \u0003ר' יוחנן ור' אלעזר דאמרי תרווייהו\u0004 \u0005[שאמרו שניהם]\u0006 \u0003כאן הודיעך כחן של מחיצות.\u0004 הרי שכבר גילו חכמים דעתם שמחיצה אינה מתבטלת בבקיעת הרבים!","ומתרצים: \u0003אי מהתם, הוה אמינא\u0004 \u0005[אם משם\u0006 בלבד, \u0005הייתי אומר]\u0006 שכוונתו \u0003'כאן'\u0004 הודיעך התנא הלכה זו \u0003ו\u0004ר' אלעזר עצמו \u0003לא סבירא ליה\u0004 \u0005[אינו סבור כן]\u0006. \u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 ש\u0003'כאן'\u0004 שאמר משמעו: \u0003וסבירא ליה\u0004 \u0005[והוא\u0006 אף \u0005סבור\u0006 כן\u0005]\u0006","ושואלים:\u0003ולימא הא ולא בעי הך\u0004 \u0005[ושיאמר זו,\u0006 בפסי ביראות ברשות הרבים, \u0005ולא יצטרך לההיא]!\u0006 ומשיבים, שאכן לא אמר ר' אלעזר שתי פעמים אלא \u0003חדא\u0004 \u0005[אחת]\u0006 \u0003מכלל חבירתה איתמר\u0004 \u0005[נאמרה].\u0006 ואמר רק הלכה אחת, ואת האחרת מסרו תלמידיו בשמו כמסקנה מדבריו.","אמרו חכמים במשנה ש\u0003מותר להקריב\u0004 את פסי הביראות \u0003לבאר.\u0004 ובלבד שיהא מקום לפרה שתעמוד ראשה ורובה ברשות היחיד כשהיא שותה מהבאר. וכעין זה \u0003תנן התם\u0004 \u0005[שנינו שם\u0006 במשנה\u0005]:\u0006 \u0003לא יעמוד אדם ברשות הרבים וישתה ברשות היחיד,\u0004 וכן לא יעמוד \u0003ברשות היחיד וישתה ברשות הרבים, אלא אם כן מכניס ראשו ורובו למקום שהוא שותה.\u0004"],["\u0003וכן בגת\u0004 לענין מעשר. כל עוד נמצא אדם ראשו ורובו בגת יכול הוא לשתות ממנה בלא לעשר, כיון ששתייה שם — שתייה ארעית היא, הפטורה ממעשר.","ומעתה באים לברר כמה הלכות בנושא זה; \u0003גבי\u0004 \u0005[אצל]\u0006 \u0003אדם — הא\u0004 \u0005[הרי]\u0006 \u0003אמר\u0004 בהלכות אלה \u0003דבעי\u0004 \u0005[שצריך]\u0006 שיהא \u0003ראשו ורובו\u0004 בתוך התחום. \u0003גבי\u0004 \u0005[אצל]\u0006 \u0003פרה\u0004 העומדת ברשות הרבים ושותה מתוך רשות היחיד \u0003מי בעינן לה\u0004 \u0005[האם צריכים אנו אותה]\u0006 שיהא \u0003ראשה ורובה\u0004 בתחום רשות היחיד \u0003או לא?\u0004","ומבררים: \u0003כל היכא דקא נקיט מנא ולא נקיט לה\u0004 \u0005[בכל מקום שהוא מחזיק את הכלי ואינו מחזיק אותה] —\u0006 \u0003לא תיבעי\u0004 \u0005[תסתפק]\u0006 \u0003לך דבעי\u0004 \u0005[שצריך]\u0006 שיהא \u0003ראשה ורובה מלגיו\u0004 \u0005[בפנים]\u0006 שמא תזוז הפרה לאחוריה ותמשוך עימה את הכלי, ויבוא הוא לטלטלו. \u0003כי תבעי\u0004 \u0005[כאשר תישאל]\u0006 \u0003לך\u0004 השאלה — \u0003היכא דנקיט מנא ונקיט לה, מאי\u0004 \u0005[כאשר מחזיק את הכלי ומחזיק אותה, מה\u0006 דינו\u0005]?\u0006","\u0003אמר ליה\u0004 \u0005[אמר לו]:\u0006 \u0003תניתוה\u0004 \u0005[\u0006כבר \u0005שניתם אותה]\u0006 את התשובה לשאלה זו: \u0003ובלבד שתהא הפרה ראשה ורובה מבפנים ושותה. מאי לאו דנקיט לה ונקיט מנא\u0004 \u0005[האם לא\u0006 מדובר גם \u0005כשמחזיק אותה ומחזיק את הכלי]?\u0006 ודוחים: \u0003לא,\u0004 מדובר כאן במקרה \u0003דנקיט מנא ולא נקיט לה\u0004 \u0005[שמחזיק את הכלי ואינו מחזיק אותה]\u0006","ומקשים: \u0003וכי נקיט מנא ולא נקיט לה, מי שרי\u0004 \u0005[וכאשר מחזיק\u0006 הוא \u0005את הכלי ולא מחזיק אותה, האם מותר\u0006 בכלל\u0005]\u0006 להשקות את בהמתו בצורה זו? \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003לא ימלא אדם מים\u0004 מן הבור שברשות הרבים לתוך כלי ויאחוז את הכלי \u0003ויתן בשבת לפני בהמתו. אבל ממלא הוא ושופך, והיא שותה מאיליה\u0004 משמע שאסור לאדם לתת את המים בכלי לפני הבהמה בדרך זו!","ודוחים: \u0003הא איתמר עלה\u0004 \u0005[הרי\u0006 כבר \u0005נאמר עליה]\u0006 על בעיה זו ש\u0003אמר אביי: הכא\u0004 \u0005[כאן]\u0006 מדובר כשהפרה עומדת בתוך בית שחלונותיו פתוחים לרשות הרבים ואוכלת מתוך \u0003אבוס\u0004 (או שוקת) \u0003העומד ברשות הרבים\u0004 והוא עצמו \u0003גבוה עשרה טפחים ורוחב ארבעה\u0004 טפחים. ואם כן איבוס זה רשות היחיד הוא, \u0003וראשו אחד\u0004 של איבוס זה \u0003נכנס לבין הפסין.\u0004","ואסרו לדלות מים מן הבור שבין הפסים ולהניח את הכלי לפני הבהמה, \u0003גזירה דילמא חזי ליה לאבוס דמקלקל ואתי לתקוניה, ודרא ליה לדוולא בהדיה\u0004 \u0005[שמא יראה אותו, את האיבוס, שהוא מקולקל\u0006 בצידו הפונה לרשות הרבים \u0005ויבוא לתקנו, וימשוך את הדלי עמו],\u0006 \u0003וקא מפיק\u0004 \u0005[והרי הוא מוציא]\u0006 \u0003מרשות היחיד לרשות הרבים\u0004 אלא שופך את המים על האיבוס ומגיעים לבהמה מאיליהן.","ומקשים: ואף אם אמנם יניח את הדלי עצמו על גבי האבוס, \u0003וכי האי גוונא מי מיחייב\u0004 \u0005[ובכגון זה האם מתחייב]?\u0006 \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רב ספרא אמר ר' אמי אמר ר' יוחנן: המפנה חפציו מזוית לזוית\u0004 בתוך הבית, \u0003ונמלך עליהן\u0004 בשעת פינוי \u0003והוציאן\u0004 לרשות הרבים — \u0003פטור\u0004 משום מוציא, כיון \u0003שלא היתה עקירה משעה ראשונה לכך\u0004 לצורך הוצאה לרשות אחרת, שהרי כשעקר את החפץ ממקומו נתכוון רק להזיזו ברשות המותרת. אף כאן כיון שלא עקר את הדלי מתחילה על מנת להוציאו לרשות הרבים — אינו מתחייב ואין מקום לגזור גזירה בשל כך.","\u0003אלא\u0004 יש לומר שהגזירה היא משום חשש אחר: \u0003זמנין דמתקן ליה והדר מעייל ליה, וקא מעייל\u0004 \u0005[פעמים שמתקן לו\u0006 לאיבוס, \u0005וחוזר ומכניסו\u0006 את הדלי אל האיבוס, \u0005והריהו מכניס]\u0006 \u0003מרשות הרבים לרשות היחיד,\u0004 ועקירתו זו הרי נעשתה כבר מתוך כוונה להכניס את הדלי מרשות הרבים לרשות היחיד.","אותה סוגיה עצמה נאמרה גם בלשון אחרת: \u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 \u0003גבי\u0004 \u0005[אצל]\u0006 \u0003אדם — הא קאמרינן דסגי ליה\u0004 \u0005[הרי אמרנו שדי לו]\u0006 \u0003בראשו ורובו\u0004 ברשות שהוא שותה בה. \u0003גבי\u0004 \u0005[אצל]\u0006 \u0003פרה מי סגי\u0004 \u0005[האם די]\u0006 \u0003לה בראשה ורובה, או לא?\u0004 ושמא צריך להכניסה כולה לאותה רשות?","ומפרטים: \u0003היכא דנקיט מנא ונקיט לה\u0004 \u0005[במקום שמחזיק את הכלי ומחזיק אותה] —\u0006 \u0003לא תיבעי\u0004 \u0005[תיסתפק]\u0006 \u0003לך דסגי\u0004 \u0005[ש\u0006ודאי \u0005די]\u0006 \u0003לה בראשה ורובה, אלא כי תיבעי\u0004 \u0005[כאשר תיסתפק]\u0006 \u0003לך\u0004 הרי זה \u0003דנקיט מנא ולא נקיט לה, מאי?\u0004 \u0005[כשמחזיק את הכלי ואינו מחזיק אותה, מה\u0006 דינו\u0005]\u0006?","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003תניתוה\u0004 \u0005[שניתם אותה]\u0006 \u0003ובלבד שתהא פרה ראשה ורובה מבפנים ושותה. מאי לאו דנקיט מנא ולא נקיט לה\u0004 \u0005[האם לא\u0006 מדובר כאן אף במקרה \u0005שמחזיק את הכלי ולא מחזיק אותה]\u0006 ודוחים: \u0003לא,\u0004 אפשר לומר \u0003דנקיט מנא ונקיט לה\u0004 \u0005[שמחזיק את הכלי ומחזיק אותה]\u0006","ומעירים: \u0003והכי נמי מסתברא\u0004 \u0005[וכך גם כן מסתבר]\u0006 \u0003דאי נקיט מנא ולא נקיט לה, מי שרי\u0004 \u0005[שאם מחזיק את הכלי ואינו מחזיק אותה, האם מותר]?\u0006 \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003לא ימלא אדם מים ויתן לפני בהמתו, אבל ממלא ושופך והיא שותה מאיליה!\u0004","ודוחים מיד את הראיה הזו: \u0003הא איתמר עלה\u0004 \u0005[הרי כבר נאמר עליה]\u0006 ש\u0003אמר אביי: הכא\u0004 \u0005[כאן]\u0006 מדובר \u0003באבוס העומד ברשות הרבים גבוה עשרה טפחים ורוחב ארבעה, וראשו נכנס לבין הפסין, דזמנין דחזי ליה לאבוס דמקלקל ואתי לתקוניה, ודרי ליה לדוולא בהדיה, וקא מפיק\u0004 \u0005[שפעמים רואה את האבוס שהוא מקולקל ובא לתקנו, ומושך את הדלי עמו, והרי הוא מוציא]\u0006 \u0003מרשות היחיד לרשות הרבים.\u0004","ומקשים: \u0003וכי האי גוונא מי מיחייב\u0004 \u0005[וכלום בכגון זה האם מתחייב]?\u0006 \u0003והאמר\u0004 \u0005[והרי\u0006 כבר \u0005אמר]\u0006 \u0003רב ספרא אמר ר' אמי אמר ר' יוחנן: המפנה חפציו מזוית לזוית ונמלך עליהן והוציאן — פטור, שלא היתה עקירה משעה ראשונה לכך!\u0004","\u0003אלא,\u0004 כך יש לומר: \u0003זימנין דמתקן ליה והדר מעייל ליה, וקא מעייל ליה\u0004 \u0005[פעמים שמתקן אותו וחוזר ומכניס אותו, והרי הוא מכניס אותו]\u0006 \u0003מרשות הרבים לרשות היחיד.\u0004 ומכל מקום אין להביא ראיה ממקור זה. על כן מנסים להביא ראיה אחרת.","\u0003תא שמע\u0004 \u0005[בוא ושמע]\u0006 מה ששנינו: \u0003גמל שראשו ורובו מבפנים — אובסין אותו\u0004 (מאכילים אותו בעל כורחו כמות גדולה) \u0003מבפנים, והא איבוס כמאן דנקיט מנא ונקיט לה דמיא\u0004 \u0005[והרי האבסה שכמי שמחזיק כלי ומחזיק אותו נחשב],\u0006 שהרי אינו יכול להאביס את הבהמה בעל כורחה בלא להחזיק בצוארה, \u0003ו\u0004בכל זאת \u0003קא בעינן\u0004 \u0005[\u0006ובכל זאת \u0005אנו צריכים,\u0006 די לנו\u0005]\u0006 שיהא \u0003ראשה ורובה\u0004 בפנים!","\u0003אמר רב אחא בר רב הונא אמר רב ששת: שאני\u0004 \u0005[שונה]\u0006 \u0003גמל, הואיל וצוארו ארוך\u0004 חייבים שיהא ראשו ורובו בפנים, שאם לא כן יוכל להוציא ראשו מעבר לתחום הפסים עד רשות הרבים, אבל אין צורך להקפיד על כך בשאר בהמות, על כן רוצים להביא ראיה.","\u0003תא שמע\u0004 \u0005[בוא ושמע]\u0006 ממה ששנינו בברייתא אחרת: \u0003בהמה שראשה ורובה בפנים — אובסין אותה מבפנים. והא אבוס כמאן דנקיט מנא ונקיט לה\u0004 \u0005[והרי איבוס שכמי שמחזיק כלי ומחזיק אותה]\u0006 נחשב, \u0003וקא בעינן\u0004 \u0005[\u0006ובכל זאת \u0005אנו צריכים,\u0006 די לנו\u0005]\u0006 \u0003ראשו ורובו!\u0004 ודוחים: \u0003מאי\u0004 \u0005[מהי]\u0006 \u0003\"בהמה\" נמי דקתני\u0004 \u0005[גם כן\u0006 זו \u0005ששנינו] —\u0006 \u0003גמל.\u0004","ותוהים: \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא אחת\u0005]\u0006 \u0003'בהמה' והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא אחרת\u0005]\u0006 \u0003'גמל'!\u0004 ומשמע שהלכה זו היא לא רק בגמל אלא גם בשאר בהמות!","ומשיבים: \u0003מידי גבי הדדי תניא\u0004 \u0005[וכי זו אצל זו שנויות\u0006 אלו שתי הברייתות\u0005]?!\u0006 שאילו הברייתות היו שנויות כאחת, ראוי היה לומר שאינו חוזר על אותו נושא במלים שונות, ואולם הרי שתי ברייתות אלה ממקורות שונים באו, ושמא קרא אחד התנאים לגמל בהמה סתם ואין להוכיח מכאן. וכעין זה \u0003תניא נמי הכי\u0004 \u0005[שנינו גם כן\u0006 בברייתא\u0005]:\u0006 \u0003ר' אליעזר אוסר בגמל, הואיל וצוארו ארוך.\u0004","\u0003אמר ר' יצחק בר אדא: לא הותרו פסי ביראות אלא לעולי רגלים בלבד.\u0004 ומקשים: \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003לא הותרו פסי ביראות אלא לגבי בהמה בלבד,\u0004 ולכאורה משמע — כל בהמה! ומשיבים: \u0003מאי\u0004 \u0005[מהי]\u0006 \u0003בהמה\u0004 זו שנזכרה — הכוונה \u0003בהמת עולי רגלים. אבל אדם\u0004"],["\u0003מטפס ועולה מטפס ויורד\u0004 לתוך הבור, ושותה שם,","ומקשים: \u0003איני\u0004 \u0005[וכי כן הוא]\u0006 שהיתר הפסים הוא לצורך בהמה בלבד? \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רב יצחק אמר ר' יהודה אמר שמואל: לא הותרו פסי ביראות אלא\u0004 כאשר יש בביראות \u0003מים חיים בלבד. ואי\u0004 \u0005[ואם]\u0006 \u0003ל\u0004צורך \u0003בהמה\u0004 המים, \u0003מה לי חיים מה לי מכונסין?\u0004 הלא גם מים מכונסים, אף שאינם טובים כל כך ראויים עדיין לשתיית בהמה! ומשיבים: \u0003בעינן מידי דחזי\u0004 \u0005[צריכים אנו דבר שראוי]\u0006 \u0003לאדם נמי\u0004 \u0005[גם כן].\u0006","\u0003גופא\u0004 \u0005[ולגוף\u0006 הדבר\u0005]\u0006 דנים: \u0003לא הותרו פסי ביראות אלא לבהמה בלבד אבל אדם מטפס ועולה מטפס ויורד\u0004 לתוך הבור ושותה, \u0003ואם היו\u0004 הבורות \u0003רחבין\u0004 שאינו יכול לטפס, \u0003אפילו לאדם נמי\u0004 \u0005[גם כן]\u0006 התירו לשאוב ממנו כדי לשתות. \u0003ולא ימלא אדם מים ויתן לפני בהמתו, אבל ממלא הוא ושופך לפני בהמה ושותה\u0004 מהן \u0003מאיליה,\u0004 אבל אסור לו להחזיקה.","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב ענן: אם כן, מה הועילו פסי ביראות?\u0004 ומייד תמהים על דבריו כיצד אפשר לשאול \u0003מה הועילו?!\u0004 הרי הועילו \u0003למלאות מהן,\u0004 שלולא זה אסור היה לשאוב מן הבאר שבתוכן!","\u0003אלא\u0004 כך יש לפרש את שאלתו: \u0003מה הועיל\u0004 שעושים מחיצה כדי \u0003ראשה ורובה של פרה\u0004 — אם בין כה וכה אין לתת את הדלי בו הוא שאב לפני הפרה?","\u0003אמר אביי:\u0004 אין הדבר כן, ובין הפסים מותר להשקות את הבהמה בכל דרך. \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה עוסקים אנו]\u0006 — במקרה מיוחד, \u0003באיבוס\u0004 (או שוקת) \u0003העומד ברשות הרבים, גבוה עשרה\u0004 טפחים \u0003ורוחב\u0004 טפחים \u0003ארבעה וראשו נכנס לבין הפסין וכו'.\u0004 וחששו שמא יתקלקל האיבוס והוא עלול לטלטל את הדלי שבידו בתחום רשות הרבים, ומשום כך גזרו גזירה זו.","\u0003אמר רב ירמיה בר אבא אמר רב: אין\u0004 דין \u0003בורגנין\u0004 (סוכות שומרים קטנות הסמוכות לעיר) \u0003בבבל,\u0004 ואין הם נחשבים כחלק מתחום העיר, \u0003ולא פסי ביראות\u0004 מתירים \u0003בחוץ לארץ.\u0004","ומסביר: \u0003בורגנין בבבל לא — דשכיחי בידקי\u0004 \u0005[שמצויים שטפונות]\u0006 הגורפים את הבורגנים, ולכן אין הם חשובים כמקום ישוב, אף \u0003פסי ביראות בחוץ לארץ לא — דלא שכיחי מתיבתא\u0004 \u0005[שאין מצויות\u0006 שם \u0005ישיבות]\u0006 שדרך האנשים ללכת אליהן, והיתר זה של פסי ביראות נעשה רק להולכים לדבר מצוה. \u0003אבל איפכא עבדינן\u0004 \u0005[אבל להיפך אנו עושים]\u0006 — סומכין על בורגנין בחוץ לארץ, ועל פסי ביראות בבבל.","\u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 גירסה שונה: \u0003אמר רב ירמיה בר אבא אמר\u0004 בשם \u0003רב: אין בורגנין ופסי ביראות, לא בבבל ולא בחוץ לארץ.\u0004 ומסביר: \u0003בורגנין בבבל לא — דשכיחי בידקי\u0004 \u0005[שמצויים שטפונות],\u0006 \u0003בחוץ לארץ נמי לא — דשכיחי גנבי\u0004 \u0005[שמצויים גנבים]\u0006 הגונבים מתוך הבורגן ואין הבריות מחשיבים אותם כמקום ישוב.","\u0003פסי ביראות בבבל לא — דשכיחי מיא\u0004 \u0005[שמצויים מים]\u0006 בבבל בנהרות ובתעלות הרבות, ואין צורך חיוני בבארות. \u0003בחוץ לארץ נמי\u0004 \u0005[גם כן]\u0006 \u0003לא — דלא שכיחי מתיבתא\u0004 \u0005[שאין מצויות ישיבות].\u0006","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב חסדא למרי בריה\u0004 \u0005[בנו]\u0006 של \u0003רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב ירמיה בר אבא: אמרי אתיתו מברנש לבי כנישתא דדניאל דהוה תלתא פרסי בשבתא\u0004 \u0005[אומרים\u0006 ש\u0005באתם מ\u0006העיר \u0005ברניש לבית הכנסת של דניאל שהוא\u0006 במרחק של \u0005שלוש פרסות בשבת]\u0006 \u0003אמאי סמכיתו, אבורגנין\u0004 \u0005[על מה סומכים אתם, על הבורגנין]\u0006 שבין שני המקומות, הממשיכים את תחום \u0003העיר לעבר בית הכנסת? הא אמר אבוה דאבוה משמיה דרב\u0004 \u0005[הרי אמר אבי אביך משם רב]:\u0006 \u0003אין בורגנין בבבל!\u0004","\u0003נפק ואחוי ליה הנהו מתוותא, דמבלען\u0004 \u0005[יצא והראה לו אותן עיירות\u0006 חרבות, \u0005שהיו מובלעות]\u0006 \u0003ב\u0004מרחק של \u0003שבעים אמה ושיריים\u0004 זו מזו, ועל ידן מותר ללכת כל אותו מרחק, ולא על ידי הבורגנים.","\u0003אמר רב חסדא, דריש\u0004 \u0005[דרש]\u0006 \u0003מרי בר מר: מאי דכתיב\u0004 \u0005[מהו שנאמר]\u0006 \u0003\"לכל תכלה ראיתי קץ רחבה מצותך מאד\"\u0004 (תהילים קיט, צו) \u0003דבר זה אמרו דוד ולא פירשו\u0004 כדיוקו, \u0003אמרו איוב ולא פירשו, אמרו יחזקאל ולא פירשו, עד שבא זכריה בן עדו ופירשו.\u0004","\u0003אמרו דוד ולא פירשו — דכתיב\u0004 \u0005[שנאמר]\u0006 ככתוב כאן \u0003\"לכל תכלה ראיתי קץ רחבה מצותך מאד\"\u0004, שלא פירש עד כמה גדולות ומרובות הן מצוות התורה, וכן \u0003אמרו איוב ולא פירשו, דכתיב\u0004 \u0005[שנאמר]\u0006 \u0003\"ארכה מארץ מדה, ורחבה מני ים\"\u0004 (איוב יא, ט).","וכן \u0003אמרו יחזקאל ולא פירשו — דכתיב\u0004 \u0005[שנאמר]\u0006 \u0003\"ויפרש אותה\u0004 (את מגילת הספר) \u0003לפני והיא כתובה פנים ואחור וכתוב אליה קינים והגה והי\"\u0004 (יחזקאל ב, י).","ומסבירים: \u0003\"קינים\" — זו פורענותן של צדיקים בעולם הזה, ו\u0004זו ראיה לכך שהיא לשון פורענות, ש\u0003כן הוא אומר \"קינה היא וקוננוה\"\u0004 (יחזקאל לב, טז). \u0003\"והגה\" — זו מתן שכרן של צדיקים לעתיד לבא, ו\u0004זו ראיה לכך שהיא לשון שמחה, ש\u0003כן הוא אומר \"\u0004עלי עשור ועלי נבל \u0003עלי הגיון בכנור\"\u0004 (תהילים צב, ד). \u0003\"והי\" — זו היא פורענותן של רשעים לעתיד לבא, וכן הוא אומר \"הוה על הוה תבוא\"\u0004 (יחזקאל ז, כו).","ואף על פי כן לא פירש גודל היקפה \u0003עד שבא זכריה בן עדו ופירשו, דכתיב\u0004 \u0005[שנאמר]\u0006 \u0003\"ויאמר אלי מה אתה ראה ואמר אני ראה מגלה עפה ארכה עשרים באמה ורחבה עשר באמה\"\u0004 (זכריה ה, ב). כיון שהיתה עפה משמע שיש לה שני אגפים שווים בגודלם, \u0003וכי פשטת לה, הויא לה עשרין בעשרין\u0004 \u0005[וכאשר פותח אתה אותה, הרי היא עשרים בעשרים\u0006 אמה\u0005].\u0006 \u0003וכתיב\u0004 \u0005[ונאמר]\u0006 \u0003\"היא כתובה פנים ואחור\", וכי קלפת לה\u0004 \u0005[וכאשר אתה קולף אותה]\u0006 ומשאיר כל צד לעצמו, \u0003כמה הויא לה\u0004 \u0005[הריהו]\u0006 כל שטחה — \u0003ארבעין בעשרין\u0004 \u0005[ארבעים על עשרים]\u0006 אמה.","\u0003וכתיב\u0004 \u0005[ונאמר]\u0006 \u0003\"מי מדד בשעלו מים, ושמים בזרת תכן\u0004 וכל בשליש עפר הארץ\u0003\"\u0004 (ישעיה מ, יב). ואם העולם כולו שיעורו זרת מרובעת אחת, שהיא רבע האמה המרובעת, \u0003נמצא\u0004 לפי חשבון זה \u0003כל העולם כולו, אחד משלשת אלפים ומאתים בתורה.\u0004","\u0003ו\u0004עוד \u0003אמר רב חסדא, דריש\u0004 \u0005[דרש]\u0006 \u0003מרי בר מר: מאי דכתיב\u0004 \u0005[מהו שנאמר]\u0006 \u0003\"והנה שני דודאי תאנים מועדים לפני היכל ה'\u0004 אחרי הגלות נבוכדראצר מלך בבל את יכניהו בן יהויקים מלך יהודה ואת שרי יהודה ואת החרש ואת המסגר מירושלם ויבאם בבל. \u0003הדוד אחד תאנים טבות מאד כתאני\u0004"],["\u0003הבכרות והדוד אחד תאנים רעות מאד אשר לא תאכלנה מרע\"\u0004 (ירמיה כד, א— ג)","ודורשים: \u0003תאנים הטובות — אלו צדיקים גמורים, תאנים הרעות — אלו רשעים גמורים. ושמא תאמר אבד סברם\u0004 (תקוותם) \u0003ובטל סיכוים\u0004 של הרשעים? \u0003תלמוד לומר: \"הדודאים נתנו ריח\"\u0004 (שיר השירים ז, יד) כלומר: \u0003אלו ואלו עתידין שיתנו ריח.\u0004","כיון שהובא פסוק זה מביאים מה ש\u0003דרש רבא\u0004 על הכתוב \"הדודאים נתנו ריח ועל פתחינו כל מגדים חדשים גם ישנים דודי צפנתי לך\": \u0003מאי דכתיב \"הדודאים נתנו ריח\" — אלו בחורי ישראל שלא טעמו טעם חטא.\u0004","\u0003\"ועל פתחינו כל מגדים\" — אלו בנות ישראל שמגידות פתחיהן לבעליהן.\u0004 כלומר, אומרות להם מתי הן נדות. \u0003לישנא אחרינא\u0004 \u0005[לשון אחר]:\u0006 \u0003שאוגדות\u0004 (קושרות, שומרות) \u0003פתחיהן לבעליהן\u0004 ואינן נבעלות לאחרים.","\u0003\"חדשים גם ישנים דודי צפנתי לך\" — אמרה כנסת ישראל לפני הקדוש ברוך הוא: רבונו של עולם, הרבה גזירות גזרתי על עצמי\u0004 בתקנות חכמים וסייגיהם \u0003יותר ממה שגזרת עלי\u0004 בתורה, \u0003וקיימתים,\u0004 ואלה הם החדשים הנוספים על הישנים האמורים בתורה.","מסופר: \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב חסדא לההוא מדרבנן דהוה קא מסדר אגדתא קמיה\u0004 \u0005[לאחד החכמים שהיה מסדר\u0006 מסורות \u0005אגדה לפניו]\u0006 \u0003מי שמיע לך\u0004 \u0005[האם שמעת]\u0006 \u0003\"חדשים גם ישנים\" מהו? אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אלו מצו‍ת קלות ואלו מצו‍ת חמורות.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב חסדא: אינו כן, \u0003וכי תורה פעמים פעמים ניתנה —\u0004 ומצוות קלות שבה ניתנו בנפרד ממצוות חמורות? \u0003אלא\u0004 ישנים — \u0003הללו\u0004 ציוויים \u0003מדברי תורה, ו\u0004חדשים \u0003הללו — מדברי סופרים.\u0004","ועוד \u0003דרש רבא\u0004 בדומה לכך: \u0003מאי דכתיב\u0004 \u0005[מהו שנאמר]\u0006 \u0003\"ויתר מהמה בני הזהר עשות ספרים הרבה\u0004 אין קץ ולהג הרבה יגיעת בשר\u0003\"\u0004 (קהלת יב, יב) — \u0003בני הזהר\u0004 לקיים \u0003דברי סופרים יותר מדברי תורה. שדברי תורה יש בהן\u0004 מצוות \u0003עשה ולא תעשה,\u0004 ואף באלה יש מהן שעונש העובר עליהם הוא מלקות בלבד. \u0003ו\u0004אילו \u0003דברי סופרים — כל העובר על דברי סופרים חייב מיתה שנאמר \"ופורץ גדר ישכנו נחש\" (קהלת י, ח).\u0004","\u0003שמא תאמר: אם יש בהן ממש\u0004 וחשיבות כה רבה בדברי סופרים \u0003מפני מה לא נכתבו?!\u0004 על כן \u0003אמר קרא\u0004 \u0005[המקרא]:\u0006 \u0003\"עשות ספרים הרבה אין קץ\"\u0004 שאי אפשר לתורה שבעל פה שתיכתב, שאין קץ להקיפה.","מהו \u0003\"ולהג הרבה יגיעת בשר\"? אמר רב פפא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב אחא בר אדא משמיה\u0004 \u0005[משמו]\u0006 של \u0003רב אחא בר עולא: מלמד שכל המלעיג על דברי חכמים, נידון בצואה רותחת\u0004 שהיא התוצאה של יגיעת בשר האדם.","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רבא: מי כתיב\u0004 \u0005[האם כתוב]\u0006 \u0003לעג? \"להג\" כתיב\u0004 \u0005[כתוב]!\u0006 \u0003אלא\u0004 להיפך: \u0003כל ההוגה בה טועם\u0004 ונהנה כ\u0003טעם בשר.\u0004","ובענין חומרת דברי חכמים מסופר. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003מעשה בר' עקיבא שהיה חבוש בבית האסורין, והיה ר' יהושע הגרסי משרתו. בכל יום ויום היו מכניסין לו\u0004 תלמידיו \u0003מים במדה\u0004 הראויה לשתות. \u0003יום אחד מצאו שומר בית האסורין\u0004 לר' יהושע הגרסי\u0003, אמר לו: היום מימך מרובין, שמא לחתור בית אסורין אתה צריך\u0004 להשתמש במים אלה כדי לרכך את הטיט שבכתלי הבית? \u0003שפך חציין ונתן לו חציין\u0004 בלבד.","\u0003כשבא\u0004 ר' יהושע \u0003אצל ר' עקיבא,\u0004 וראה ר' עקיבא כמה מעטים המים, \u0003אמר לו: יהושע, אין אתה יודע שזקן אני וחיי תלויין בחייך?\u0004 שאין אדם אחר מביא לי מים, ואם אתה מביא פחות מכשיעור, מסתכן אני בחיי.","\u0003סח לו כל אותו המאורע.\u0004 לאחר מכן \u0003אמר לו\u0004 ר' עקיבא: \u0003תן לי מים שאטול ידי, אמר לו\u0004 ר' יהושע: הלא \u0003לשתות אין מגיעין\u0004 (מספיקים), \u0003ליטול ידיך מגיעין?! אמר לו: מה אעשה שחייבים עליהן,\u0004 על אכילה בלא נטילת ידים לפניה, \u0003מיתה,\u0004 כעובר על דברי חכמים? ואם כן, \u0003מוטב אמות מיתת עצמי\u0004 בצמא, \u0003ולא אעבור על דעת חבירי!\u0004","\u0003אמרו: לא טעם כלום עד שהביא לו מים ונטל ידיו\u0004, ו\u0003כששמעו חכמים בדבר אמרו: מה בזקנותו\u0004 ובחולשתו \u0003כך\u0004 היה מדקדק במצוות — \u0003בילדותו על אחת כמה וכמה. ומה בבית האסורין כך, שלא בבית האסורין על אחת כמה וכמה.\u0004","\u0003אמר רב יהודה אמר שמואל: בשעה שתיקן שלמה\u0004 המלך \u0003עירובין\u0004 (עירובי חצירות) \u0003ונטילת ידים\u0004 שהם סייגים נוספים על דברי תורה \u0003יצתה בת קול ואמרה: \"בני אם חכם לבך ישמח לבי גם אני\"\u0004 (משלי כג, טו). \u0003ו\u0004כן \u0003אומר\u0004 הכתוב עליו: \u0003\"חכם בני ושמח לבי ואשיבה חרפי דבר\"\u0004 (משלי כז, יא).","ועוד מביאים ממה ש\u0003דרש רבא: מאי דכתיב\u0004 \u0005[מהו שנאמר]\u0006 \u0003\"לכה דודי נצא השדה נלינה בכפרים נשכימה לכרמים נראה אם פרחה הגפן פתח הסמדר הנצו הרמונים שם אתן את דודי לך\"\u0004 (שיר השירים ז, יב-יג).","\u0003אמרה כנסת ישראל לפני הקדוש ברוך הוא: רבונו של עולם, אל תדינני כיושבי כרכים שיש בהן גזל ועריות ושבועת שוא ושבועת שקר,\u0004 אלא \u0003\"נצא השדה\" — בא ואראך תלמידי חכמים ש\u0004עובדי אדמה הם, ובכל זאת \u0003עוסקין בתורה מתוך הדחק\u0004 וביושר.","\u0003\"נלינה בכפרים\" — אל תקרי\u0004 \u0005[תקרא]\u0006 \u0003\"בכפרים\" אלא בכופרים,\u0004 כלומר: \u0003בא ואראך אותם\u0004 אומות העולם \u0003שהשפעת להן טובה והן כפרו בך.\u0004","\u0003\"נשכימה לכרמים\" — אלו בתי כנסיות ובתי מדרשות. \"נראה אם פרחה הגפן\" — אלו בעלי מקרא\u0004 שהם הלומדים בתחילת הלימוד. \u0003\"פתח הסמדר\" — אלו בעלי משנה. \"הנצו הרמונים\" — אלו בעלי גמרא. \"שם אתן את דודי לך\" — אראך כבודי וגודלי שבח בני ובנותי\u0004 כמה דבוקים הם בקדושה. ועוד דרשו על שלמה המלך.","\u0003אמר רב המנונא: מאי דכתיב\u0004 \u0005[מהו שנאמר]\u0006 \u0003\"וידבר שלשת אלפים משל ויהי שירו חמשה ואלף\".\u0004 (מלכים א' ה, יב) — \u0003מלמד שאמר שלמה על כל דבר ודבר של תורה, שלשת אלפים משל. על כל דבר ודבר של סופרים, חמשה ואלף טעמים.\u0004","עוד \u0003דרש רבא: מאי דכתיב\u0004 \u0005[מהו שנאמר]\u0006 \u0003\"ויתר שהיה קהלת חכם עוד לימד דעת את העם ואזן וחקר תיקן משלים הרבה\"\u0004 (קהלת י, ט). והוא מבאר: \"\u0003לימד דעת את העם\" — דאגמריה בסימני טעמים ואסברה במאי דדמי ליה\u0004 \u0005[שלמדו בסימני הטעמים\u0006 בתורה \u0005והסביר\u0006 דבר \u0005על ידי הדומה לו].\u0006","\"\u0003ואזן וחקר תקן משלים הרבה\" — אמר עולא אמר ר' אליעזר: בתחילה היתה תורה דומה לכפיפה\u0004 (סל) \u0003שאין לה אזנים\u0004 (ידיות) \u0003עד שבא שלמה ועשה לה אזנים,\u0004 שעל ידי הסבריו ומשליו ניתן לכל אדם להחזיק בה ולהבינה, לקיים מצוותיה ולהתרחק מדבר עבירה.","על הכתוב \"ראשו כתם פז \u0003קוצותיו תלתלים\u0004 שחורות כעורב\" (שיר השירים ה, יא) \u0003אמר רב חסדא אמר מר עוקבא:\u0004 \"קווצותיו\" \u0003מלמד שיש לדרוש על כל קוץ וקוץ\u0004 שבתורה \u0003תילי תילים של הלכות.\u0004","\u0003\"שחרות כעורב\"\u0004 משמעו: \u0003במי אתה מוצאן\u0004 את דברי התורה — \u0003במי\u0004"],["\u0003שמשכים\u0004 בשחר (שחורות) \u0003ומעריב\u0004 (עורב) \u0003עליהן לבית המדרש. רבה אמר: במי שמשחיר פניו עליהן כעורב\u0004, לאמור; שמתענה ומסתגף תוך לימוד התורה.","\u0003רבא אמר: במי שמשים עצמו אכזרי על בניו ועל בני ביתו כעורב, כי הא\u0004 \u0005[כמו זה]\u0006 ש\u0003רב אדא בר מתנא הוה קאזיל לבי רב\u0004 \u0005[היה הולך לבית הרב]\u0006 ללמוד תורה. \u0003אמרה ליה דביתהו\u0004 \u0005[לו אשתו]:\u0006 \u0003ינוקי דידך מאי אעביד להו\u0004 \u0005[התינוקות שלך מה אעשה להם]\u0006 לפרנסם כשאתה אינך מפרנסם? \u0003אמר לה: מי שלימו קורמי באגמא\u0004 \u0005[האם נגמרו\u0006 כבר \u0005הקנים באגם]?\u0006 ואם אין מאכל אחר, שיאכלו את קני הסוף.","על פסוק אחר אמרו: \u0003\"ומשלם לשנאיו אל פניו להאבידו\u0004 לא יאחר לשונאו אל פניו ישלם לו\u0003\"\u0004 (דברים ז, י). \u0003אמר ר' יהושע בן לוי: אילמלא מקרא כתוב, אי אפשר\u0004 היה \u0003לאומרו\u0004 מפני כבוד שמים, שכן הוא עלול להתפרש \u0003כביכול כאדם שנושא משוי על פניו, ומבקש להשליכו ממנו.\u0004 והוא שנאמר שאין ה' כביכול מסוגל לשאת את הדבר, אלא מעניש אלא בעולם הבא את הרשע.","על קטע הפסוק \u0003\"לא יאחר לשנאו\" אמר ר' אילא: לשנאיו הוא\u0004 ש\u0003לא יאחר\u0004 מתן שכרם אם קיימו דבריו \u0003אבל יאחר — לצדיקים גמורים\u0004 שמתן שכרם של צדיקים אינו בא מיד אלא לעולם הבא.","\u0003והיינו\u0004 \u0005[וזהו]\u0006 ש\u0003אמר ר' יהושע בן לוי: מאי דכתיב\u0004 \u0005[מהו שנאמר]\u0006 \u0003\"\u0004ושמרת את המצוה ואת החוקים ואת המשפטים \u0003אשר אנכי מצוך היום לעשותם\"\u0004 (דברים ז, יא) כוונתו \u0003\"היום לעשותם\"\u0004 — בעולם הזה, \u0003ולא למחר לעשותם —\u0004 שאין בעולם הבא חובה ואפשרות לקיים מצוות. ועוד זאת: \u0003היום — לעשותם,\u0004 ואילו רק \u0003למחר\u0004 לעתיד לבוא — \u0003לקבל שכרם.\u0004","ובענין זה \u0003אמר ר' חגי: ואיתימא\u0004 \u0005[ויש אומרים]\u0006 \u0003ר' שמואל בר נחמני, מאי דכתיב\u0004 \u0005[מהו שנאמר]\u0006 \"ויעבור ה' על פניו ויקרא ה' ה' אל רחום וחנון \u0003ארך אפים\u0004 ורב חסד ואמת\" (שמות לד, ו). ויש לדייק בכתוב: \"ארך אפיים\", \u0003\"ארך אף\" מבעי ליה\u0004 \u0005[צריך\u0006 היה \u0005לו\u0006 לומר\u0005]\u0006 ומדוע אמר \"ארך אפיים\" בלשון רבים?","כוונתו שיש שני מיני הארכת אף: \u0003ארך אפים לצדיקים —\u0004 שהוא ממתין בתשלום שכרם לעולם הבא, \u0003ארך אפים לרשעים —\u0004 שאין פורענותם באה עליהם מיד, אלא אף היא אינה באה אלא לעולם הבא.","במשנה נאמר ש\u0003ר' יהודה אומר\u0004 כי את הפסים עושים \u0003עד בית סאתים וכו'. איבעיא להו\u0004 \u0005[נשאלה להם,\u0006 לחכמים בבירור הענין\u0005]\u0006 האם הכוונה היא \u0003בור ופסין קאמר\u0004 \u0005[הוא אמר],\u0006 ששטח הבור עצמו על מחיצותיו והרחקו צריך להיות בית סאתים בלבד. \u0003או דילמא\u0004 \u0005[שמא]\u0006 \u0003בור\u0004 עצמו אינו אלא בית סאתים וב\u0003לא\u0004 שטח ה\u0003פסין\u0004 והרחקתם \u0003קאמר\u0004 \u0005[הוא אמר],\u0006","ועיקר בסיסה של השאלה: האם \u0003אדם נותן עיניו בבורו\u0004 ויודע שעושים מחיצה זו משום הבור, \u0003ו\u0004לכן כיון ששטח הבור אינו יותר מבית סאתיים \u0003לא גזרינן דילמא אתי לטלטולי\u0004 \u0005[אין אנו גוזרים שמא יבוא\u0006 לדמות מקום אחר אליו ו\u0005יטלטל]\u0006 \u0003יותר מבית סאתים בקרפף,\u0004","\u0003או דילמא\u0004 \u0005[שמא]\u0006 \u0003אדם נותן עיניו במחיצתו,\u0004 ואינו שם לב לשטח הבור אלא לכל ההיקף שהוא גדול יותר מבית סאתיים, \u0003וגזרינן דילמא אתי לאיחלופי\u0004 \u0005[וגוזרים אנו שמא יבוא להחליף]\u0006 \u0003יותר מבית סאתים בקרפף\u0004 משום הדמיון לפסים.","כדי לפתור מביאים ראיה. \u0003תא שמע\u0004 \u0005[בוא ושמע]\u0006 מה ששנינו בברייתא: \u0003כמה הן מקורבין\u0004 הפסים של הבור — \u0003כדי ראשה ורובה של פרה, וכמה הם מרוחקין — אפילו כור אפילו כוריים. ר' יהודה אומר: בית סאתים\u0004 בלבד — \u0003מותר, יתר מבית סאתים — אסור,\u0004","\u0003אמרו לר' יהודה: אי\u0004 \u0005[אין]\u0006 \u0003אתה מודה בדיר וסהר מוקצה, וחצר\u0004 ש\u0003אפילו\u0004 היו \u0003בית חמשת כורים ובית עשרת כורים שמותר\u0004 לטלטל בהם.","\u0003אמר להם\u0004 יש לחלק בדברים: \u0003זו\u0004 באותם המקרים בדיר וסהר וכיוצא בהם, \u0003מחיצה\u0004 גמורה יש להם, ומשום כך מותרים הם בטלטול אף ביותר מכבית סאתיים. \u0003ואלו\u0004 שמסביב לבור \u0003פסין\u0004 בלבד, והתירום בטלטול רק אם אין שטחם יותר מכבית סאתיים.","ו\u0003ר' שמעון בן אלעזר אומר: בור בית סאתים אבית סאתים — מותר, ולא אמרו להרחיק\u0004 את הפסים מן הבור \u0003אלא כדי ראשה ורובה של פרה.\u0004","ומדייקים: \u0003הא מדקאמר\u0004 \u0005[הרי מזה שאמר]\u0006 \u0003ר' שמעון בן אלעזר בור ולא\u0004 הזכיר \u0003פסין\u0004 אלא בור בלבד. \u0003מכלל\u0004 הדברים נסיק ש\u0003ר' יהודה בור ופסין קאמר\u0004 \u0005[הוא שאמר,\u0006 התכוון\u0005].\u0006 ודוחים: \u0003ולא היא, ר' יהודה\u0004 כשאמר שאין השטח המותר בטלטול אלא בית סאתיים הרי של \u0003בור בלא פסין קאמר\u0004 \u0005[הוא שאמר].\u0006","ושואלים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 \u0003היינו\u0004 \u0005[הרי זהו]\u0006 בדיוק מה שאמר \u0003ר' שמעון בן אלעזר.\u0004 ומשיבים: \u0003איכא בינייהו\u0004 \u0005[יש ביניהם]\u0006 הבדל למעשה כשהיה ההיקף \u0003אריך וקטין\u0004 \u0005[ארוך וצר]\u0006 שר' יהודה מתיר בה, ור' שמעון בן אלעזר מתיר רק אם היתה בית סאתיים רבועה.","ומוסיפים: \u0003כלל אמר ר' שמעון בן אלעזר: כל אויר\u0004 (חלל מוקף מחיצה, ואפילו אינו מקורה) \u0003שתשמישו לדירה כגון דיר וסהר מוקצה וחצר, אפילו בית חמשת כורים ובית עשרת כורים — מותר\u0004 בטלטול.","\u0003וכל דירה שתשמישה לאויר\u0004 ולא נעשתה מחיצתה לדור בה אלא לצורך החלל והחצר \u0003כגון בורגנין שבשדות,\u0004 אם היתה \u0003בית סאתים — מותר\u0004 לטלטל בה, \u0003יתר מבית סאתים — אסור.\u0004","\u0003ר' יהודה אומר: אם היה דרך רשות הרבים מפסקתן\u0004 שהיתה דרך הרבים עוברת בין הפסים — \u0003יסלקנה לצדדין\u0004 שיעברו הרבים סביב הפסים, שהרי לא יתכן שיהו רבים עוברים שם שעדיין דינו כרשות יחיד גמורה. \u0003וחכמים אומרים: אינו צריך,\u0004 ואין הפסים נפגמים על ידי הדרך העוברת ביניהם.","\u0003ר' יוחנן ור' אלעזר דאמרי תרווייהו\u0004 \u0005[שאמרו שניהם]:\u0006 \u0003כאן\u0004 בדברי חכמים \u0003הודיעך כוחן של מחיצות,\u0004 שאף שדרך הרבים עוברת בין המחיצות — עדיין יפה כוח המחיצות להתיר בטלטול, אף שלכאורה אינן מועילות למעשה.","על עצם שיטתו של ר' יוחנן תוהים: האם כוונת דבריו היא ש\u0003כאן\u0004 הביעו חכמים סברה זו, \u0003וסבירא ליה\u0004 \u0005[וסבור הוא עצמו\u0006 גם כך\u0005]\u0006 שדרך הרבים אינה מבטלת מחיצות? \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רבה בר בר חנה אמר ר' יוחנן: ירושלים אילמלא\u0004 היו \u0003דלתותיה ננעלות בלילה, חייבין עליה משום רשות הרבים,\u0004 נמצא שאף על פי שיש לעיר חומות אם לא היו דלתותיה ננעלות היתה העיר נחשבת כרשות הרבים, וזאת משום דרך הרבים העוברת בתוכה. הרי שאין כוח המחיצה מספיק לבטל בקיעת רבים.","\u0003אלא\u0004 יש לפרש: \u0003כאן\u0004 אמרו חכמים דבר זה \u0003ולא סבירא ליה\u0004 \u0005[ו\u0006הוא עצמו \u0005אינו סבור]\u0006 כך להלכה.","ומעירים: \u0003ורמי\u0004 \u0005[והשלך\u0006, מצא סתירה\u0005]\u0006 בין דברי \u0003ר' יהודה\u0004 כאן לדברי \u0003ר' יהודה\u0004 במקום אחר. \u0003ורמי\u0004 \u0005[והשלך\u0006, מצא סתירה\u0005]\u0006 בין דברי \u0003רבנן\u0004 \u0005[חכמים]\u0006 לדברי \u0003רבנן\u0004 \u0005[חכמים]\u0006 במקום אחר.","\u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בתוספתא\u0005]:\u0006 \u0003יתר על כן אמר ר' יהודה: מי שהיו לו שני בתים משני צידי רשות הרבים, עושה לחי מכאן ולחי מכאן\u0004 בצד הפונה החוצה, \u0003או קורה מכאן וקורה מכאן, ונושא ונותן באמצע.\u0004 שהשטח שבאמצע נעשה כרשות היחיד בשל שתי המחיצות. \u0003אמרו לו: אין מערבין רשות הרבים בכך\u0004 על ידי לחי בלבד, בעוד הרבים ממשיכים להלך ברחוב העיר שבאמצע.","ואם כן \u0003קשיא\u0004 \u0005[קשה]\u0006 מדברי \u0003ר' יהודה\u0004 על דברי \u0003ר' יהודה,\u0004 ו\u0003קשיא\u0004 \u0005[קשה]\u0006 מדברי \u0003רבנן\u0004 \u0005[חכמים]\u0006 על דברי \u0003רבנן\u0004 \u0005[חכמים]\u0006.","ומתרצים שיש להבחין בין המקרים: מדברי \u0003ר' יהודה\u0004 על דברי \u0003ר' יהודה, לא קשיא\u0004 \u0005[קשה]\u0006 שיש לחלק: \u0003התם\u0004 \u0005[שם]\u0006 בבתים — \u0003דאיכא\u0004 \u0005[שיש]\u0006 \u0003שתי מחיצות מעלייתא\u0004 \u0005[מעולות].\u0006 שהרי הבתים מחיצות של ממש הם, ודי בשתי מחיצות כדי לתחום רשות לעצמה. ואילו \u0003הכא\u0004 \u0005[כאן]\u0006 בפסים — \u0003ליכא\u0004 \u0005[אין]\u0006 \u0003שתי מחיצות מעלייתא\u0004 \u0005[מעולות],\u0006 שהרי הפסים אינם מחיצות גמורות,","אף מדברי \u0003רבנן\u0004 \u0005[חכמים]\u0006 על דברי \u0003רבנן\u0004 \u0005[חכמים]\u0006 \u0003נמי\u0004 \u0005[גם כן]\u0006 \u0003לא קשיא\u0004 \u0005[קשה]\u0006, כי \u0003הכא\u0004 \u0005[כאן\u0006 בפסים\u0005] —\u0006 \u0003איכא\u0004 \u0005[יש]\u0006 לפחות \u0003שם ארבע מחיצות\u0004 שהרי הבור מוקף והוא קרוי מוקף בארבע מחיצות, \u0003התם\u0004 \u0005[שם\u0006 בבתים\u0005] —\u0006 \u0003ליכא\u0004 [\u0005אין]\u0006 אפילו \u0003שם ארבע מחיצות.\u0004","\u0003אמר ר' יצחק בר יוסף אמר ר' יוחנן: ארץ ישראל אין חייבין עליה משום רשות הרבים, יתיב\u0004 \u0005[ישב]\u0006 \u0003רב דימי וקאמר ליה להא שמעתא\u0004 \u0005[ואמר את ההלכה הזאת].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי לרב דימי: מאי טעמא\u0004 \u0005[מה הטעם]\u0006 על מה מתבססים דברים אלה?"],["\u0003אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003משום\u0004 ש\u0003מקיף לה\u0004 \u0005[אותה]\u0006 \u0003סולמא\u0004 \u0005[סולמה]\u0006 של \u0003צור מהך גיסא\u0004 \u0005[מצד זה],\u0006 \u0003ומחתנא דגדר מהך גיסא\u0004 \u0005[ומורד גדר\u0006 עמוק עשרה טפחים ורחב ארבעה טפחים \u0005מצד זה]\u0006 \u0003בבל נמי\u0004 \u0005[גם כן]\u0006 \u0003מקיף לה\u0004 נהר \u0003פרת מהך גיסא\u0004 \u0005[מצד זה],\u0006 \u0003ו\u0004נהר \u0003דיגלת מהאי גיסא\u0004 \u0005[מצד זה]\u0006 ואף היא לא תיחשב כרשות הרבים. וכן \u0003דכולא עלמא נמי\u0004 \u0005[\u0006ואת \u0005כל העולם גם כן]\u0006 \u0003מקיף אוקיינוס.\u0004 ונמצא שאין רשות הרבים כלל בעולם, אלא \u0003דילמא\u0004 \u0005[שמא]\u0006 \u0003מעלות ומורדות\u0004 שבארץ ישראל \u0003קאמרת\u0004 \u0005[אמרת]\u0006 שאינם נוחים להילוך ולכן אין עליהם דין רשות הרבים?","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב דימי: \u0003קרקפנא\u0004 \u0005[בעל הגולגולת,\u0006 אדם גדול\u0005],\u0006 \u0003חזיתיה לרישך בי עמודי כי\u0004 \u0005[ראיתי את ראשך בין העמודים\u0006 של בית המדרש \u0005כאשר]\u0006 \u0003אמרה ר' יוחנן להא שמעתא\u0004 \u0005[את זאת השמועה,\u0006 ההלכה\u0005]\u0006 כלומר, הרי אתה מכוון למשמעות הדברים כאילו היית בין עמודי בית המדרש, ושמעת את הדברים מר' יוחנן עצמו.","\u0003איתמר נמי\u0004 \u0005[נאמר גם כן]\u0006 \u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רבין\u0004 מארץ ישראל \u0003אמר ר' יוחנן, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 \u0003אמר ר' אבהו אמר ר' יוחנן: מעלות ומורדות שבארץ ישראל אין חייבין עליהן משום רשות הרבים לפי שאינן כדגלי מדבר\u0004 שאין רשות הרבים אלא בדומה למקום שהלכו בו שבטי (דגלי) בני ישראל ביציאת מצרים, שהיה מקום ישר ונוח להילוך הרבים.","\u0003בעא מיניה\u0004 \u0005[שאל אותו]\u0006 \u0003רחבה מרבא: תל המתלקט עשרה מתוך ארבע,\u0004 כלומר, שמגיע גובהו לעשרה טפחים בתוך אורך שיפוע של ארבע אמות ויש בו איפוא התנאים היוצרים רשות היחיד, \u0003ו\u0004אולם \u0003רבים בוקעים\u0004 (מהלכים) \u0003בו, חייבין עליו משום רשות הרבים או אין חייבין עליו?\u0004","ומפרשים את הדברים: \u0003אליבא דרבנן לא תיבעי לך\u0004 \u0005[על פי שיטת חכמים לא תישאל לך\u0006 השאלה כלל \u0005]\u0006 \u0003השתא ומה התם דניחא תשמישתיה אמרי רבנן לא אתו רבים ומבטלי לה מחיצתא\u0004 \u0005[עכשיו, ומה שם\u0006 בפסים \u0005שנוח תשמישה\u0006 של רשות הרבים \u0005אמרו חכמים שאין הרבים באים ומבטלים את המחיצה],\u0006 \u0003הכא, דלא ניחא תשמישתיה — לא כל שכן\u0004 \u0005[כאן שלא נוח תשמישו,\u0006 במדרון — \u0005לא כל שכן]\u0006 שיחשב התל כמחיצה היוצרת רשות היחיד ואין דריסת הרבים מבטלתה.","\u0003כי תיבעי לך אליבא\u0004 \u0005[כי תישאל לך\u0006 השאלה, הרי זה \u0005לשיטת]\u0006 \u0003ר' יהודה מאי\u0004 \u0005[מהו],\u0006 \u0003התם הוא דניחא תשמישתיה, הכא הוא דלא ניחא תשמישתיה; לא אתו רבים ומבטלי מחיצתא\u0004 \u0005[שם הוא שנוח שימושה\u0006 של רשות הרבים, \u0005כאן שלא נוח שימושה, אין הרבים באים ומבטלים מחיצה]\u0006 \u0003או דילמא לא שנא\u0004 \u0005[או שמא אינו שונה]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003חייבין\u0004 משום רשות הרבים.","שאלו רחבה: והאם תאמר הלכה זו \u0003ואפילו\u0004 מדרון זה משופע עד כדי כך שכדי לטפס עליו \u0003עולין לו בחבל\u0004 שיש להיעזר בחבל כדי לטפס בו. אמר לו: \u0003אין\u0004 \u0005[כן]\u0006 שאלו: \u0003ואפילו ב\u0004מקום ששמו \u0003מעלות בית מרון,\u0004 שהן תלולות ביותר\u0003?! אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אין\u0004 \u0005[כן].\u0006","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 רחבה מן התוספתא: \u0003חצר\u0004 המגודרת מסביב \u0003שהרבים נכנסין לה\u0004 בכניסה \u0003זו ויוצאין בזו;\u0004 הרי היא נחשבת כ\u0003רשות הרבים\u0004 לענין \u0003טומאה,\u0004 וכל ספק טומאה בתוכה הוא טהור, ואולם עדיין \u0003רשות היחיד\u0004 היא לענין \u0003שבת.\u0004","ומעתה נברר \u0003מני\u0004 \u0005[של מי היא]\u0006 הלכה זו; \u0003אילימא רבנן\u0004 \u0005[אם תאמר חכמים]\u0006 \u0003השתא\u0004 \u0005[עכשיו]\u0006 \u0003ומה התם דניחא תשמישתיה אמרי רבנן לא אתי רבים ומבטלי מחיצתא\u0004 \u0005[ומה שם\u0006 בפסים \u0005שנוח תשמישה\u0006 של דרך הרבים \u0005אמרו חכמים אין הרבים באים ומבטלים מחיצה],\u0006 \u0003הכא דלא ניחא תשמישתיה\u0004 \u0005[כאן,\u0006 בחצר, \u0005שאין נוח תשמישה\u0006 למעבר רבים\u0005]\u0006 \u0003לא כל שכן\u0004 שאין הרבים יכולים לבטל מחיצה, ולא היה מקום לפרט הלכה זו במיוחד.","\u0003אלא לאו\u0004 \u0005[האם לא]\u0006 כשיטת \u0003ר' יהודה היא?\u0004 ונמצא שאף ר' יהודה מחלק בין דרך לדרך.","ענה לו: \u0003לא, לעולם\u0004 תפרש שהלכה זו כשיטת \u0003רבנן\u0004 \u0005[חכמים]\u0006 היא, ומה ששאלת מה חידוש בדבר לשיטתם \u0003ו\u0004הרי \u0003רשות הרבים לטומאה איצטריכא ליה\u0004 \u0005[הוצרכה לו\u0006 להשמיענו]. שאף על פי שחצר זו רשות היחיד לשבת מכל מקום חידש שרשות הרבים היא לענין טומאה. שוב מנסה רחבה להביא ראייה מן המשנה.","\u0003תא שמע\u0004 \u0005[בא ושמע]\u0006 מה ששנינו: \u0003מבואות המפולשות בבורות, בשיחין ובמערות,\u0004 הרי הן \u0003רשות היחיד לשבת, ורשות הרבים לטומאה.\u0004","ומתחילה מבררים את לשון המשנה: \u0003\"בבורות\" סלקא דעתך\u0004 \u0005[עולה על דעתך],\u0006 וכי אפשר לדבר על מבואות מפולשים בתוך בורות? \u0003אלא\u0004 יש לתקן כך: מבואות המפולשות \u0003לבורות\u0004 הרי הם \u0003רשות היחיד לשבת, ורשות הרבים לטומאה.\u0004","ומעתה נברר \u0003מני\u0004 \u0005[של מי היא\u0006 משנה זו], \u0003אילימא רבנן\u0004 \u0005[אם תאמר חכמים]\u0006 \u0003השתא\u0004 \u0005[עכשיו]\u0006 \u0003ומה התם\u0004 \u0005[שם,\u0006 בפסים\u0005] —\u0006 \u0003דניחא תשמישתיה, אמרי: לא אתו רבים ומבטלי לה\u0004 \u0005[שנוח תשמישה\u0006 של דרך הרבים\u0005, אמרו\u0006 חכמים \u0005: אין הרבים באים ומבטלים אותה,\u0006 את המחיצה\u0005].\u0006 \u0003הכא\u0004 \u0005[כאן,\u0006 בחצר\u0005] —\u0006 \u0003דלא ניחא תשמישתיה\u0004 \u0005[שלא נוח תשמישה\u0006 למעבר רבים\u0005],\u0006 \u0003לא כל שכן. אלא לאו\u0004 \u0005[האם לא]\u0006 כשיטת \u0003ר' יהודה היא!\u0004","ודחה רבא: \u0003לא, לעולם\u0004 תפרש שהלכה זו כשיטת \u0003רבנן\u0004 \u0005[חכמים]\u0006 היא, ואם תשאל מה חידוש יש בדבר? החידוש הוא שדין \u0003רשות הרבים לטומאה\u0004 היא \u0003איצטריכא ליה\u0004 \u0005[הוצרכה לו\u0006 להשמיענו\u0005]\u0006 שאף על פי שאין נוח להלך בהם, כיון שבכל זאת הרבים מצויים שם הרי זו רשות הרבים לענין טומאה.","שוב רוצה רחבה להביא ראיה מן המשנה. \u0003תא שמע\u0004 \u0005[בא ושמע]\u0006 מה ששנינו: \u0003שבילי בית גילגול\u0004 (שבילים הקשים להילוך) \u0003וכיוצא בהן\u0004, הרי דינם כ\u0003רשות היחיד לשבת ורשות הרבים לטומאה,\u0004","\u0003ואיזהו שבילי בית גילגול? אמרי דבי\u0004 \u0005[אומרים\u0006 בני \u0005בית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ינאי: כל שאין העבד יכול ליטול\u0004 על גופו \u0003סאה של חיטין וירוץ לפני סרדיוט\u0004 \u0005[חייל],\u0006 שאף מפני אימתו את איש הצבא אינו יכול לרוץ,","ונברר \u0003מני\u0004 \u0005[של מי היא\u0006 משנה זו\u0005]\u0006 \u0003אילימא רבנן, השתא ומה התם דניחא תשמישתא, אמרי רבנן: לא אתו רבים ומבטלי לה מחיצתא. הכא, דלא ניחא תשמישתא\u0004 \u0005[עכשיו, ומה שם\u0006 בפסי בור \u0005שנוח תשמישה\u0006 לרבים \u0005אמרו חכמים: אין הרבים באים ומבטלים את המחיצה. כאן, שלא נוח תשמישה],\u0006 \u0003לא כל שכן! אלא לאו\u0004 \u0005[האם לא]\u0006 \u0003ר' יהודה?\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003שבילי בית גילגול קאמרת, יהושע\u0004 שכבש את הארץ וחילקה \u0003אוהב ישראל היה, עמד ותיקן להם דרכים וסרטיא\u0004 (דרך המלך), \u0003כל היכא דניחא תשמישתא\u0004 \u0005[כל מקום שנוח שימושו]\u0006 \u0003מסרה לרבים,\u0004 ו\u0003כל היכא דלא ניחא תשמישתא\u0004 \u0005[וכל מקום שלא נוח שימושו]\u0006 \u0003מסרה ליחיד.\u0004 ודבר זה נאמר רק בארץ ישראל בלבד אבל אין לקבוע כלל שכל מקום אחר שקשה להלך בו אינו נידון כרשות הרבים.","\u0003אחד בור\u0004 מקום כינוס מים, אבל שאין מימיו נובעים, השייך ל\u0003רבים. ובאר\u0004 שמימיה נובעים, והיא של \u0003הרבים,\u0004 ואפילו \u0003באר היחיד; עושין להן פסין\u0004 להתירם כפי שאמרנו.","\u0003אבל לבור היחיד\u0004, שיש בו שני חסרונות: שהוא של יחיד ושאין מימיו נובעים — אין אפשרות להתיר לשאוב ממנו בשבת על ידי פסים אלא אם כן \u0003עושין לו מחיצה גבוהה\u0004 גמורה בת \u0003עשרה טפחים,\u0004 אלו \u0003דברי ר' עקיבא.\u0004","\u0003ר' יהודה בן בבא אומר: אין עושין פסין אלא לבאר הרבים בלבד, ולשאר,\u0004 כגון: בור הרבים, או באר היחיד — \u0003עושין חגורה\u0004 (היקף חבלים) \u0003גבוה עשרה טפחים\u0004 שהרי מכח דין לבוד דינה כמחיצה מעולה."],["\u0003אמר רב יוסף אמר רב יהודה אמר שמואל: הלכה כר' יהודה בן בבא. ואמר רב יוסף אמר רב יהודה אמר שמואל: לא הותרו פסי ביראות\u0004 ותקנתם \u0003אלא לבאר מים חיים בלבד.\u0004","ומעירים: \u0003וצריכא\u0004 \u0005[וצריך]\u0006 להשמיענו שתי הלכות אלה אף שלכאורה תוכנן זהה. שכן \u0003אי אשמעינן\u0004 \u0005[אילו היה משמיע לנו]\u0006 רק \u0003הלכה כר' יהודה בן בבא\u0004 במשנתנו שאמר שאין עושים פסים אלא לבאר בלבד, \u0003הוה אמינא\u0004 \u0005[הייתי אומר]\u0006 של \u0003רבים, ואפילו\u0004 אינם מים חיים אלא אף \u0003מכונסין,\u0004","\u0003והאי דקתני\u0004 \u0005[וזו ששנינו]\u0006 \u0003באר הרבים — לאפוקי\u0004 \u0005[להוציא]\u0006 \u0003מ\u0004דברי \u0003ר' עקיבא,\u0004 אבל אין לדייק במלה באר שהוא דווקא מים חיים, אלא הכוונה גם לבור שמימיו נקווים ואינם נובעים. על כן \u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 ש\u0003לא הותרו פסי ביראות אלא לבאר מים חיים\u0004 נובעים.","\u0003ו\u0004להיפך, \u0003אי אשמעינן\u0004 \u0005[ואילו היה משמיע לנו]\u0006 שעושים פסים רק ל\u0003באר מים חיים הוה אמינא\u0004 \u0005[הייתי אומר]:\u0006 \u0003לא שנא\u0004 \u0005[שונה]\u0006 של \u0003רבים ולא שנא\u0004 \u0005[שונה]\u0006 של \u0003יחיד,\u0004 על כן \u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 שמואל: \u0003הלכה כר' יהודה בן בבא,\u0004 משמע — באר הרבים ולא של יחיד.","\u0003ועוד אמר ר' יהודה בן בבא: הגינה והקרפף\u0004 (חצר מגודרת) \u0003שהן שבעים אמה ושיריים\u0004 (ועוד משהו כאשר יבואר להלן), \u0003על שבעים אמה ושיריים, המוקפות גדר גבוה עשרה טפחים — מטלטלין בתוכה\u0004 שהריהי רשות יחיד גמורה, \u0003ובלבד שיהא בה שומירה\u0004 (סוכת שומרים) \u0003או בית דירה או שתהא\u0004 חצר או גינה, או קרפף זה, \u0003סמוכה לעיר\u0004 ומחמת סמיכותה דעתו להשתמש בה ונחשבת כחצר שבעיר.","\u0003ר' יהודה אומר:\u0004 אין צורך בתנאי זה דוקא אלא \u0003אפילו אין בה\u0004 באותה גינה \u0003אלא בור ושיח\u0004 (בור שפתחו מארך) \u0003ומערה\u0004 (בור מקורה שיש בו מים) \u0003מטלטלין בתוכה,\u0004 שמשום מקוה המים שבתוכה הריהי כבית דירה. \u0003ר' עקיבא אומר: אפילו אין בה אחת מכל אלו — מטלטלין בתוכה, ובלבד שיהא בה שבעים אמה ושיריים על שבעים אמה ושיריים.\u0004","\u0003ר' אליעזר אומר: אם היתה ארכה יתר על רחבה, אפילו אמה אחת אין מטלטלין בתוכה,\u0004 ואף על פי שאין שטחה עולה על בית סאתיים, שלא הותר טלטול בחצר שאינה עשויה לדירה אלא אם כן היתה רבועה, שאורכה כרוחבה. \u0003ר' יוסי אומר: אפילו ארכה פי שנים ברחבה — מטלטלין בתוכה,\u0004 ואין להקפיד על הריבוע.","\u0003אמר ר' אלעאי: שמעתי מר' אלעזר, ואפילו\u0004 גינה זו \u0003היא\u0004 גדולה \u0003כבית כור,\u0004 כלומר: פי שלושים יותר מהמידות שהוזכרו קודם לכן.","ואגב כך הזכיר: \u0003וכן שמעתי ממנו\u0004 הלכה אחרת. \u0003אנשי חצר ששכח אחד מהן ולא עירב,\u0004 ואילו שאר אנשי החצר עירבו עירוב חצרות — \u0003אסור מלהכניס ולהוציא\u0004 מן הבית לחצר \u0003לו —\u0004 לזה ששכח לערב, \u0003אבל להם מותר\u0004 להכניס חפצים מן החצר לביתו. ואין אנו אומרים שבשל הדייר שלא עירב בטלה תורת עירוב מכל החצר כולה.","\u0003וכן שמעתי ממנו\u0004 עוד הלכה: \u0003שיוצאין בערקבלין\u0004 (מין ירק מר) משום מרור \u0003בפסח.\u0004 ובכל שלושת הלכות אלו \u0003חזרתי על כל תלמידיו\u0004 של ר' אלעזר \u0003וביקשתי לי חבר\u0004 שגם הוא שמע דברים אלו מפיו \u0003ולא מצאתי.\u0004","מתחילה מבררים את לשונה של משנה זו: \u0003מאי\u0004 \u0005[מהי]\u0006 לשונו המיוחדת של ה\u0003תנא דקתני\u0004 \u0005[ש\u0006התחיל \u0005שונה]\u0006 משנה זו ב\"\u0003ועוד\u0004 אמר ר' יהודה בן בבא\" שמשמעה המשך לשיטתו במשנה הקודמת.","\u0003אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003משום דתנא ליה חדא לחומרא וקתני אחריתי\u0004 \u0005[ששנה לו\u0006 הלכה \u0005אחת לחומרה\u0006 בענין פסי באר \u0005ושנה אחרת],\u0006 \u0003משום הכי\u0004 \u0005[כך]\u0006 \u0003קתני\u0004 \u0005[שנה]\u0006 מלת \u0003\"ועוד\" — והא\u0004 \u0005[והרי]\u0006 \u0003ר' יהודה\u0004 בר אלעאי במשנתנו, \u0003דתנא ליה חדא לחומרא וקתני אחריתי, ולא קתני\u0004 \u0005[ששנה\u0006 שיטה \u0005אחת לחומרה ושנה אחרת, ואינו שונה]\u0006 \"\u0003ועוד\u0004 אמר ר' יהודה\"!","ומשיבים: יש להבדיל בין הדברים: \u0003התם אפסקוה רבנן\u0004 \u0005[שם הפסיקוהו חכמים]\u0006 בין דבר ודבר כדי לחלוק עליו, ומשום כך אין לומר \"ועוד אמר ר' יהודה\". \u0003הכא לא אפסקוה רבנן\u0004 \u0005[כאן לא הפסיקוהו חכמים]\u0006 שדבריו של ר' יהודה בן בבא סמוכים זה לזה.","ומקשים: \u0003וכל היכא דאפסקוה רבנן לא קתני\u0004 \u0005[ו\u0006כי \u0005בכל מקום שהפסיקוהו חכמים\u0006 החולקים עליו \u0005אינו שונה]\u0006 \u0003\"ועוד\"? והא\u0004 \u0005[והרי]\u0006 \u0003ר' אליעזר\u0004 במשנה במסכת \u0003סוכה\u0004 (כז, א) \u0003דאפסקוה רבנן\u0004 \u0005[שהפסיקוהו חכמים],\u0006 \u0003ו\u0004בכל זאת \u0003קתני\u0004 \u0005[שנה]\u0006 \u0003\"ועוד\"!?\u0004","ומשיבים: אינו דומה; \u0003התם במילתיה הוא דאפסקוה\u0004 \u0005[שם בענינו הוא\u0006 \u0005שהפסיקוהו]\u0006 שנחלקו בפרט ובאותו נושא עצמו. \u0003הכא במילתא אחריתי אפסקוה\u0004 \u0005[כאן בדבר אחר הפסיקוהו]\u0006 ומשום כך כבר נשכח ענין ראשון ואין זה מסגנון המשנה לצרף דברים כאשר הקשר הרצוף ביניהם כבר נותק.","מביאים מן המשנה את דברי \u0003ר' עקיבא\u0004 ה\u0003אומר,\u0004 ש\u0003אפילו\u0004 אם \u0003אין בה\u0004 בחצר \u0003אחד מכל אלו\u0004 התנאים שאמרו בה חכמים אחרים \u0003מטלטלין בתוכה,\u0004 ובלבד שיהיו בה שבעים אמה ושיריים על שבעים אמה ושיריים."],["\u0003ר' עקיבא היינו תנא קמא\u0004 \u0005[זהו התנא הראשון]\u0006 כלומר חכמים שאמרו במשנה לעיל (עירובין יח, א) שלא אמרו שבית סאתיים מותר בטלטול אלא בגינה שאינה מוקפת לדירה, אבל אם היתה מוקפת לדירה, מותר לטלטל בה כפי צרכה, אף על פי ששטחה גדול מאוד. ומשמע מדבריו שבגינה וכדומה, אף שאינה מוקפת לדירה, מותר לטלטל בה מכל מקום אם אין היקפה עולה על בית סאתיים. וזוהי בדיוק שיטת ר' עקיבא כאן.","ומשיבים: \u0003איכא בינייהו\u0004 \u0005[יש ביניהם\u0006 הבדל למעשה\u0005]\u0006 ב\u0003דבר מועט.\u0004 ומהו דבר מועט זה? \u0003דתניא\u0004 \u0005[ששנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' יהודה אומר: דבר מועט יש על שבעים אמה ושיריים, ולא נתנו חכמים בו שיעור\u0004 שהוא שטח חצר רבועה ששיטחה בית סאתיים ולא נתנו בו שיעור מפני קוטנו ומפני שאין להגיע לדיוק מוחלט בענין זה.","\u0003וכמה שיעור\u0004 בית \u0003סאתים? כחצר המשכן\u0004 שהוא חמישים על מאה אמה. ובדבר זה נחלקו חכמים ור' עקיבא, שחכמים אומרים שצריך להיות שיעור החצר מדויק כריבוע המגיע לבית סאתים ור' עקיבא אומר שאין להקפיד בהבדל מועט זה, ודי בחשבון שבעים אמה ושיריים ששיערו אף שהוא פחות.","ושואלים: \u0003מנא הני מילי\u0004 \u0005[מנין דברים אלו]\u0006 שיש לרבע את חצר המשכן כדי לשער בשכמותה לענין שבת?","ומשיבים: \u0003אמר רב יהודה\u0004 שכן \u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"ארך החצר מאה באמה ורחב חמשים בחמשים\u0004 וקמה חמש אמות שש משזר ואדניהם נחושת\u0003\"\u0004 (שמות כז, יח) \u0003אמרה תורה: טול חמשים\u0004 אמה שאורכו עודף על רוחבו, \u0003וסבב\u0004 את אותם \u0003חמשים\u0004 אמה הנותרים, וחלקם באופן שווה להוסיפם על החמישים שנשארו, עד שיגיעו לצורת ריבוע ששיעורו בית סאתיים.","ושואלים: \u0003פשטיה דקרא במאי כתיב\u0004 \u0005[פשוטו של מקרא במה נאמר]?!\u0006 שהרי פשוטו של מקרא לא בא ללמדנו דיני עירובין? \u0003אמר אביי\u0004: משמעו \u0003העמד משכן על שפת חמשים\u0004 אמה, \u0003כדי שיהא\u0004 שטח של \u0003חמשים אמה לפניו, ועשרים אמה לכל רוח ורוח\u0004 בצידיו ומאחריו.","שנינו במשנה ש\u0003ר' אליעזר אומר: אם היתה ארכה\u0004 יתר על רחבה אף אמה אחת הרי היא אסורה בטלטול. ומקשים: \u0003והתניא\u0004 \u0005[הרי שנינו\u0006 בברייתא\u0005]\u0006 \u0003ר' אליעזר אומר: אם היתה ארכה יתר על פי שנים ברחבה אפילו אמה אחת אין מטלטלין בתוכה!\u0004","\u0003אמר רב ביבי בר אביי: כי תנן נמי מתניתין\u0004 \u0005[כאשר שנינו גם כן במשנתנו]\u0006 משמעות הדברים היא \u0003יתר על פי שנים ברחבה תנן\u0004 \u0005[שנינו]\u0006. \u0003ומקשים: אי הכי, היינו\u0004 \u0005[אם כך\u0006 הלא \u0005זוהי]\u0006 שיטת \u0003ר' יוסי\u0004 האמורה במשנה, שאף הוא מתיר בשאורכה כפול מרוחבה?!","ומשיבים: \u0003איכא בינייהו ריבועא דריבעוה רבנן\u0004 \u0005[יש ביניהם\u0006 הבדל \u0005בריבוע שריבעו אותה חכמים]\u0006 שלשיטת ר' אליעזר אם היה אורכו יותר מכפול על רוחבו, אפילו באמה, כך שאם יימדד אלכסונו יהיה אורכו יותר מפי שניים מרוחבו, ואסור. ולשיטת ר' יוסי — מותר (ר\"ח).","שנינו במשנה ש\u0003ר' יוסי אומר\u0004: אם היתה יתרה על פי שנים ברוחבה כשרה. \u0003איתמר\u0004 \u0005[נאמר]\u0006 על ידי אמוראים, \u0003אמר רב יוסף אמר רב יהודה אמר שמואל: הלכה כר' יוסי. ורב ביבי אמר רב יהודה אמר שמואל: הלכה כר' עקיבא\u0004.","ומסבירים כי \u0003תרוייהו לקולא\u0004 \u0005[שניהם\u0006 נתכוונו \u0005להקל]\u0006 עד כמה שאפשר. \u0003וצריכא\u0004 \u0005[וצריך,\u0006 נחוץ\u0005]\u0006 להשמיענו את שני הדברים. \u0003דאי אשמעינן\u0004 \u0005[שאילו היה משמיע לנו]\u0006 רק \u0003הלכה כר' יוסי הוה אמינא\u0004 \u0005[הייתי אומר]\u0006 \u0003עד דאיכא\u0004 \u0005[שיש]\u0006 במקום \u0003שומירה או בית דירה,\u0004 שהרי לא פירש ר' יוסי בדבריו שאין צורך בכך. על כן \u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 ש\u0003הלכה כר' עקיבא\u0004 שאינו מקפיד אלא בשטחה של החצר.","\u0003ו\u0004מן הצד השני, \u0003אי אשמעינן\u0004 \u0005[אילו היה משמיענו]\u0006 רק \u0003הלכה כר' עקיבא, הוה אמינא\u0004 \u0005[הייתי אומר]\u0006 אם הוא \u0003אריך וקטין\u0004 \u0005[ארוך וצר] —\u0006 \u0003לא.\u0004 לכן \u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 ש\u0003הלכה כר' יוסי\u0004 אפילו לא היתה החצר בריבוע.","אמרו חכמים: \u0003קרפף שהוא יותר מבית סאתים\u0004 אבל \u0003שהוקף\u0004 מתחילה \u0003לדירה\u0004, שבקרפף כזה מותר לטלטל בכל שיעור שיש בו, ואחר כך \u0003נזרע רובו — הרי הוא\u0004 נעשה \u0003כגינה\u0004 שאינה מקום לדירה, \u0003ואסור\u0004 לטלטל בו.","ואולם, אם \u0003נטע\u0004 אילנות ב\u0003רובו — הרי הוא כחצר, ומותר\u0004. וטעמו של דבר שאילנות נוטעים גם בחצר בית דירה ומציאות אילנות בחצר אינה מבטלת אותה מתורת מקום דיור לבני אדם. אולם אין זורעים אלא בגינה מרוחקת מבית דירה שמציאות זרעים בגינה מבטלת אותה מתורת דירה.","\u0003נזרע רובו — אמר רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע: לא אמרן\u0004 \u0005[לא אמרנו]\u0006 שיש איסור טלטול בגינה זרועה \u0003אלא\u0004 כשהיה המקום הזרוע \u0003יותר מבית סאתים. אבל בית סאתים\u0004 בדיוק — \u0003מותר\u0004.","ומעירים: \u0003כמאן\u0004 \u0005[כ\u0006שיטת \u0005מי\u0006 דבר זה\u0005?]\u0006 \u0003כר' שמעון\u0004 דת \u0003נן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005],\u0006 \u0003ר' שמעון אומר: אחד גגות ואחד חצירות ואחד קרפיפות — רשות אחת הן לכלים ששבתו בתוכן\u0004 אפילו כשהכלים שייכים לבעלים שונים, כיון שאינם בית דירה גמור אין צורך לערב בהן ומותר לטלטל ביניהם ממקום למקום, אבל טלטול כזה \u0003לא\u0004 הותר אם אותם \u0003כלים\u0004 הוצאו לחצר לאחר \u0003ששבתו בתוך הבית\u0004 ורוצה להעבירם. ונמצא שחלק הקרפף שאינו זרוע והחלק הזרוע, שדינו כגינה, הלא רשות אחת הן ומותר לטלטל כלים באותו מקום, ואין חלק הגינה אוסר על חלק הקרפף.","ודוחים: \u0003לר' שמעון נמי\u0004 \u0005[גם כן]\u0006 \u0003כיון\u0004 ש\u0003נזרע רובו\u0004 של אותו קרפף \u0003הוי ההוא מיעוטא\u0004 \u0005[הרי אותו מיעוט]\u0006"],["\u0003בטיל ליה לגבי\u0004 \u0005[בטל לו אצל]\u0006 \u0003רובה\u0004 של הגינה והרי זה כאילו נזרעה כולה. \u0003והוה ליה\u0004 \u0005[הריהו נעשה]\u0006 כדין \u0003קרפף יותר מבית סאתים — ואסור\u0004 בטלטול כל עיקר.","\u0003אלא אי איתמר\u0004 \u0005[אם נאמר]\u0006 דבר בשם רב הונא בן רב יהושע \u0003הכי איתמר\u0004 \u0005[כך נאמר]\u0006 ונדייק: \u0003הא\u0004 \u0005[הרי]\u0006 אם נזרע \u0003מיעוטא\u0004 \u0005[מיעוט]\u0006 של הקרפף — \u0003שרי\u0004 \u0005[מותר]\u0006 בטלטול. \u0003אמר רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע: לא אמרן\u0004 \u0005[אמרנו]\u0006 \u0003אלא דלא הוי\u0004 \u0005[שאין הוא]\u0006 שיעור המקום הזרוע \u0003בית סאתים, אבל\u0004 אם היה \u0003בית סאתים\u0004 או יותר — \u0003אסור\u0004 הטלטול בכל שטח הקרפף אף על פי שרובו אינו זרוע.","\u0003כמאן\u0004 \u0005[כ\u0006שיטת \u0005מי]?\u0006 \u0003כרבנן\u0004 \u0005[כ\u0006שיטת \u0005חכמים]\u0006 החולקים על ר' שמעון וסוברים שקרפף וחצר אסורים בטלטול מזה לזה.","\u0003ורב ירמיה מדיפתי מתני לקולא\u0004 \u0005[היה שונה\u0006 דבר זה \u0005להקל],\u0006 וכך היה מדייק: דברנו בקרפף שנזרע רובו, \u0003הא מיעוטא\u0004 \u0005[הרי\u0006 אם זרע \u0005מיעוטו] —\u0006 \u0003שרי\u0004 \u0005[מותר],\u0006 \u0003אמר רב הונא בריה [בנו]\u0004 של \u0003רב יהושע: לא אמרן\u0004 \u0005[אמרנו]\u0006 \u0003אלא בית סאתים, אבל יותר מבית סאתים — אסור.\u0004 ו\u0003כמאן\u0004 \u0005[כ\u0006שיטת \u0005מי]?\u0006 \u0003כר' שמעון\u0004.","אמרנו מקודם שאם \u0003נטע\u0004 אילנות ב\u0003רובו\u0004 של הקרפף — \u0003הרי הוא כחצר, ומותר\u0004. \u0003אמר רב יהודה אמר אבימי: והוא שעשויין אצטבלאות\u0004 (שורות) שכך נהוג לנטוע עצים לנוי בחצר. אבל אם היו מסודרים בדרך אחרת הריהם כפרדס שאינו עשוי לדירה, ואסור. \u0003ורב נחמן אמר: אף על פי שאין עשויין אצטבלאות\u0004 דרך לנטוע עצים בכל צורה בחצר הבית.","\u0003מר יהודה אקלע לבי\u0004 \u0005[הזדמן לבית]\u0006 \u0003רב הונא בר יהודה חזנהו להנהו דלא עבידי אצטבלאות, וקא מטלטלי בגוייהו\u0004 \u0005[ראה את אלו\u0006 העצים \u0005שאינם עשויים שורות, ומטלטלים בתוכם].\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 האם \u0003לא סבר לה מר להא דאבימי\u0004 \u0005[אדוני לאותה\u0006 הלכה \u0005זו של אבימי]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אנא\u0004 \u0005[אני]\u0006 \u0003כרב נחמן סבירא לי\u0004 \u0005[אני סבור],\u0006 שאף כשאין עשויים שורות מותר.","\u0003אמר רב נחמן אמר שמואל: קרפף\u0004 ששטחו \u0003יותר מבית סאתים שלא הוקף\u0004 מלכתחילה \u0003לדירה\u0004 ורוצה לעשות בו תיקון שיהא מותר לטלטל בכולו, \u0003כיצד הוא עושה? פורץ בו פירצה יותר מעשר\u0004 אמות, ועל ידי כך נעשה כאילו פירצה גדולה זו מבטלת את המחיצה. \u0003וגודרו\u0004 (את הקרפף), \u0003ומעמידו על\u0004 פירצה של \u0003עשר\u0004 אמות בלבד. \u0003ו\u0004היקף מחודש זה גורם שיהא \u0003מותר\u0004 לטלטל בו.","\u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]\u0006 שאלה זו: מה הדין אם לא עשה פירצה זו בבת אחת, אלא \u0003פרץ אמה וגדר\u0004 מחדש את אותה \u0003אמה, ופרץ אמה וגדרה, עד שהשלימו\u0004, את שיעור ההיקף מחודש, \u0003ליותר מעשר\u0004 אמות. \u0003מהו?\u0004","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003לאו היינו דתנן\u0004 \u0005[האם לא זה ששנינו\u0006 במשנה\u0005]:\u0006 \u0003כל כלי\u0004 עץ של \u0003בעלי בתים\u0004 שנטמאו, \u0003שיעורן\u0004 שתיבטל מהם תורת כלי וייטהרו, ככל כלים שבורים אם יש בהם נקבים, \u0003כ\u0004גודל \u0003רמונים.\u0004","\u0003ובעי\u0004 \u0005[ושאל]\u0006 \u0003חזקיה:\u0004 מה יהא הדין אם \u0003ניקב\u0004 רק נקב \u0003כמוציא זית\u0004 (שזית יכול לצאת בו\u0005)\u0006 \u0003וסתמו, וחזר וניקב\u0004 הכלי \u0003כמוציא זית\u0004 סמוך לנקב ההוא וחזר \u0003וסתמו, עד שהשלימו\u0004 בחשבון כל הנקבים והסתימות לשיעור \u0003כמוציא רמון מהו\u0004 הדין? האם נאמר שהנקבים הללו מצטרפים לנקב אחד, או שמא כיון שלא היו כל הנקבים בשעה אחת אינם מצטרפים?","\u0003ואמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' יוחנן: רבי, שניתה לנו\u0004 מענין זה: \u0003סנדל\u0004 שהוא טמא מדרס \u0003שנפסקה\u0004 (נחתכה) \u0003אחת מאזניו ותיקנה —\u0004 עדיין הריהו \u0003טמא מדרס.\u0004 וטעמו של דבר — שהסנדל אינו בטל מתורת כלי על ידי פסיקת אוזן אחת.","\u0003נפסקה שניה ותיקנה — טהור מן המדרס,\u0004 שבטל ממנו תשמישו. \u0003אבל טמא מגע מדרס\u0004 כאילו היה רק נוגע בדבר שטמא טומאת מדרס.","\u0003ואמרת עלה\u0004 \u0005[עליה],\u0006 על הלכה זו: \u0003מאי שנא\u0004 \u0005[במה שונה]\u0006 פסיקת אוזן \u0003ראשונה\u0004 שאין הכלי ניתר בגללה — \u0003דהא קיימא\u0004 \u0005[שהרי קיימת]\u0006 האוזן ה\u0003שניה,\u0004 כשנקרעה ה\u0003שניה נמי, הא קיימא\u0004 \u0005[גם כן, הרי קיימת]\u0006 ה\u0003ראשונה,\u0004 וכיצד בטל הסנדל מתורת כלי כל עוד יש לו אוזן אחת שלמה?!","\u0003ואמרת לן עלה\u0004 \u0005[לנו עליה],\u0006 \u0003כתשובה: פנים חדשות באו לכאן\u0004 כלומר כיון שתוקנו שתי אוזניו של הסנדל, שוב אין זה הסנדל הישן שנטמא אלא נתחדש והריהו כסנדל אחר, שלא נטמא כלל. \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 בענין כלי שניקב כמוציא רימון נאמר אף אנו \u0003פנים חדשות באו לכאן,\u0004 וכל אותו מקום הנקב חדש הוא לגמרי, וכיון שניקב הכלי בסך הכל כמוציא רימון הריהו טהור.","התפעל חזקיה ו\u0003קרי עליה\u0004 \u0005[קרא עליו\u0006 על ר' יוחנן\u0005]:\u0006 \u0003לית דין בר אינש\u0004 \u0005[אין זה בן אדם\u0006 אלא מלאך\u0005]\u0006 שיכול לפתור בעיה שאני מתקשה בה מדבר שאני עצמי לימדתיו. \u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 שכך אמר: \u0003כגון דין ברנש\u0004 \u0005[זה\u0006 הריהו \u0005בן אדם],\u0006 ומכאן נלמד אף לעניננו שאם גדר ופרץ, גדר ופרץ, עד שהשלים לכשיעור הראוי — הרי זה מועיל, ואין צורך שיפרוץ בבת אחת.","\u0003אמר רב כהנא: רחבה שאחורי הבתים\u0004 שאין הבית פתוח אליה ונוהגים להניח בה חפצים שונים, והמיועדת לדברים שאינם מחייבים שימוש קבוע, אף אם היתה גדורה — אין דינה כחצר ממש ואינה כרשות היחיד גמורה שמותר לטלטל בתוכה, אם שטחה גדול מכבית סאתיים, \u0003אין מטלטלין בו אלא בארבע אמות\u0004 בלבד.","\u0003ואמר רב נחמן: אם פתח לו פתח\u0004 מצד הבית — \u0003מותר לטלטל בכולו,\u0004 שכן \u0003פתח מתירו\u0004 ועושה אותו כחלק מן הבית. \u0003ולא אמרן\u0004 \u0005[אמרנו]\u0006 היתר זה \u0003אלא שפתח ולבסוף הוקף\u0004 בגדר, \u0003אבל הוקף ולבסוף פתח — לא.\u0004","ומקשים: \u0003פתח ולבסוף הוקף פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]\u0006 שהרי בודאי היקף רחבה זו לצורך הפתח נעשתה, ומשיבים: \u0003לא צריכא דאית ביה בי דרי\u0004 \u0005[לא נצרכה\u0006 אלא כגון \u0005שיש בה גורן],\u0006 \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 פתח זה \u0003אדעתא דבי דרי עבדיה\u0004 \u0005[על דעת הגורן עשאו],\u0006 ולא לשם הרחבה כולה, על כן השמיע לנו שהפתח מתיר את הרחבה בכל מקרה.","\u0003קרפף יותר מבית סאתים שהוקף לדירה, ו\u0004אולם \u0003נתמלא מים\u0004 בשיטפון או בדרך אחרת, \u0003סבור רבנן למימר\u0004 \u0005[סברו חכמים לומר]\u0006 שהמים \u0003כזרעים דמו\u0004 \u0005[הם נחשבים] —\u0006 \u0003ואסיר\u0004 \u0005[ואסור]\u0006 הקרפף בטלטול. שביטלוהו המים מדירה, כי אין זה רגיל לדור במקום המלא מים.","\u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003רב אבא אבוה\u0004 \u0005[אביו]\u0006 של \u0003רב בריה\u0004 \u0005[בנו]\u0006 של \u0003רב משרשיא: הכי אמרינן משמיה דרבא\u0004 \u0005[כך אומרים אנו משמו של רבא]:\u0006 \u0003מים כנטעים דמו\u0004 \u0005[הם נחשבים],\u0006 \u0003ושרי\u0004 \u0005[ומותרים].\u0006 שחצר שיש בה מים, ראויה לדירה, שהמים מועילים לדרי החצר."],["\u0003אמר אמימר: והוא דחזיין לתשמישתא\u0004 \u0005[שראויים\u0006 המים \u0005לשימוש\u0006 שלהם, כלומר לשתייה\u0005],\u0006 שמשום כך הריהם מוסיפים לצורכי הדירה, \u0003אבל\u0004 אם הם \u0003לא חזיין לתשמישתא\u0004 \u0005[ראויים לשימוש\u0006 שלהם\u0005] —\u0006 \u0003לא,\u0004 שאינם נחשבים כנטיעה ומבטלים את הקרפף מהיותו כמוקף לדירה ואסור בטלטול.","\u0003אמר רב אשי: ודחזיין לתשמישתא נמי לא אמרן\u0004 \u0005[ו\u0006כאשר \u0005ראויים\u0006 המים \u0005לשימוש גם כן לא אמרנו]\u0006 \u0003אלא שאין בעומקו יותר מבית סאתים, אבל אם יש בעומקו\u0004 במקום שהמים מגיעים בו לעומק של עשרה טפחים \u0003יותר\u0004 משטח של \u0003בית סאתים — אסור\u0004. שעל ידי כך בטלה החצר מהיותה מוקפת לדירה.","ומעירים: \u0003ולאו מילתא היא\u0004 \u0005[ואין זה דבר\u0006 נכון\u0005],\u0006 \u0003מידי דהוה אכריא דפירי\u0004 \u0005[כשם שהוא\u0006 ביחס \u0005לכרי של פירות]\u0006 שאף אם כרי הפירות גדול ורחב ביותר אינו מבטל את החצר.","מסופר: \u0003ההיא\u0004 \u0005[אותה]\u0006 \u0003רחבה, דהואי\u0004 \u0005[שהיתה]\u0006 \u0003ב\u0004עיר \u0003פום נהרא, דחד גיסא הוה פתיח למתא, וחד גיסא הוה פתיח\u0004 \u0005[שצידה האחד היה פתוח לעיר, וצידה האחד היה פתוח]\u0006 \u0003לשביל של כרמים\u0004 שהיו דרים בו. \u0003ו\u0004אותו \u0003שביל של כרמים הוה סליק לגודא דנהרא\u0004 \u0005[היה מגיע לחוף הנהר].\u0006","\u0003אמר אביי: היכי נעביד\u0004 \u0005[כיצד נעשה]\u0006 לתקן שיהא מותר לטלטל ברחבה זו בלא לפרוץ בה פירצה הרחבה מעשר אמות ולגודרה מחדש? אם \u0003לעביד ליה\u0004 \u0005[נעשה לה]\u0006 \u0003מחיצה אגודא דנהרא\u0004 \u0005[על שפת הנהר]\u0006 ועל ידי כך יהא שביל הכרמים מוקף במחיצות מכל צד. ואולם הלא \u0003אין עושין מחיצה על גבי מחיצה,\u0004 וחוף הנהר הריהו כמחיצה לגבי הנהר.","\u0003ו\u0004אם \u0003לעביד ליה\u0004 \u0005[נעשה לה]\u0006 \u0003צורת הפתח אפומא\u0004 \u0005[על פי]\u0006 \u0003שביל של כרמים,\u0004 גם זה לא יוכל להועיל במקרה שלנו, כי \u0003אתו גמלי שדיין ליה\u0004 \u0005[באים הגמלים\u0006 המהלכים דרך רחבה זו כדי לשתות מים מן הנהר \u0005ומפילים אותו]\u0006 את צורת הפתח.","\u0003אלא אמר אביי\u0004 שיש להשתמש בתקנה זו: \u0003לעביד\u0004 \u0005[שיעשו]\u0006 \u0003לחי אפיתחא\u0004 \u0005[על פתח]\u0006 \u0003שביל של כרמים, דמגו דמהניא\u0004 \u0005[שמתוך שמועיל]\u0006 \u0003לשביל של כרמים\u0004 לטלטל בו, שעתה שוב אינו פרוץ לכרמלית, \u0003מהני נמי\u0004 \u0005[מועיל גם כן]\u0006 \u0003לרחבה,\u0004 ויחשב הלחי כמחיצה נוספת המתירה את הרחבה.","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003רבא:\u0004 אם כך, \u0003יאמרו לחי מועיל\u0004 להתיר \u0003לשביל של כרמים דעלמא\u0004 \u0005[\u0006בכלל, \u0005סתם]\u0006 ונביא את הרבים להיכשל בדבר זה. שהרי בדרך כלל הינו מפולש ואינו פתוח לנהר וכדומה.","\u0003אלא אמר רבא: עבדינן ליה\u0004 \u0005[עושים אנו]\u0006 \u0003לחי לפיתחא דמתא\u0004 \u0005[לפתח העיר],\u0006 \u0003דמגו דמהני ליה\u0004 \u0005[שמתוך שמועיל לה]\u0006 ה\u0003לחי למתא\u0004 \u0005[לעיר]\u0006 להיחשב כמחיצה\u0005,\u0006 \u0003מהני נמי\u0004 \u0005[מועיל גם כן]\u0006 \u0003לרחבה\u0004 להתירה בטלטול.","\u0003הלכך\u0004 נוכל לסכם; \u0003טלטולי במתא גופה\u0004 \u0005[טלטול בעיר עצמה] —\u0006 \u0003שרי\u0004 \u0005[מותר],\u0006 \u0003טלטולי ברחבה גופה\u0004 \u0005[טלטול ברחבה עצמה] —\u0006 \u0003שרי\u0004 \u0005[מותר]\u0006 אולם; \u0003ממתא\u0004 \u0005[מן העיר]\u0006 \u0003לרחבה ומרחבה למתא\u0004 \u0005[לעיר]\u0006 \u0003פליגי\u0004 \u0005[נחלקו]\u0006 \u0003בה רב אחא ורבינא; חד\u0004 \u0005[אחד]\u0006 \u0003אסר וחד\u0004 \u0005[ואחד]\u0006 \u0003שרי\u0004 \u0005[התיר].\u0006"],["\u0003מאן דשרי\u0004 \u0005[מי שמתיר]\u0006 טעמו הוא — \u0003דהא ליכא\u0004 \u0005[שהרי אין]\u0006 \u0003דיורין\u0004 ברחבה, ובמקום שאין בו דיורים אינו יכול לאסור על רשות אחרת הסמוכה לו. \u0003ומאן דאסר\u0004 \u0005[ומי שאוסר]\u0006 טעמו הוא — \u0003זימנין דהוי\u0004 \u0005[פעמים שיש]\u0006 \u0003בה דיורין\u0004 היכולים לאסור על בני רשות אחרת \u0003ואתי לטלטולי\u0004 \u0005[ויבוא לטלטל]\u0006 באיסור מרחבה לעיר.","\u0003קרפף\u0004 ששטחו \u0003יותר מבית סאתים שלא הוקף\u0004 מתחילה \u0003לדירה ובא למעטו\u0004 משטח זה, \u0003מיעטו באילנות\u0004 שנטע בו — \u0003לא הוי\u0004 \u0005[אינו]\u0006 \u0003מיעוט\u0004 משום שרגיל שיהיו אילנות בקרפף העשוי לדירה ואינם נחשבים כדבר שונה הממעט משטחו.","ואולם, \u0003בנה בו עמוד גבוה עשרה ורחב ארבעה\u0004 טפחים — \u0003הוי\u0004 \u0005[הריהו]\u0006 \u0003מיעוט\u0004 שאם נעשה על ידי כך שטח הקרפף עד כבית סאתיים, מותר לטלטל בו. אולם אם היה העמוד רחב \u0003פחות משלשה\u0004 טפחים — \u0003לא הוי\u0004 \u0005[אינו]\u0006 \u0003מיעוט\u0004. \u0003משלשה ועד ארבעה\u0004 טפחים — נחלקו בדבר. \u0003רבה אמר: הוי\u0004 \u0005[הריהו]\u0006 \u0003מיעוט, ורבא אמר: לא הוי\u0004 \u0005[אינו]\u0006 \u0003מיעוט.\u0004","ומסבירים את השיטות. \u0003רבה אמר: הוי\u0004 \u0005[הריהו]\u0006 \u0003מיעוט — דהא נפיק ליה\u0004 \u0005[שהרי יצא לו]\u0006 כבר בגודלו \u0003מתורת לבוד\u0004 שהוא בשלשה טפחים, וכיון ששטח כזה אינו נדון כצמוד למקום אחר הרי שטח חשוב הוא, ואם כן יפה כוחו אף למעט. \u0003רבא אמר\u0004: \u0003לא הוי\u0004 \u0005[אינו]\u0006 \u0003מיעוט, כיון דלא הוי\u0004 \u0005[שאין הוא]\u0006 \u0003מקום\u0004 של \u0003ארבעה\u0004 טפחים \u0005—\u0006 \u0003לא חשיב\u0004 \u0005[אינו חשוב],\u0006 שבפחות מארבעה טפחים אינו קרוי מקום.","ועוד אמרו: \u0003הרחיק מן הכותל\u0004 הקיים בקרפף \u0003ארבעה\u0004 טפחים \u0003ועשה מחיצה\u0004 אחרת — \u0003הועיל\u0004 לתקן את השטח הגדור במחיצה הפנימית. אולם אם הרחיק \u0003פחות משלשה\u0004 טפחים — \u0003לא הועיל,\u0004 שהרי הכותל החדש נחשב כלבוד לראשון והרי הוא כמחיצה על גבי מחיצה. \u0003משלשה\u0004 טפחים \u0003ועד ארבעה\u0004 טפחים — נחלקו חכמים. \u0003רבה אמר: הועיל, רבא אמר: אינו מועיל.\u0004 ומסבירים את השיטות.","\u0003רבה אמר: הועיל — דהא נפיק ליה\u0004 \u0005[שהרי יצא לו]\u0006 \u0003מתורת לבוד. רבא אמר: אינו מועיל, כיון דלא הוי\u0004 \u0005[שאין הוא]\u0006 \u0003מקום ארבעה\u0004 טפחים, \u0003לא חשיב\u0004 \u0005[אינו חשוב].\u0006","\u0003רב שימי מתני\u0004 \u0005[היה שונה]\u0006 מחלוקת זו \u0003לקולא\u0004 \u0005[להקל],\u0006 ולדעתו שלושה טפחים די בהם כדי למעט חצר בעמוד וכדי לעשות את המחיצה הסמוכה לחברתה כמחיצה למעט את החצר ולהכשירה, ולא חלקו אלא בפחות משלשה טפחים. ועוד אמרו: \u0003טח בו\u0004 בכותלי אותו קרפף הגדול מבית סאתיים \u0003טיט, ויכול\u0004 הטיט \u0003לעמוד בפני עצמו\u0004 — \u0003הוי\u0004 \u0005[הריהו]\u0006 \u0003מיעוט\u0004 שהרי זה כאילו עשה מחיצה חדשה. אולם אם הטיט \u0003אינו יכול לעמוד בפני עצמו\u0004 ועמידתו רק משום שהוא דבוק לכותל — \u0003רבה אמר\u0004: \u0003הוי\u0004 \u0005[הריהו]\u0006 \u0003מיעוט,\u0004 ו\u0003רבא אמר\u0004: \u0003לא הוי\u0004 \u0005[אין הוא]\u0006 \u0003מיעוט.\u0004","ומסבירים את השיטות. \u0003רבה אמר: הוי\u0004 \u0005[הריהו]\u0006 \u0003מיעוט, השתא מיהא קאי\u0004 \u0005[עכשיו בכל אופן הוא עומד].\u0006 \u0003רבא אמר: לא הוי\u0004 \u0005[אין הוא]\u0006 \u0003מיעוט, כיון\u0004 ש\u0003לא יכול למיקם\u0004 \u0005[לעמוד]\u0006 \u0003בפני עצמו, לא כלום הוא.\u0004","וכן \u0003הרחיק מן התל\u0004 הגבוה מעשרה טפחים, שהיה בתוך הקרפף ורחוק ממחיצתו יותר מכבית סאתיים, והרחב מארבעה טפחים וגבוה \u0003ארבעה\u0004 טפחים \u0003ועשה מחיצה — הועיל\u0004 לכל החצר.","עשאה \u0003פחות משלשה או על שפת התל,\u0004 ונעשית כמחיצה על גבי מחיצה, \u0003רב חסדא ורב המנונא\u0004 נחלקו בכך. \u0003חד\u0004 \u0005[אחד]\u0006 מהם \u0003אמר: הועיל\u0004, \u0003וחד\u0004 \u0005[ואחד]\u0006 מהם \u0003אמר: לא הועיל.\u0004","מתחילה לא נמסר לנו מה היתה דעתו של כל אחד מן החכמים, ומעירים: \u0003תסתיים\u0004 (תוגדר) ש\u0003רב חסדא\u0004 הוא זה ש\u0003אמר הועיל\u0004, \u0003דאתמר\u0004 \u0005[ש\u0006כן \u0005נאמר]\u0006 שנחלקו אמוראים: \u0003העושה מחיצה על גבי מחיצה\u0004 קיימת, \u0003אמר רב חסדא ב\u0004ענין \u0003שבת\u0004 אם המחיצה הראשונה היתה שלא לשם היקף דירה — \u0003הועיל,\u0004 ומחיצתו השניה מחיצה היא.","\u0003בנכסי הגר — לא קנה.\u0004 שנכסי הגר שמת בלא יורשין נעשים הפקר, אם לא נתנם בחייו מתנה למי שהוא. ונכסים אלה כל הקונה אותם ראשונה — זכה בהם. אחד מאופני הקנייה הוא עשיית מחיצה, ואמרו חכמים שאם עשה בנכסי הגר שמת מחיצה על גבי מחיצה קיימת — לא קנה בכך את הנכסים.","\u0003ורב ששת אמר: אף בשבת נמי\u0004 \u0005[גם כן]\u0006 \u0003לא הועיל\u0004. ומעירים: אכן, \u0003תסתיים\u0004 (תוגדר) שרב חסדא הוא שסבור שמחיצה על גבי מחיצה מועילה.","\u0003אמר רב חסדא: ומודה לי רב ששת שאם עשה מחיצה על התל\u0004 שיש בו כבית סאתיים ולא בסמוך לו בלבד — \u0003שהועיל\u0004 להתיר את הטלטול בתוך התל עצמו, אף על פי שהחצר עצמה אסורה בטלטול.","\u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 \u0003— הואיל ובאויר\u0004 (בחלל\u0005)\u0006 \u0003המחיצות העליונות הוא דר\u0004 ונמצא שמחיצות חדשות אלה יש בהן עבורו שימוש ויש להן תפקיד, ואף שלגבי העומד למטה מן התל הרי אלו מחיצות על גבי מחיצת התל הקיימת, ואינן מתירות את הטלטול בקרפף עצמו, מכל מקום לטלטול בתוך התל עצמו הועילו.","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רבה בר בר חנה: נבלעו מחיצות התחתונות,\u0004 כגון שטבעו באדמת בוץ, ומחיצות \u0003העליונות\u0004 שעשה \u0003קיימות, מהו\u0004 דינן?","ושואלים \u0003למאי\u0004 \u0005[למה,\u0006 לאיזה ענין נשאלה השאלה\u0005]?\u0006 \u0003אי\u0004 \u0005[אם]\u0006 \u0003ל\u0004ענין \u0003נכסי הגר, היינו\u0004 \u0005[\u0006הלא \u0005זוהי]\u0006 ההלכה שאמר \u0003ירמיה ביראה,\u0004 ש\u0003אמר ירמיה ביראה אמר רב יהודה: האי מאן דשדא ליפתא אפילא דארעא דגר, ואתא ישראל אחרינא רפק בה פורתא, בתרא קני, קמא לא קני\u0004 \u0005[מי שזרע\u0006 זרע \u0005לפת על סדקי האדמה של גר, ובא\u0006 אדם \u0005אחר מישראל\u0006 ו\u0005עדר בה מעט\u0006 באותה האדמה, \u0005האחרון\u0006 העודר \u0005—\u0006 \u0005קנה, הראשון —\u0006 \u0005לא קנה]\u0006.","\u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]\u0006 שלא קנה הזורע? \u0003בעידנא דשדא\u0004 \u0005[בזמן שזרע] —\u0006 הרי \u0003לא קא שבח\u0004 \u0005[הושבחה]\u0006 הקרקע בזריעה. \u0003כי קא שבחא\u0004 \u0005[כאשר הושבחה]\u0006 בגדילת הלפת — \u0003ממילא קא משבחא\u0004 \u0005[מעצמה היא משביחה].\u0006 כלומר, מעשה הזריעה בלבד אינו מעשה ניכר שיש בו כדי לשנות ולהועיל לנכס בשעתו. ואף על פי שיש בו תועלת לאחר זמן, הרי זו תועלת הבאה כאילו מעצמה בקרקע, ולכן, פעולה שתועלתה רק בעתיד אין בה משום מעשה קנין.","\u0003ואלא\u0004 תאמר ששאל \u0003לענין שבת,\u0004 והרי זו \u0003מחיצה הנעשה בשבת\u0004 שהרי קודם לכן לא היתה זו להלכה מחיצה, ומכיון שנבלעו המחיצות התחתונות נעשתה העליונה חשובה כמחיצה.","\u0003ו\u0004אף דבר זה \u0003תניא\u0004 \u0005[\u0006כבר \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003כל מחיצה הנעשה בשבת, בין בשוגג בין במזיד — שמה מחיצה.\u0004 ואם כן מחיצות העליונות נעשו מחיצות כדינן.","ומקשים: \u0003לאו איתמר עלה\u0004 \u0005[\u0006וכי \u0005לא נאמר עליה]\u0006 \u0003אמר רב נחמן: לא שנו\u0004 ענין זה שדינה כמחיצה \u0003אלא\u0004 לאסור \u0003לזרוק\u0004 ממנה לרשות הרבים ולהיפך, \u0003אבל לטלטל\u0004 בתוכה כברשות היחיד — \u0003אסור\u0004. משמע שאין אלה מחיצות גמורות.","ודוחים: \u0003כי איתמר\u0004 \u0005[כאשר נאמרה]\u0006 הלכה זו של \u0003רב נחמן — אמזיד איתמר\u0004 \u0005[על\u0006 ענין \u0005מזיד נאמרה],\u0006 שאם עשה בשבת מחיצה במזיד קנסו שלא ישתמש בה בשבת.","בדומה לעניננו מסופר: \u0003ההיא איתתא דעבדה\u0004 \u0005[אשה אחת שעשתה]\u0006 \u0003מחיצה על גבי מחיצה בנכסי הגר. אתא ההוא גברא, רפק\u0004 \u0005[בא אדם אחד, עדר]\u0006 \u0003בה פורתא\u0004 \u0005[מעט].\u0006 \u0003אתא לקמיה\u0004 \u0005[בא\u0006 אותו איש \u0005לפני]\u0006 \u0003רב נחמן, אוקמא בידיה\u0004 \u0005[\u0006ו\u0005העמיד\u0006 את השדה \u0005בידו].\u0006 \u0003אתת איהי וקא צווחא קמיה\u0004 \u0005[באה היא\u0006 האשה \u0005וצוחה לפני]\u0006 רב נחמן. \u0003אמר לה: מאי איעביד לך, דלא מחזקת כדמחזקי אינשי\u0004 \u0005[מה אעשה לך, שאין\u0006 את \u0005מחזיקה\u0006 בדבר \u0005כ\u0006פי \u0005שאנשים\u0006 עושים \u0005חזקה].\u0006","היה \u0003קרפף\u0004 ששטחו \u0003בית שלש\u0004 סאים \u0003וקירה בו\u0004 חלק שהוא \u0003בית סאה\u0004, ואם כן יש מקום לדון האם אפשר לומר שעכשיו יש בו בית סאתיים בלבד ומותר לטלטל בקרפף, או לא. \u0003רבא אמר: אויר קירויו מייתרו\u0004 (מוסיף בו) על מידת בית סאתיים, שאין הקירוי נחשב נפרד מן השאר. \u0003ור' זירא אמר: אין אויר קירויו מייתרו,\u0004 ומותר.","ומעירים: \u0003לימא\u0004 \u0005[האם לומר]\u0006 ש\u0003רבא ור' זירא בפלוגתא\u0004 \u0005[במחלוקת]\u0006 של \u0003רב ושמואל קא מיפלגי\u0004 \u0005[נחלקו].\u0006 \u0003דאתמר\u0004 \u0005[ש\u0006כן \u0005נאמר]\u0006 שנחלקו בכך: היתה \u0003אכסדרה\u0004 מבנה מקורה ללא מחיצות, או ללא מחיצות שלמות, בתוך \u0003בקעה\u0004 שדינה ככרמלית, \u0003רב אמר: מותר לטלטל ב\u0004אכסדרה \u0003כולה\u0004 שהיא כרשות היחיד. \u0003ושמואל אמר: אין מטלטלין אלא בארבע אמות.\u0004 ומסבירים את השיטות.","\u0003רב אמר: מותר לטלטל\u0004 באכסדרה \u0003כולה\u0004 כי \u0003אמרינן\u0004 \u0005[אומרים אנו]\u0006 \u0003פי תקרה יורד וסותם,\u0004 שתקרת האכסדרה נחשבת כיורדת עד למטה ונעשית כמחיצה הסותמת את האכסדרה מכל צדדיה והריהי כולה רשות היחיד לעצמה. \u0003ושמואל אמר: אין מטלטלין אלא בארבע אמות,\u0004 כי \u0003לא אמרינן\u0004 \u0005[אין אנו אומרים]\u0006 \u0003פי תקרה יורד וסותם.\u0004"],["\u0003אי דעבידא\u0004 \u0005[אם שעשוי]\u0006 הגג באותו חלק מקורה \u0003כי\u0004 \u0005[כמו]\u0006 \u0003אכסדרה\u0004 שקירויה ישר \u0003— הכי נמי\u0004 \u0005[כך גם כן]\u0006 מודים הכל שפי תקרה יורד וסותם. \u0003הכא במאי עסקינן, דעבדה כי אורזילא\u0004 \u0005[כאן במה אנו עוסקים, שעשויה\u0006 התקרה \u0005בשיפוע]\u0006 ואין איפוא לומר פי תקרה סותם.","\u0003אמר ר' זירא: ומודינא\u0004 \u0005[ומודה אני]\u0006 \u0003בקרפף שנפרץ במלואו לחצר — שאסור. מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 \u0003הואיל ואויר חצר\u0004 הנוסף ומצטרף לקרפף \u0003מייתרו\u0004 ועושהו גדול מבית סאתים, ואסור מעתה בטלטול.","\u0003מתקיף לה\u0004 \u0005[מקשה עליה,\u0006 על דעה זו\u0005]\u0006 \u0003רב יוסף: וכי אויר המותר לו — אוסרו?\u0004 הרי מותר היה עוד קודם לכן לטלטל מן החצר לקרפף, ומדוע נאמר שאם מתווסף חלל (אויר), שמותר היה מעיקרו, יאסור עתה כשנפרצה מחיצתו?!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: כמאן\u0004 \u0005[כמי]\u0006 אומר אתה דבר זה? \u0003כ\u0004שיטת \u0003ר' שמעון\u0004 שלדעתו מותר לטלטל מן הקרפף לחצר בכל עת. ואולם \u0003לר' שמעון נמי הא איכא\u0004 \u0005[גם כן הרי יש]\u0006 \u0003אויר\u0004 (חלל) ב\u0003מקום מחיצות\u0004 שנפלו והשאירו אחריהן חלל פנוי, וחלל זה אפילו לדעת ר' שמעון לא היה ראוי מתחילה לטלטל בו וכיון שכך, אם היה הקרפף מלכתחילה רק כבית סאתיים בדיוק, הרי משום תוספת חלל המחיצות — נאסר כל הקרפף.","וכעין זה \u0003אמר רב חסדא\u0004 בענין אחר: \u0003קרפף שנפרץ במלואו לחצר\u0004 שכל הכותל בינו ובין החצר נפרץ — \u0003חצר מותרת וקרפף אסור.\u0004","ושואלים: \u0003חצר מאי טעמא\u0004 \u0005[מה טעם]\u0006 מותרת? משום \u0003דאית ליה גיפופי\u0004 \u0005[שיש לה שרידי מחיצות]?\u0006 \u0003והא זימנין דמשכחת לה איפכא\u0004 \u0005[והרי פעמים שמוצא אתה אותה להיפך];\u0006 שאם היתה החצר צרה מן הקרפף, ונפרצה המחיצה ביניהם במלואה, נשארו לקרפף שרידי מחיצות, והחצר תהא פרוצה כולה.","\u0003אלא, משום דאמרינן\u0004 \u0005[שאנו אומרים]\u0006 \u0003זה\u0004 הקרפף שאינו ממש מוקף לדירה ואינו מותר אלא בבית סאתיים — \u0003אויר מחיצות\u0004 שנפלו \u0003מייתרו\u0004 ועושה אותו גדול משיעור בית סאתים, \u0003וזה\u0004 החצר — \u0003אין אויר מחיצות מייתרו,\u0004 שהרי חצר המוקפת לדירה אין בה הגבלה של שיעור שטח מסויים שלמעלה ממנו תהא נאסרת.","בעיה קצת דומה לענין מחיצות ואוירן מובאת במעשה שהיה: \u0003ההוא בוסתנא דהוה סמיך לגודא דאפדנא\u0004 \u0005[בוסתן אחד שהיה סמוך לכותל הארמון]\u0006 והיה משמש גם כמחיצה חיצונית לגן זה, ששטחו היה יתר מבית סאתים, ועל ידי מחיצה זו — מוקף לדירה. \u0003נפל אשיתא ברייתא דאפדנא\u0004 \u0005[נפל הקיר החיצון של הארמון]\u0006 ששימש גם ככותל לבוסתן. \u0003סבר רב ביבי למימר\u0004 \u0005[לאמר]\u0006 שאפשר \u0003ליסמוך אגודא גוויתא\u0004 \u0005[על הכותל הפנימי]\u0006 של הארמון שישמש כמחיצה לבוסתן ויהא מותר גם הלאה לטלטל בו.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב פפי: משום דאתו ממולאי אמריתו מילי מולייאתא\u0004 \u0005[שאתם באים מן הקטועים, אומרים אתם דברים מקוטעים]\u0006 (שהיה רב ביבי מתייחס לבני עלי שנתקללו כי ימותו רובם בצעירותם (שמואל א' ב, לג), ומשום כך אמר לו בסגנון זה), שהרי אין לסמוך כלל על הקיר הפנימי. \u0003הנך\u0004 \u0005[אלה]\u0006 ה\u0003מחיצות\u0004 של הארמון, \u0003לגואי\u0004 \u0005[לפנים] —\u0006 \u0003עבידן\u0004 \u0005[עשויות],\u0006 \u0003לבראי\u0004 \u0005[לחוץ] —\u0006 \u0003לא עבידן\u0004 \u0005[אינן עשויות]\u0006 ולא נועדו מתחילה לשמש מחיצה גם לגן.","מסופר: \u0003ההיא אבוורנקא דהוה ליה לריש גלותא בבוסתניה\u0004 \u0005[אילן אחד העשוי לצל שהיה לו לראש הגולה בגנו\u0006 פרדסו\u0005]\u0006 והיה אותו בוסתן כקרפף יתר מבית סאתים שלא הוקף לדירה. \u0003אמר ליה\u0004 \u0005[לו]\u0006 ראש הגולה \u0003לרב הונא בר חיננא: לעביד מר תקנתא, דלמחר נאכול נהמא התם\u0004 \u0005[שיעשה אדוני תיקון שלמחר\u0006 בשבת \u0005נאכל לחם שם].\u0006 כלומר, שאפשר יהיה לטלטל מן הבית אל האילן הזה מאכלים וכלים.","\u0003אזל עבד\u0004 \u0005[הלך עשה]\u0006 \u0003קנה קנה פחות משלשה,\u0004 שתי מחיצות שביניהן שביל ובין מחיצות אלה יוכלו לעבור ולטלטל, שהרי הן נעשו לצורך דירה, כראוי, \u0003אזל\u0004 \u0005[הלך]\u0006 \u0003רבא\u0004"]]};
